/* ÇEVİRİ ja · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ja","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["ハドラマウトがオスマンのサンジャクとなる — 内部統治はカスィーリー家の首長に残る", "d80f8d20"], "d": ["ハディム・スレイマン・パシャのインド遠征の際にオスマン統治に入ったハドラマウトは、イエメンに属するサンジャクとして組織された。しかしハドラマウトの内部では、統治を実際に握っていたのはカスィーリー部族の首長たちであった。オスマンの支配は、沿岸と税による結びつきにとどまった。", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["ザイド派イマーム・ムタワッキル・アラッラーがハドラマウトを侵攻 — カスィーリー・スルタン国がイエメンのイマーム制に従属", "21ad9c85"], "d": ["オスマンの1635年のイエメンからの撤退の後に強まったザイド派イマーム制は、イマーム・ムタワッキル・アラッラーの時代に軍を送ってハドラマウトに侵攻した。カスィーリー家の内ハドラマウトにおける支配は、こうして半世紀近くにわたりイエメンのイマーム制に従属した。18世紀前半にイマームたちとカスィーリー家の影響力が弱まると、統治は再び現地の部族に移った。", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["アブドゥッラー・ブン・ラシードがハーイル首長国をイブン・アリー家から奪う — シャンマル(ラシード家)首長国の成立", "357cc1a0"], "d": ["シャンマル部族の最大の支族アブデに属するアブドゥッラー・ブン・ラシードは、兄弟のウバイドとともに、ハーイルを治めるイブン・アリー家に対して始めた闘争に1835年に勝って首長国を手にした。ハーイルは、メソポタミアとヒジャーズを結ぶ交易路・巡礼路上の位置により、ラシード家の1921年まで続くジャバル・シャンマル支配の中心となった。", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["オスマン侯国の成立", "9f0b7c0a"], "d": ["カユ部族出身のオスマン・ガーズィーがソユト＝ドマニチ周辺で独立して行動し始めたことが、オスマン国家成立の伝統的な起点とされる。一部の歴史家は、1302年のバフェウスの勝利を真の転換点とみなす。侯国はビザンツ帝国との境界地帯に位置したため、ガザー（聖戦）の襲撃を通じて急速に力を蓄えた。ルーム・セルジューク朝の遺産が解体していくこの状況の中で、オスマン・ガーズィーの周囲にはアヒー、ガーズィー、遊牧トルクメンが集まった。シェイフ・エデバリとの結びつきは、侯国の精神的な正統性の基礎とされる。同じ日に加わったその他の地：イネギョル、ヤルヒサル。", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["ブルサの征服", "98c727fa"], "d": ["長年封鎖されていたブルサは、包囲の最終段階を指揮したオルハン・ガーズィーに降伏した。この都市は侯国最初の大きな首都となった。征服の知らせは、臨終の床にあったオスマン・ガーズィーに伝えられたと伝えられ、オスマン・ガーズィーは遺言によりブルサに埋葬された。都市は短期間のうちにモスク、イマーレット（慈善施設）、マドラサを備え、初期オスマン都市建設の模範となった。", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["イズニクの征服", "a846a811"], "d": ["ビザンツ帝国のアナトリアにおける最重要拠点の一つであったイズニク（ニカイア）は、1329年のペレカノンの勝利の後、抵抗の望みを失ってオルハン・ガーズィーに降伏した。最初のオスマン朝のマドラサがここに設立され、ダーヴード・イ・カイセリーのような学者が講義を始めた。都市は初期の学問の中心となった。アヤソフィア教会はモスクに転用され、征服の伝統の初期の一例が示された。", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["イズミットの征服", "06a35035"], "d": ["イズミット（ニコメディア）の陥落により、ビザンツ帝国のアナトリア側における最後の重要な城塞もオスマン朝の支配下に入った。イスタンブルの対岸に至るまでのコジャエリ半島全域がオスマン領となった。こうして侯国はマルマラ海の南岸と東岸の全域を掌握し、ルメリアへの進出の基盤を整えた。", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["チンペ城塞 — ルメリアへの渡海", "c2f0a07d"], "d": ["オルハン・ガーズィーの子スレイマン・パシャは、ビザンツ帝国の内戦の中で与えられたチンペ城塞を1352年に拠点とした。1354年3月にゲリボルを破壊した大地震の後、空いた城塞が速やかに強化され、半島は恒久的なオスマン朝の橋頭堡となった。アナトリアから連れてこられたトルクメン人口の入植に支えられたこの一歩は、オスマン朝のヨーロッパ大陸における550年を超える存在の始まりである。", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["エディルネの征服", "2f54ebb0"], "d": ["トラキアの要衝エディルネ（アドリアノープル）の占領は、バルカン征服の主要な拠点と方向を決定した。征服の年代は史料で1361年から1369年の間で議論がある。都市は間もなく首都とされ、国家の重心がルメリアへ移ったことを示した。イスタンブル征服まで約90年間、都であり続けた。", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["ムラト1世の即位", "f8d48a26"], "d": ["オルハン・ガーズィーの死により即位したムラト1世（Hüdavendigâr）は、27年に及ぶ治世のうちに国家を辺境の侯国から帝国の骨格へと押し上げた。ペンチク制によりイェニチェリ軍団の基礎が築かれ、ティマール制が広められ、ルメリア・ベイレルベイリクが設けられ、宰相制度が強化された。バルカン征服は彼の時代に体系的な国家政策となった。", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["第1次コソヴォの戦い — ムラト1世の殉教", "10b8ddc9"], "d": ["クネズ・ラザル率いるバルカン同盟軍はコソヴォの野で決定的な敗北を喫し、セルビアはオスマン朝の宗主権下に入った。戦場を巡っていたムラト1世は、セルビアの貴族ミロシュ・オビリッチに短剣で刺されて殉教した。戦場で死んだ唯一のオスマン朝スルタンである。陣営でイルドゥルム・バヤジトが後継に据えられ、弟ヤクブ・チェレビは絞殺された。これは兄弟殺しの慣行の知られる最初の例の一つとなった。", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["ニコポリスの勝利", "75716e96"], "d": ["ハンガリー王ジギスムントの呼びかけで集結し、フランス・ブルゴーニュの騎士も加わった大十字軍は、ドナウ河畔のニコポリスでイルドゥルム・バヤジトに大敗した。この勝利はブルガリアに対するオスマン朝の支配を確定させ、ヨーロッパでは一世代の間、大規模な十字軍が組織されなかった。", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["アンカラの戦い — 空位時代の始まり", "b4a99d96"], "d": ["ティムールの軍に対しチュブク平原で喫した大敗でイルドゥルム・バヤジトは捕虜となり、数か月後に捕囚の身で没した。ティムールはアナトリアの諸侯国を復活させ、オスマン領はバヤジトの息子たちの間で分割され、11年続く王位争い（空位時代）が始まった。国家の成立以来最も深刻な危機であったこの時期は、中央集権的な体制の重要性をオスマン朝の記憶に刻んだ。同じ日に失われたその他の集落：Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofya, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Niğbolu, Rusçuk, Selanik, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia)。", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["チェレビ・メフメトによる統一の再建", "03413dfd"], "d": ["兄弟間の最後の決着でムーサー・チェレビをチャムルルで破ったメフメト1世は、国土を単一の統治の下に再統合した。そのため「国家の第二の創建者」とみなされる。治世において、傷んだ国家機構が修復され、アナトリアの諸侯国との関係が均衡され、ルメリアでは慎重な平和政策が取られた。", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["シェイフ・ベドレッディンの反乱", "e0a072ca"], "d": ["空位時代にカザスケル（軍司法官）を務めた大法学者・神秘主義者シェイフ・ベドレッディンの周囲に生じた宗教的・社会的運動は、カラブルンでのベルクリュジェ・ムスタファ、マニサでのトルラク・ケマルの蜂起と同時に勃発した。反乱は血なまぐさく鎮圧され、ベドレッディンはデリオルマンで捕らえられ、セレスで処刑された。この出来事は、オスマン史における最初期の大規模な社会的・マフディー主義的蜂起として、文学と歴史叙述に深い痕跡を残した。", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["ヴァルナの勝利", "f739eedc"], "d": ["セゲド条約を破って南下したハンガリー・ポーランドの十字軍は、退位していたが軍の指揮に戻ったムラト2世によってヴァルナで壊滅させられ、若き王ヴワディスワフ3世は戦場で死んだ。この勝利は、バルカンにおけるオスマン朝の存在を一掃しようとする最後の大規模な外部介入の機会を消し去り、イスタンブル征服への道を確実なものにした。", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["第2次コソヴォの戦い", "ebe0b662"], "d": ["ヴァルナの復讐を望んだフニャディ・ヤーノシュの軍は、三日間続いた激戦でムラト2世に決定的な敗北を喫した。これは十字軍がバルカンでオスマン朝に対して挑んだ最後の大規模な会戦である。この勝利により、ドナウ川以南のオスマン朝の支配は覆しがたく定着した。", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["コンスタンティノープルの征服", "583d5e3e"], "d": ["五十四日間（4月6日〜5月29日、1453年）に及んだ包囲の後、5月29日の朝に城壁を越えたオスマン軍が都市に入った。最後の皇帝コンスタンティノス11世は戦闘で死に、1100年続いた東ローマ帝国は歴史に消えた。若いスルタンは「ファーティフ（征服王）」の称号を得、都市を首都とし、アヤソフィアをモスクに転用した。都市は短期間のうちに入植と建設によって再び活気づいた。TDVによれば、シリヴリとヴィゼは1453年になって初めて決定的に征服された。TDVのリムノス項によれば、島は征服の直後にオスマン朝の統治下に入り、貢納を条件にガッティルージオ家に委ねられた。アトラスでは、シリヴリ、ヴィゼ、リムノスはこの日付でビザンツからオスマンへ（リムノスは貢納地として）記されている。巨大な大砲の鋳造、艦船の陸上輸送、城壁前の包囲配置は、当時の軍事工学の頂点とみなされる。この征服は、ヨーロッパの歴史叙述において中世の終わりを象徴する日付の一つに数えられる。", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["トレビゾンドの征服", "15f52403"], "d": ["ファーティフが陸軍と海軍で同時に進めた困難な黒海遠征の末に、トレビゾンド・ギリシア帝国は降伏した。アナトリアにおけるビザンツ世界の最後の残滓が一掃されたことで、黒海南岸は完全にオスマン朝の支配下に入った。コムネノス朝の終焉は、ファーティフの「二つの海と二つの陸の支配者」という主張を強めた。同じ日に加わったその他の地：Giresun, Rize。", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["シリフケの最終的征服 — カラマン朝最後の抵抗の粉砕", "d988bee4"], "d": ["シリフケ城は1472年に一度ゲディク・アフメト・パシャに降伏したが、同じ年にカラマンオウル・カスム・ベイが地中海の十字軍艦隊の支援で城を奪回していた。オトゥルクベリの勝利の後、ファーティフは息子とゲディク・アフメト・パシャにこの地域を最終的に掌握するよう命じた。旧オスマン砲兵の援助により火薬庫に火がつけられ、城は速やかに陥落した。こうしてカラマン朝のタシェリ＝イチェル山地における最後の抵抗は砕かれ、侯国の解体は1474年に完了することになった。", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["オトゥルクベリの戦い", "42c7194e"], "d": ["東方で大きな勢力となりヴェネツィアと同盟したアク・コユンルの君主ウズン・ハサンは、オトゥルクベリで、火器で装備したファーティフの軍に大敗した。この勝利はアナトリアにおけるオスマン朝の優位を確定させ、大砲と銃を用いる中央集権的な軍が在来の軍に対して優位であることの初期の証拠ともなった。TDVのギュミュシュハーネ項によれば、この都市は1467年以来アク・コユンルの支配下にあったが、この支配はオトゥルクベリの敗北で終わり、ギュミュシュハーネは決定的にオスマン朝の支配に移った。", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["クリミアのオスマン朝保護下への編入", "44e3f7c8"], "d": ["ゲディク・アフメト・パシャ指揮下の艦隊は、ジェノヴァ人の手にあったカッファをはじめとするクリミア南岸の諸都市を征服し、これらの沿岸は直接オスマン朝のサンジャクとされた。一方、クリミア・ハン国はメングリ・ギレイとともに、オスマン朝の宗主権を認める特権的な従属国となり、3世紀にわたり北方政策の要となった。黒海は事実上オスマン朝の内海となった。同じ日に加わったその他の地：Bahçesaray, Kerç, Azak。", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["ファーティフの死 — ジェム・スルタン事件", "190ecf01"], "d": ["ファーティフが遠征の途上で急死したため、バヤジト2世が即位した。弟のジェム・スルタンは王位を主張してブルサで自らの名でフトバを読ませ貨幣を鋳造させた。敗れると、まずマムルーク朝に、次いでロードス騎士団のもとに身を寄せた。騎士団と教皇庁の手の中でヨーロッパ外交の取引材料となったジェムは、1495年にナポリで死んだ。この事件は、オスマン朝の外交政策を十五年にわたり慎重な行動へと向かわせた。", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["チャルディランの勝利", "fea64ebb"], "d": ["アナトリアにおけるサファヴィー朝の宣伝が生んだ脅威を根本から解決しようとしたヤヴズ・スルタン・セリムは、シャー・イスマーイールの軍をチャルディラン平原で大砲と銃の優位によって大敗させた。タブリーズに入城し、東アナトリアと南東アナトリア、およびモスル＝ディヤルバクルの線がオスマン朝の統治に加わった。イドリース・ビトリースィーの尽力によるクルドの諸侯のオスマン朝への帰属は、数世紀続く東の国境の枠組みを築いた。", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["マルジュ・ダービクの勝利", "07d254d3"], "d": ["マムルーク軍はアレッポ北方のマルジュ・ダービクで数時間のうちに潰走させられ、年老いたスルタン、カンスー・ガウリーは戦闘中に死んだ。アレッポとダマスクスの門を大きく開いたこの勝利によって、シリア、レバノン、パレスチナはオスマン朝の統治下に入り、マムルーク国家の終焉をもたらすエジプト遠征への道が開かれた。", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["リダーニーヤ — エジプトの征服とカリフ位", "caf378d6"], "d": ["シナイ砂漠を急ぎ越えたオスマン軍は、リダーニーヤでトゥマーン・バイの防衛線を突破してカイロに入った。抵抗を続けたトゥマーン・バイは捕らえられて処刑され、マムルーク国家は歴史から消えた。エジプト、ヒジャーズ、聖地がオスマン朝の統治下に入り、アッバース朝のカリフと聖遺物はイスタンブルに運ばれた。カリフ位がオスマン朝の王家に移ったことで、スルタンたちはイスラーム世界の指導者としての主張を担い、香辛料の道の支配も帝国に大きな収入をもたらした。同じ日に加わったその他の地：Akkâ, Maan, Sayda, Kerak。", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["カーヌーニー・スレイマンの即位", "f6512269"], "d": ["ヤヴズの死により唯一の男子として即位したスレイマン1世の46年に及ぶ治世は、帝国の政治・軍事・法・文化の頂点とみなされる。慣習法を体系化したカーヌーン・ナーメにより「カーヌーニー（立法者）」の称号を得た。西欧では「壮麗王」（Magnificent）と呼ばれた。建築家シナンの作品、ディーワーン文学の黄金期、艦隊の地中海における優位は、この時代の象徴である。", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["ベオグラードの征服", "59ef5cec"], "d": ["ファーティフが1456年に奪えなかった、「中央ヨーロッパの鍵」とされるベオグラードは、カーヌーニーの最初の遠征でドナウ川とサヴァ川の合流点での包囲の末に陥落した。ハンガリーの南の防衛線は崩壊し、五年後のモハーチ、二十年後のブダ併合へと続く中央ヨーロッパ作戦の扉が、この征服で開かれた。", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["ロードスの征服", "807bbb1e"], "d": ["東地中海の海路と巡礼路を脅かしていた聖ヨハネ騎士団の拠点ロードスは、数か月に及ぶ血なまぐさい包囲の末、協定により降伏した。騎士団が島から自由に去ることが許された（のちにマルタに定着した）。アナトリア沿岸の安全が確保され、イスタンブルとエジプトを結ぶ海路は途切れなくオスマン朝の管理下に入った。", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["モハーチの戦い", "f3418b0d"], "d": ["ハンガリー軍は、モハーチ平原でおよそ二時間のうちに砲火と機動の優位によって壊滅させられた。国王ラヨシュ2世は逃走中に沼地で死んだ。オスマン史上最も短時間で勝ち取られた大会戦の一つであるモハーチは、独立したハンガリー王国を事実上終わらせ、中央ヨーロッパにおけるオスマン＝ハプスブルク対立の時代を開いた。", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["第1次ウィーン包囲", "dc49ea4f"], "d": ["ハプスブルク家がハンガリーの王位に手を伸ばしたことへの対抗として行われた遠征で、オスマン軍はウィーンを包囲した。重砲を途中に残したこと、早く訪れた冬、補給の困難のため、三週間後に包囲は解かれた。都市は陥落しなかったが、ハンガリーに対するオスマン朝の影響力は保たれた。ウィーン城下は、帝国の中央ヨーロッパにおける兵站上の到達限界を示した。", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["バグダードの征服 — 二つのイラク遠征", "897092c3"], "d": ["「二つのイラク」（アラブのイラクとアジャムのイラク）に向けた遠征で、まずタブリーズに、次いで戦わずしてバグダードに入った。アッバース朝の旧都の占領は、オスマン朝の君主にイスラーム世界で大きな威信をもたらした。イマーム・アーザム・アブー・ハニーファの廟が再興され、バグダードとバスラの編入によりオスマン領はペルシア湾に達した。同じ日に加わったその他の地：Kerkük, Kerbelâ。", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["プレヴェザ海戦の勝利", "30dc0f97"], "d": ["教皇の主導で組織された十字軍艦隊は、数で優っていたにもかかわらず、風と海岸を巧みに利用したバルバロスの戦術によりプレヴェザ沖で撃破された。アンドレア・ドーリアは戦場を放棄した。この勝利は、地中海でおよそ33年続く議論の余地のないオスマン朝の海上優位を確立した。トルコの海事の伝統における海軍記念日の象徴的な日付である。同じ日に加わったその他の地：Aden, Bender。", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["ブダの併合 — ハンガリーがオスマン朝の州となる", "db53b244"], "d": ["ハプスブルク家によるブダ包囲を受けて出征したカーヌーニーは、都市を解放した後、中部ハンガリーを直接オスマン朝の統治下に置いてブダ・ベイレルベイリクを設けた。トランシルヴァニアはオスマン朝に従属する自治公国とされた。ハンガリーのこの三分割の体制は約150年続き、オスマン朝の中央ヨーロッパにおける恒久的な統治の骨格をなした。", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["アマスヤ条約", "a5afe0d1"], "d": ["長年続いたオスマン＝サファヴィー戦争を終結させた最初の正式な和平条約である。バグダードとイラクはオスマン朝に残り、東アナトリアの国境が初めて相互に承認された。サファヴィー朝はオスマン領内でのシーア派の宣伝を止めることを、オスマン朝はイラン人巡礼者の通行の安全を保証することを引き受けた。この条約は、両国間の関係の法的な枠組みの最初の例となった。", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["シゲトヴァール — カーヌーニーの崩御", "e2917ed2"], "d": ["72歳のカーヌーニーは、十三回目の遠征で包囲していたシゲトヴァール城の陥落の数時間前に、天幕で崩御した。ソコッル・メフメト・パシャは軍が崩れないよう、死を数週間にわたり隠した。城は占領されたが、国家は最も長く在位し最も壮麗であったスルタンを失った。息子のセリム2世が即位し、国政における大宰相たちの比重が増し始めた。", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["キプロスの征服", "e364a2b3"], "d": ["ヴェネツィア統治下のキプロスに1570年に上陸が行われた。ニコシアは速やかに陥落し、マグサ（ファマグスタ）は十一か月の包囲の後、1571年8月になってようやく降伏した。東地中海の通商路と巡礼路の安全にとって重要なこの島は、ベイレルベイリクとして組織され、アナトリアから人口が入植させられた。この征服は、レパントに至る大十字軍同盟の理由にもなった。", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["レパント（İnebahtı）の敗北", "6a1d44a9"], "d": ["キプロス征服を受けて結集した十字軍艦隊は、オスマン艦隊をレパント湾で捕捉してその大部分を壊滅させた。海軍総督ミュエッズィンザーデ・アリ・パシャは戦死し、ウルチ・アリの艦隊だけが逃れた。惨事の後、大宰相ソコッル・メフメト・パシャはウルチ・アリ・パシャを海軍総督に任じて散り散りになった艦隊を集めさせ、イスタンブルからアランヤに至るすべての造船所で新たな艦隊の建造を始めさせた。しかし、地中海における絶対的な優位は心理的に揺らいだ。", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["ハチョヴァの戦い", "da308ec5"], "d": ["長期戦争（1593〜1606年）で最大の会戦において、メフメト3世が自ら率いた軍は、崩壊寸前の瞬間にホジャ・サーデッディン・エフェンディの進言で立て直し、ハプスブルク軍を敗走させた。オスマン朝が勝ち取った最後の大きな古典的会戦とみなされる。しかし、戦争の全体的な流れを変えなかったことは、軍事体制の疲弊の兆候ともみなされた。", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["ジトヴァトロク条約", "39c01142"], "d": ["十三年に及ぶ消耗戦を終結させた条約により、ハプスブルクの君主は初めて「ローマ皇帝」の称号でスルタンと対等とみなされ、年貢が廃止された。領土の喪失はないに等しかった。しかし外交上の言葉づかいのこの変化は、オスマン朝のヨーロッパに対する絶対的優位の主張の終わりの象徴として読まれる。", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["カスレ・シーリーン条約", "c1acf3af"], "d": ["ムラト4世によるバグダード奪回（1638年）の後に調印された条約は、百年を超えるオスマン＝サファヴィー戦争に終止符を打った。バグダードとイラクは決定的にオスマン朝に残り、エレヴァンはサファヴィー朝に譲られた。引かれた線は、小さな変更を伴いながら今日のトルコ＝イランの国境の基礎となり、世界で最も長続きした国境の一つとされる。条約はBedre, Cessân, Mendelî, Derteng, Derneをオスマン朝に譲った。国境のZencir城塞は破壊され、その西側の村はオスマン朝に、東側の村はイランに属すこととされた。シェフリゾル近郊のZalim城塞周辺とKızılca Kaleはオスマン朝に、AvromanとMihribanはイランに残った。Kotur, Mâkû, Mağazberd城塞は両側によって破壊されることとなった。", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["クレタ征服の完了", "e0d85604"], "d": ["1645年に始まったクレタ戦争の最終幕であるカンディア包囲は、ファーズル・アフメト・パシャの三年にわたる断固たる作戦によって決着した。ヴェネツィアの司令官モロジーニは、都市を協定により引き渡した。およそ四半世紀に及んだ闘争は、オスマン史上最長の包囲として記録された。東地中海における最後の大きなラテン人の城塞もオスマン朝の統治下に入った。島の北岸の三つの小さな岩の城塞、すなわちスダ、スピナロンガ、グランボウサは、まだヴェネツィアに残っていた。これらは別個の小島の上に築かれているため、地図上でクレタの残りの部分から分けて示すことはできない。", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["ブチャチ条約 — 最大版図", "b17b6e5a"], "d": ["ポーランド遠征でカームヤネツの征服の後に調印されたブチャチ条約により、ポドリアがオスマン朝に編入され、ウクライナの一部が保護下に置かれた。こうして帝国はヨーロッパにおける最大の版図に達した。この点は、拡張の時代の頂点であると同時に、その最後の環とみなされる。", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["第2次ウィーン包囲の潰走", "7d889252"], "d": ["メルズィフォンル・カラ・ムスタファ・パシャの二か月に及ぶウィーン包囲は、ポーランド王ヤン・ソビエスキがカーレンベルクの丘から繰り出した急襲によって潰走に終わった。軍は輜重を捨てて退き、メルズィフォンルはベオグラードで処刑された。勝利の後に結成された神聖同盟との戦争は16年続いた。この敗走は、オスマン史における大きな衰退の始まりの瞬間として示される。", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["グランボウサ城塞の征服 — クレタに残ったヴェネツィアの岩の城塞の一つ", "3ddf9eeb"], "d": ["1669年のカンディアの降伏によりクレタの征服は大筋で完了したとみなされるが、島の北西端の岩の島の城塞グランボウサは、さらに二十三年間ヴェネツィアの手に残った。1692年の占領により、クレタに残る三つのヴェネツィアの残滓のうち一つが一掃された。スダとスピナロンガは、1715年のモレア遠征を待つことになった。", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["カルロヴィッツ条約 — 最初の大規模な領土喪失", "8f7e2546"], "d": ["十六年に及ぶ神聖同盟戦争を終結させたカルロヴィッツ条約により、ハンガリーとトランシルヴァニアはオーストリアに、ポドリアはポーランドに、モレアとダルマチア沿岸はヴェネツィアに譲られた。オスマン史上初めて、この規模の領土が交渉の席で恒久的に失われた。この条約は、帝国がヨーロッパに対して守勢に回った新しい時代の始まりの文書とされ、オスマン外交史の転換点でもある。同じ日にアトラスで所属が変わった集落：Kostajnica と Jasenovac（オスマン朝からハプスブルクへ。条約文は Castanoviz を皇帝の手に残しており、Jasenovac の引き渡し日は史料になく、条約の日が記された）、および Preveze（ヴェネツィアからオスマン朝へ。TDV karlofca：ヒジュラ暦1110年ラジャブ月24日／1699年1月26日に調印された条項に従い、ヴェネツィアのレパント湾北方の占領地が返還された）。アトラスはさらに Kostayniçe (Kostajnica) と Jasenovaç をハプスブルク側に、右岸ウクライナの Uman と Vinnitsa をオスマン朝からポーランドへ（TDV merzifonlu-kara-mustafa-pasa；IEU Vinnytsia：1672〜99年トルコの支配）、そしてダルマチアの Nadin をヴェネツィアに記す（集落固有の引き渡し日は史料になく、条約の日が記された。Nadin の期間の端は史料で確認されていない — 申告付きの近似）。レパント湾北方の Vonitsa もヴェネツィアからオスマン朝に返還される（TDV karlofca）。ダルマチアの Vrana (Urana) はヴェネツィアに残った地の一つである（期間の端は確認されていない — 申告付き）。", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["プルートの勝利", "2583572f"], "d": ["ポルタヴァの敗北の後にオスマン朝に身を寄せたスウェーデン王の問題から起きた戦争で、ツァーリ・ピョートル1世の軍はプルート河畔で包囲され、降伏を余儀なくされた。結ばれた条約によりアゾフが取り戻された。軍が殲滅されなかったことと、ツァーリが解放されたことは、その日から今日まで議論される決定として歴史に残った。", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["スダ城塞とスピナロンガ城塞の征服 — クレタにおける最後のヴェネツィアの痕跡の消滅", "7261f7ba"], "d": ["グランボウサが1692年に陥落してから二十三年後、モレア遠征の一支隊によって、ヴェネツィアのクレタにおける最後の二つの拠点であるスダ城塞とスピナロンガ城塞も征服された。こうして1645年に始まったクレタの征服は、四十六年を経て、島の最後の一寸に至るまで完了した。", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["パトロナ・ハリルの反乱", "100941a4"], "d": ["イラン戦線での失敗、税、宮廷周辺の贅沢への怒りは、浴場の垢すり職人パトロナ・ハリルの指導のもとで大きな蜂起へと発展した。大宰相イブラヒム・パシャは殺され、アフメト3世は廃位され、チューリップ時代は終わった。反乱者たちが数か月にわたり都市を支配したことは、中央権力の脆弱さを際立たせた。", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["ベオグラード条約 — ベオグラード、スメデレヴォ、北セルビアの奪回", "ba7f8e46"], "d": ["オーストリアとロシアに対する二正面の戦争（1736〜1739年）の末、ベオグラードと北セルビアが取り戻された。ロシアはアゾフの武装解除と黒海に艦隊を置かないことを受け入れた。18世紀のオスマン外交と軍の最後の大きな成功とされるこの条約は、帝国に四半世紀の平和の時代をもたらした。同じ日にアトラスでオーストリアからオスマン朝に戻ったその他の集落：Hisarcık (Grocka)（ベオグラードの兄貴分中心地の連鎖；TDV belgrad）、Krayova (Craiova)、Rimnik (Râmnicu Vâlcea)、Turnu Severin（小ワラキアのオスマン朝への復帰、ワラキアの従属下へ）。サヴァ川沿いの Bosna Brod (Bosanski Brod) と Bosna Dubiçası (Bosanska Dubica) は、アトラスでは1739年9月28日にオスマン朝に戻る（TDV bosna-hersek；TDV mahmud-i--osmanli：1739年9月28日）。小ワラキアの Tırgu Jiu も同じ日にオスマン朝に戻る。", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["チェシュメ襲撃", "840b30bd"], "d": ["イギリスの支援を受けて地中海に出たロシア艦隊は、避難していたチェシュメ港のオスマン艦隊を火船で襲い、ほぼ完全に焼き払った。ロシアは初めて地中海で大きな海軍力として姿を現した。この惨事は、1774年のキュチュク・カイナルジャへと至る戦争の行方を決めた打撃の一つとなり、艦隊の根本的な改革の必要性を明らかにした。", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["キュチュク・カイナルジャ条約", "2776dcdb"], "d": ["1768〜1774年の戦争を終結させ、オスマン史上最も重い条約の一つとされるキュチュク・カイナルジャにより、クリミア・ハン国に「独立」が与えられた — 事実上ロシアの勢力圏が作られたことになる。ロシアは黒海沿岸に足場を築き、商船に海峡の通行権とイスタンブルへの常駐大使を得た。正教徒臣民に対する曖昧な保護条項は、次の世紀の介入の口実への扉を開いた。初めて、住民がムスリムである土地がオスマン朝の支配から切り離された。", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["クリミアのロシアへの併合", "bdf6faa8"], "d": ["キュチュク・カイナルジャが生み出した「独立」クリミアは、最後のハン、シャヒン・ギレイの時代の混乱を口実に、エカチェリーナ2世の宣言によりロシアに併合された。3世紀に及んだオスマン＝クリミアの提携は終わった。北方の草原の喪失はイスタンブルの防衛の縦深を失わせ、数万のクリミア・タタール人がオスマン領へ移住する最初の大きな波を引き起こした。この日、クリミア半島（Aluşta, Kefe, Sudak, Yalta, Balaklava, İnkirman, Mankup, Arabat）はロシアに編入され、Taman と Kuban も同じ併合でロシアに移った（TDV Kırım：1783年4月8日ユリウス暦＝4月19日グレゴリオ暦）。", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["セリム3世とニザーム・ジェディード", "d53aec21"], "d": ["戦争のさなかに即位したセリム3世は、敗北が構造的なものであることを見抜き、「ニザーム・ジェディード」（新秩序）の名で包括的な改革計画を始めた。ヨーロッパ式の訓練を受けた新軍、それを賄う別個の国庫（イラード・ジェディード）、工兵学校の強化、そしてヨーロッパの首都における最初の常駐大使館である。この計画は近代トルコの改革の伝統の始まりとみなされるが、軍団（イェニチェリ）とアーヤーンの抵抗により、1807年に潰えることになった。", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["マルタ騎士団の解体 — フランス艦隊の途上の寄港", "d62f901d"], "d": ["エジプトへ向かうフランス艦隊は途上のマルタに立ち寄り、聖ヨハネ（マルタ）騎士団はさしたる抵抗もなく島を明け渡した。1522年にロードスから追われてこの地に定着した騎士団の最後の拠点は、こうして終わった。マルタは二年後にイギリスの手に渡り、ナポレオンは島から直接アレクサンドリアへ向かうことになった。", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["ナポレオンのエジプト占領", "93fede5f"], "d": ["ボナパルト将軍の軍はアレクサンドリアに上陸してエジプトを占領した。イギリスのインドへの道を狙ったこの遠征は、ヨーロッパの一大国によるオスマン朝の中核領への最初の直接攻撃であった。ネルソンのアブキール襲撃とジェッザール・アフメト・パシャのアッカ防衛がフランスの進軍を砕いた。占領は1801年に終わったが、残された空白の中でカヴァラのメフメト・アリー・パシャの台頭と「東方問題」の時代が始まった。", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["同盟の誓約書（セネディ・イッティファーク）", "cce49ef5"], "d": ["マフムト2世を即位させたルスチュクのアーヤーン、アレムダル・ムスタファ・パシャの主導のもとで、宮廷と地方の有力アーヤーン家の間で調印された文書である。アーヤーンはスルタンへの忠誠と兵力の支援を約し、国家もまた彼らの存在と権利を認めた。スルタンの権威が文書によって制限された最初の例であるため、一部の歴史家によって立憲的な伝統の遠い始まりとみなされるが、事実上は数か月のうちに効力を失った。", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["ギリシア独立戦争の開始", "a7293715"], "d": ["フィリキ・エテリア組織が準備した蜂起は、まずワラキアで、次いで主力をもってモレアで勃発した。テペデレンリ・アリ・パシャの問題に手を取られていた国家は、初動の対応が遅れた。蜂起は、ヨーロッパの世論における強いギリシア贔屓（フィルヘレニズム）のおかげで、短期間のうちに国際的な問題へと発展した。民族主義の時代におけるオスマン領で最初の成功した独立運動の導火線は、このようにして点火された。同じ日に失われたその他の集落：Atina, Balyabadra (Patras), İstefe (Tebai), Livadya, Eleusis (Attika), Missolonghi。", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["モレアでの最初の武装蜂起", "77e6250f"], "d": ["プルートの渡河の後、蜂起はモレアに波及した。カラヴリタ（ユリウス暦3月21日）で始まった武装行動にパトラ、カラマタ、マニの運動が続き、モレアは短期間のうちに全面的な蜂起となり、オスマン朝の統治は半島の大部分を失った。同じ日に失われたその他の集落：Atina, Balyabadra (Patras), İstefe (Tebai), Livadya, Eleusis (Attika), Missolonghi。", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["ヴァカ・イ・ハイリイェ — イェニチェリ軍団の廃止", "08c9372a"], "d": ["新設のエシュキンジ軍団の訓練に反発して釜をひっくり返して反乱したイェニチェリは、マフムト2世があらかじめ整えていた忠実な部隊の砲火によって、エトメイダヌの兵営で壊滅させられた。軍団はすべての支部と関連するベクタシー教団のテッケとともに廃止された。「吉兆の出来事」を意味する名で歴史に残るこの作戦は、4世紀続いた制度を一掃することで、ムハンマド常勝軍の創設とその後のあらゆる中央集権化改革の道を開いた。", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["ナヴァリノ襲撃", "ee579e7f"], "d": ["ギリシアの蜂起を鎮圧していたオスマン＝エジプト艦隊は、宣戦布告なしに港に入った英仏露の連合艦隊によってナヴァリノで焼き払われた。六十隻近い艦船と数千人の船員が失われた。ヨーロッパ外交で「不幸な出来事」として片づけられた襲撃は、ギリシアの独立を事実上保証し、1828〜29年のオスマン＝ロシア戦争への道を開いた。", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["タンジマート勅令", "5042ce7b"], "d": ["ギュルハーネで読み上げられたハット・イ・ヒュマーユーンにより、宗教の区別なくすべての臣民の生命、財産、名誉の安全が国家の保障下に置かれた。課税における公正、兵役における秩序、裁判なしに刑を科さないことの原則が宣言された。ムスタファ・レシト・パシャの作であるこの勅令は、オスマン近代化の憲法的性格を持つ最初の大きな文書とみなされ、「タンジマート時代」（1839〜1876年）は改革の時代にその名を与えた。行政、法、教育、財政における根本的な再編がこの枠組みの中で進められた。", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["クリミア戦争の開始", "3b9ca3c8"], "d": ["聖地問題とロシアの正教徒臣民に対する保護の主張から始まった危機は、オスマン朝の宣戦布告により公然たる戦闘に発展した。シノプ襲撃の後、イギリスとフランス（のちにピエモンテ）がオスマン朝の側で参戦した。連合軍がクリミアに上陸してセヴァストポリを占領したことで、戦争は1856年のパリ条約によって勝利に終わった。しかし、戦争の年に受けた最初の対外債務（1854年）は、帝国を半世紀続く財政的従属の悪循環に陥れた。", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["改革勅令（イスラハート勅令）", "78ff234d"], "d": ["パリ講和会議の前に発布された勅令は、タンジマートの原則を拡張し、非ムスリム臣民に官吏への登用、兵役、学校設立を含む広い平等の権利を認めた。共同体の組織も再編された。続いて調印されたパリ条約により、オスマン国家は正式にヨーロッパの国際法の仲間に受け入れられ、その領土保全は列強の共同保証の下に置かれた。この保証は、実際には介入の新たな扉となった。", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["カーヌーン・エサースィー — 第一次立憲政", "0fe052c1"], "d": ["バルカン危機を協議するためイスタンブルで開かれた国際会議の開会日に、礼砲とともに最初のオスマン憲法が公布された。ミドハト・パシャを筆頭とする「新オスマン人」運動の作であるカーヌーン・エサースィーにより、二院制の議会が設けられた。議会（メクリス・イ・メブスーン）は1877年3月に開かれたが、アブデュルハミト2世は93年戦争を口実に1878年2月に議会を無期限に停会し、憲法は三十年間棚上げとなった。", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["93年戦争（1877〜78年のオスマン＝ロシア戦争）", "5bd96af7"], "d": ["ルーミー暦1293年にあたるため「93年戦争」と呼ばれる戦争で、ロシア軍は二方面から攻撃した。ガーズィー・オスマン・パシャのプレヴェン防衛とアフメト・ムフタル・パシャのカフカース戦線の戦いは叙事詩となったが、戦線は崩壊し、ロシア軍はイェシルキョイ（アヤステファノス）まで進んだ。戦争は、バルカンとカフカースからイスタンブルへ向かう、影響が今日にまで及ぶ大規模なムスリムの移住の波を引き起こした。帝国の人口構造と財政構造は二度と元には戻らなかった。", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["ベルリン条約", "47f76a49"], "d": ["アヤステファノスが生んだ「大ブルガリア」を列強の均衡の名の下に修正したベルリン会議は、それでも重い結果を残した。セルビア、モンテネグロ、ルーマニアが独立し、自治のブルガリア公国が設けられ、ボスニア・ヘルツェゴヴィナはオーストリアの占領に、キプロスはイギリスの統治に、カルス・アルダハン・バトゥミはロシアに委ねられた。ルメリアにおける五百年のオスマン朝の秩序は大きく解体され、「東方問題」はヨーロッパ外交の恒常的な議題となった。同じ日に失われたその他の集落：Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Bükreş, Yaş, Köstence。ルーマニアは、ベッサラビアをロシアに譲る代償としてトゥルチャ（Tulcea）とドブルジャを得た。北ドブルジャのトゥルチャ、Babadağı (Babadag)、Maçin、İshakçı (Isaccea)、Hırsova (Hârșova)、Mangalya (Mangalia) はルーマニアに移った。", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["チュニジアの占領とデュユーン・ウムーミイェ", "c7e25598"], "d": ["フランスはアルジェリア国境での事件を口実にチュニジアを占領し、バルドー条約によってその保護下に置いた。オスマン朝の北アフリカにおける存在はトリポリタニアにまで後退した。同年に出されたムハッレム勅令により、破産した対外債務の管理のために債権者が代表されるデュユーン・ウムーミイェ管理局が設立された。塩、煙草、絹などの基幹収入が直接この外国の機関に結びつけられ、財政主権は著しく制限された。同じ日に失われたその他の集落：Kayrevan, Gabes, Sfaks, Cerbe (Djerba)。", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["エジプトのイギリスによる占領", "f1269768"], "d": ["エジプトで財政破綻と外国の管理に抗して高まったウラービー・パシャの運動は、アレクサンドリアの砲撃の後に上陸したイギリス軍のテル・エル・ケビールの勝利で粉砕され、カイロは占領された。エジプトは法的にはオスマン朝に属し続けたが、事実上イギリスの統治下に入った。スエズ運河の管理は、ブリテン帝国の戦略の中心に据えられた。", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["第二次立憲政の宣言", "95ee2fd2"], "d": ["統一と進歩委員会に属する将校たちがマケドニアで山に入ったことで広がった運動を前に、アブデュルハミト2世はカーヌーン・エサースィーを再び施行した。「自由の宣言」は熱狂をもって迎えられ、選挙が行われた。しかし安定は訪れなかった。3月31日事件（1909年4月）が鎮圧された後、アブデュルハミトは廃位された。ブルガリアの独立、ボスニアの併合、クレタのギリシアへの志向も、この動揺の数か月の間に起きた。", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["トリポリタニア戦争（伊土戦争）", "ed441994"], "d": ["植民地を求めるイタリアは、オスマン朝の北アフリカにおける最後の領土トリポリタニアに宣戦し、沿岸を占領した。艦隊を持たない国家が正規軍を送れなかったため、ムスタファ・ケマルやエンヴェル・ベイのような若い将校たちが密かに現地に渡り、セヌーシー部族とともに効果的な抵抗を組織した。バルカン戦争の勃発を受けて調印されたウシー条約（1912年10月18日）によりリビアはイタリアに譲られた。イタリアはさらにロードスとドデカネス諸島を占領した。", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["ロンドン条約 — ルメリアの喪失", "f3f976df"], "d": ["第1次バルカン戦争を終結させたロンドン条約により、ミディエ＝エネス線の西側の全領土とエーゲ海の島々が失われ、アルバニアは独立した。五百年を超える間、帝国の人口・経済・文化の重心であったルメリアから残るのは東トラキアだけとなった（エディルネは第2次バルカン戦争で取り戻された）。この喪失は、統一派政権の戦争と入植の政策を根本的に硬化させた。ミディエ＝エネス線の西側に残った次の地が失われた：Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Dibra), Prizren, Priştine, Peç (Pejë), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje)；Serez, Drama, Kavala, Petriç, Nevrokop, İskeçe, Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo)；クレタではHanya, Kandiye, Girit (Resmo), Sitiye (Sitia), İsfakiye (Sfakia)。", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["第一次世界大戦への参戦", "05a0252e"], "d": ["イギリスから逃れてきた戦艦ゲーベンとブレスラウを購入したと見せかけて海峡に入れたことが、国家を一歩ずつドイツの側に引き寄せた。スーション提督指揮下の艦隊がロシアの港を砲撃したこと（10月29日）で戦争は事実上始まり、相互の宣戦布告は11月初めに行われた。ジハード・エクベル（大ジハード）の宣言にもかかわらず期待された効果は生じなかった。帝国は四年間にわたり、カフカースからパレスチナまで五つの戦線で存亡をかけた戦争に入った。", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["チャナッカレの勝利", "95d888e8"], "d": ["イスタンブルを陥落させてロシアに到達することを目指した連合軍の大艦隊は、3月18日に機雷線と砲台の砲火によって海峡から撃退された。ヌスレト機雷敷設艦が敷いた線が戦いの行方を決めた。4月に始まったゲリボル半島上陸作戦も、アナファルタラルとコンクバユルで食い止められ、連合軍は1916年1月に半島から完全に撤退した。中佐ムスタファ・ケマルの名はこの戦線で知られるようになった。約二十五万の戦死者・損失をもって勝ち取られた勝利は、民族闘争の人材と精神が生まれた場所とみなされる。", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["シャリーフ・フサインの反乱", "75f7c58c"], "d": ["メッカの太守シャリーフ・フサインは、イギリスと行った秘密の書簡交換の後、独立したアラブ王国の約束を得て蜂起した。ヒジャーズ鉄道は襲撃の標的となった。休戦の後まで続いたファフレッディン・パシャのメディナ防衛は、抵抗の象徴として語り継がれたが、反乱はパレスチナ戦線におけるイギリス軍の進撃と結びついて、アラブ諸州におけるオスマン朝の支配の解体を加速させた。同じ日に失われたその他の集落：Tâif。", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["ムドロス休戦協定", "9e87c767"], "d": ["ブルガリアの崩壊により諸戦線が互いに分断されたオスマン国家は、戦艦アガメムノン号上で調印された休戦協定によって戦争から撤退した。海峡の開放と、特に安全が脅かされた地の占領を可能にする第7条は、短期間のうちに事実上の分割の法的な口実とされた。モスル、イスケンデルン、続いてイズミルとイスタンブルが占領された。休戦協定は、帝国の事実上の終焉の文書とみなされる。同じ日に失われたその他の集落：Hama, Şam, Humus。", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["ムスタファ・ケマルのサムスン上陸 — 民族闘争", "09a8f784"], "d": ["イズミル占領が生んだ憤激の中、第9軍監察官の資格でサムスンに上陸したムスタファ・ケマル・パシャは、公式の任務をアナトリアの抵抗の組織化へと転じた。アマスヤ通達とエルズルム会議、シヴァス会議はこの出立の続きである。「民族の独立は、ただ民族の決意と決断によって救われる」という原則は、民族闘争の政治綱領の核となった。", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["トルコ大国民議会の開会とセーヴル", "2008feec"], "d": ["イスタンブルの公式な占領とメクリス・イ・メブスーンの解散を受けて、1920年4月23日にアンカラで大国民議会が開かれた。非常の権限を自らに集めた議会は、国民の意思に基づく新国家の核となった。8月にイスタンブル政府が調印したセーヴル条約はアナトリアを分割するものであった。大国民議会は条約に署名した者たちを祖国への裏切り者と宣言し、セーヴルは一度も実施されなかった。", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["サカリヤの戦い", "f2f970a6"], "d": ["アンカラまで50キロメートルに迫ったギリシア軍の攻勢は、総司令官の権限を担ったムスタファ・ケマル・パシャの「防衛線はない、防衛面がある」との命令のもと、22日22夜にわたる戦闘で挫かれた。ギリシア軍は初めて戦略的防御に転じた。勝利はムスタファ・ケマルにガーズィーの称号と元帥の位をもたらし、フランスとのアンカラ協定と対外的承認への扉を開いた。", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["大攻勢とイズミルの解放", "172a50c4"], "d": ["8月26日の朝にコジャテペから開始された攻勢は、8月30日にドゥムルプナルで総司令官会戦によってギリシア軍主力の殲滅に達した。「諸軍よ、諸君の第一の目標は地中海である、前進せよ」の命令で続いた追撃により、9月9日にイズミルが解放された。ムダニヤ休戦協定（10月11日）により東トラキアは戦わずして取り戻された。軍事的勝利は、ローザンヌで築かれる新国家の交渉の場での力を決定づけた。", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["スルタン制の廃止", "9f36a9f6"], "d": ["ローザンヌ会議にイスタンブル政府も招かれたことを受け、大国民議会は1922年11月1日にスルタン制とカリフ制を分離してスルタン制を廃止した。623年続いたオスマン朝の王朝支配は法的に終わった。メフメト6世ヴァヒデッディンは11月17日にイギリスの戦艦で国を去った。カリフ位には大国民議会の決定によりアブデュルメジト・エフェンディが就けられ、この地位も1924年3月3日に廃止されることになった。", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["ローザンヌ条約", "38c27f7d"], "d": ["八か月に及ぶ困難な交渉の末に調印されたローザンヌ講和条約により、新トルコ国家の国境、完全な独立と主権が国際的に承認された。カピチュレーションは廃止され、デュユーン・ウムーミイェは清算の手続きに入り、住民交換が定められた。セーヴルを事実上無効としたローザンヌは、民族闘争の外交的勝利であり、共和国の創設的な対外文書とみなされる。", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["共和国の宣言", "d5bfcdfb"], "d": ["大国民議会が憲法の改正により「トルコ国家の政体は共和制である」との規定を採択したことで共和国が宣言され、ムスタファ・ケマル・パシャが初代大統領に選ばれた。1299年に辺境の侯国として始まった624年のオスマンの歩みはこうして閉じ、主権が無条件に国民に属する新国家が、帝国の遺産の上に築かれた。", "f5cabb8c"]},
"OLAYLAR_0073_IRAN_YANYA:1820-03-01:0":{"b": ["テペデレンリ・アリー・パシャの罷免とヤンヤ包囲の開始", "e8a6530b"], "d": ["マフムト2世の地方勢力の一掃政策は、33年間ヤンヤを統治し、テッサリアとエピロスを事実上手中にしていたテペデレンリ・アリー・パシャに及んだ。パシャはデルベンドの長から、息子ヴェリはトゥルハラ・パシャ職から罷免された。従わないと予想されたため、彼に対して軍が送られた。この任務を与えられたフルシド・アフメト・パシャは同時にモレアの総督でもあり、彼にはルメリア総司令官職も与えられた。地域のすべての民政・軍政の長がテペデレンリを捕らえる任務を与えられた。つまりギリシャの蜂起が勃発した時、モレアを統治すべき司令官とその配下の軍はヤンヤ城塞を包囲していた。アリー・パシャは1820年5月23日にギリシャ人とヤンヤで会合を開き、自らの統治下でギリシャ人の州を作ることを企て、彼らに金と武器の援助を行った。相手側には軽んじうる力はなかった。アリー・パシャには、7千人が常備軍である3-4万人の軍と小さな艦隊があり、支配下の人口は150-200万、年収は400-500万クルシュと見積もられていた。", "d0250e2a"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:0":{"b": ["オスマン・イラン戦争が始まった — カルスとバヤジットの喪失、エルズルムの包囲", "570b27bd"], "d": ["ギリシャの蜂起の2年目に、帝国の東の国境は戦争地帯となった。ガージャール朝の皇太子アッバース・ミールザーは、シャーの妃のメッカ巡礼に向かう隊商がオスマンの代表者に捜索されたことを口実に、大きな軍事力を率いて国境を越え、カルスとバヤジットの両州を奪い、エルズルムを包囲した。相対した軍は通常の国境部隊ではなかった。アッバース・ミールザーはアゼルバイジャン軍をヨーロッパ式に訓練し、タブリーズに火薬工房と大砲の鋳造所を設けさせていた。オスマン国家はこの時、西ではモレアの反乱と、北西ではテペデレンリ・アリー・パシャのヤンヤでの抵抗と取り組んでおり、手元にヨーロッパ式に訓練された軍はなかった。イェニチェリ軍団は1826年まで存続することになる。", "88b4be76"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:1":{"b": ["スレイマニイェとバグダードのイラン占領 — キルクークの包囲", "384d74e4"], "d": ["東アナトリアでの作戦と同時に、イラン軍はオスマンの統治下にある北イラクとバグダード州に広範な攻撃を行った。バグダードを当時統治していたのは1817年から総督を務めていたキョレメン・ダーヴド・パシャで、パシャはナポレオンの元副官ドゥヴォーに訓練させた1万人の歩兵と砲兵の軍を持っていた。帝国の中心にはまだそのような軍はなかった — ヨーロッパ式に訓練された部隊は当時、地方の有力な総督の手にしかなかった。戦争を終わらせたのはオスマンの勝利ではなかった。オスマンの抵抗とアゼルバイジャンを襲った疫病が、イラン軍を撤退せざるを得なくさせた。", "b60b096c"]},
"OLAYLAR_0073_IRAN_YANYA:1822-02-14:0":{"b": ["テペデレンリ・アリー・パシャの殺害 — ヤンヤ包囲の終わり", "da679150"], "d": ["ヤンヤでの抵抗は2年近く続き、まさにこの期間にギリシャの反乱は全般的な広がりを得た。フルシド・パシャが城塞に密偵を送り、逃げた者に階級と恩賜を配ると、アリー・パシャの周りの兵は40-50人に減った。パシャは降伏すれば命に手を付けないという保証のもと、湖上のパンデレイモン修道院に退いた。この時フルシド・パシャの家族はギリシャの反乱者の手に落ちていた。一刻も早くモレアに戻るため、彼は与えた安全保証書を無視して偽の死刑勅令を作らせた。部屋に踏み込まれた時、アリー・パシャは武器で応じ、起きた衝突で殺された。その首は2月24日にイスタンブルへ運ばれた。包囲は、オスマンの指揮部内の亀裂も明らかにした。モレアの反乱がテペデレンリの問題より危険になると、セイイド・アリー・パシャが独立したモレア総司令官に任命され、これを好まないフルシド・パシャは彼の援助要請を退け、彼を国家の目に失敗者として見せようとさえした。アリー・パシャが取り除かれた年の終わりに、モレアで最も強い城塞アナボリが陥落した。", "c7a915be"]},
"OLAYLAR_0073_IRAN_YANYA:1823-07-28:0":{"b": ["エルズルム条約 — イラン軍の60日での撤退", "166373c3"], "d": ["2年続いた戦争は、エルズルムで調印された和平条約で終わった。条約に従い、イラン軍は60日以内に占領した土地から撤退することになっていた。条約は新たな国境を引かず、戦前の状況を戻した。両国間の国境紛争は1833-1842年に再び衝突に転じ、1847年にやはりエルズルムで調印された第二の条約でやっと整理されることになる。東の戦線の閉鎖は、帝国がその全重みをギリシャの蜂起に注げるための前提条件であった。", "7c54983b"]},
"OLAYLAR_2S0920:0224-04-28:0":{"b": ["ホルミズダガーンの戦い: アルダシールがパルティア王アルタバヌス5世を破る — イスファハーンがササン朝の核に入る", "3689fd45"], "d": ["ファールスの地方君主アルダシールは、ホルミズダガーンでパルティア王アルタバヌス5世を破った。パルティア(アルサケス)朝は崩壊し、ササン朝が台頭した。atlasはこの日以降、イスファハーンをササン朝の土地とみなす。", "3551fe9f"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["カラフェリエ(ヴェリア)のオスマン支配への編入", "b0ece3f3"], "d": ["テッサロニキが1387年に降伏したのと同じ年に、下マケドニアの内陸のカラフェリエもオスマンの支配に入った。都市は、テッサロニキとテッサリアのあいだの道の結節点であった。", "4e571f7b"]},
"OLAYLAR_2S0920:1506-07-08:0":{"b": ["アルブレヒト4世がヴィッテルスバッハ長子相続令を発布 — バイエルンの諸公領が統合され、不可分の単一の公領となる", "86ee6f77"], "d": ["ランツフートの継承戦争(1503〜1505年)の後、バイエルンの諸公領を再び一手に集めた公アルブレヒト4世は、1506年7月8日に、国の不可分性と王位の最年長の男子への継承を定めた長子相続令を発布した。1255年から続いたバイエルンの分割はこうして終わった。ミュンヘンを中心とするバイエルンは、ドイツ諸国のなかで不可分の単一の公領として続いた。", "26058158"]},
"OLAYLAR_2S0920:1517-04-15:0":{"b": ["アーミル2世がサナア近郊で殺される — ターヒル朝の終焉", "713ae406"], "d": ["ターヒル朝の最後の君主アーミル2世は、マムルーク艦隊との関係の悪化から始まった戦争で、イエメンの部族とザイド派がマムルークを支援したことにより、まずザビード近郊で敗れ(1516年11月)、続いてサナア近郊の戦いで死んだ。1454年からイエメンを支配してきたターヒル朝はこうして終わり、王朝の都市(ターイズを含む)はもはやターヒル朝の君主権に従属しなかった。", "4b9725ef"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["ルゴイ(Lugoj)とカランセベシュ要塞の征服 — ティミショアラ遠征の続き", "1af5a2be"], "d": ["ティミショアラ要塞は3週間の抵抗の後、1552年7月26日に降伏した。8月にルゴイとカランセベシュの要塞も取られた。ムレシュ谷に沿って15の要塞が奪取され、中心をティミショアラとする新たなベイレルベイ領が設けられた。", "ecd1e532"]},
"OLAYLAR_2S0920:1723-11-18:0":{"b": ["エカテリンブルクの製鉄所兼要塞の建設 — ウラルの鉱山地帯の中心", "c416e12e"], "d": ["タチシチェフが選んだ、イセチ川の場所で、ド・ゲニンが仕上げた製鉄所の鍛造機が動かされた。エカテリンブルクはこの日をもって建設の日を数える。ウラルの鉱山・製鉄地帯の中心となる居住地は、ロシア帝国のシベリア路に開かれた門となった。", "8d081bcf"]},
"OLAYLAR_2S0920:1902-03-01:0":{"b": ["ザリア(ザッザウ)がイギリスの行政統制下に入る — ソコト・カリフ国のザリア首長国が北ナイジェリア保護領に従属", "c2e4131e"], "d": ["ソコト・カリフ国に属するザリア首長国は、1902年3月にイギリスの北ナイジェリアの統治下に置かれた。イギリスはザリアに駐在官と守備隊を置いた。首長クワサウは1902年7月に降伏し、9月に解任された。", "d2ce29e8"]},
"OLAYLAR_2S0920:1903-02-01:0":{"b": ["イギリスがカノを取る — ソコト・カリフ国最大の首長国が北ナイジェリア保護領に移る", "0484009d"], "d": ["北ナイジェリアの高等弁務官ラガードの命令下にあるモーランド大佐の部隊は、ザリアから出発して1903年2月にカノを奪取した。ソコト・カリフ国に属するカノ首長国はイギリスの統治に入った。ソコトは1か月後の1903年3月15日に取られた。", "33350275"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["プリシュティナがセルビア軍の手に渡る", "2ef111c0"], "d": ["第一次バルカン戦争でコソヴォに入ったセルビア軍はプリシュティナを取り、都市で再セルビア化政策が始まった。プリシュティナの陥落は、コソヴォ州におけるオスマンの抵抗の崩壊の最初の環のひとつである。", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["マナスティルのセルビア軍による占領", "db9b3353"], "d": ["第一次バルカン戦争で、マケドニアで最も重要な行政・軍事の中心のひとつであったマナスティル(ビトラ)は、5日間続いた戦闘の後にセルビア軍の手に渡った。都市の喪失は、オスマン国家のマケドニアにおける存在が事実上終わったことを意味した。", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["アルバニアの独立の宣言 — ヴロラでイスマイル・ケマリ", "2cdbd4d9"], "d": ["バルカン戦争の軍隊がアルバニア人の州に入るなか、イスマイル・ケマリはヴロラ(Avlonya)でアルバニアの独立を宣言した。ドゥラス、エルバサン、ベラト、ギロカストラ、コルチャからサランダに至る沿岸と内陸は、こうしてオスマンの統治を離れ、新たなアルバニア国家の核を形づくった。", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["オフリドとデバルにおけるオスマン支配の終焉", "5273f1ec"], "d": ["マナスティルの陥落から11日後、セルビア軍は西マケドニアの湖水地方に入った。オフリドで5世紀にわたるオスマン支配は終わり、北のデバルも同じ作戦のなかで失われた。", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["シュコドラのモンテネグロ人による占領", "db704247"], "d": ["第一次バルカン戦争で最も長い包囲のひとつがシュコドラで行われた。数か月にわたる抵抗の後、都市はモンテネグロ軍に委ねられた。シュコドラは、戦争の終わりまで持ちこたえた最後のオスマンの要塞のひとつであった。", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["モンテネグロがシュコドラを撤退 — 列強の国際軍団が都市に入る", "8a6593e9"], "d": ["列強の圧力により、モンテネグロは1913年4月23日に取ったシュコドラを1913年5月14日に撤退した。都市に国際軍団が入り、アルバニアの創設期の統治の一部となった。", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["イブン・サウードがラフサーを取る — オスマンのペルシア湾沿岸における支配の終焉", "505f26d5"], "d": ["ネジドの首長アブドゥルアズィーズ・ブン・サウードは、オスマン守備隊を追い出してラフサー地方を取り、中心をホフーフに定めた。カティーフとウカイルの港とともに、湾の西岸はサウードの統治に移った。オスマン国家の地域における50年の統治は終わった。", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["ブカレスト条約 — 西トラキアとカヴァラ盆地がブルガリアからギリシアに移る", "56123a58"], "d": ["第二次バルカン戦争は、ブルガリアとセルビア、ギリシア、モンテネグロのあいだで調印されたブカレスト条約によって終わった。第一次戦争でブルガリアの手に渡っていたカヴァラ、ドラマ、セレス盆地は、この条約によってギリシアに残された。この条約により、トゥトラカン(Turtukaya)はルーマニアに移った。", "dd427970"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["シャットゥルアラブへの上陸 — バスラの陥落とイラク戦線の開始", "c0a87d5d"], "d": ["第一次世界大戦の開始に、インドから来たイギリスの遠征軍はシャットゥルアラブ河口のファーウに上陸し、間もなくバスラを取った。都市の陥落は、イラク戦線の開始と湾の北端がイギリスの統制下に入ることを意味した。", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["ジョージアが独立を宣言 — ザカフカース・セイムが解体", "6c79a8c7"], "d": ["ブレスト・リトフスクの後に成立したザカフカース・セイムから離れたジョージアは独立を宣言し、ジョージア民主共和国が成立した。クタイシとともに西ジョージアはこの新国家の統治に移った。この宣言により、スフミ、ポティ、ズグディディ、ゴリ、テラヴィ、ドゥシェティはジョージア民主共和国に移った。", "5500d335"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["アゼルバイジャン民主共和国が宣言される", "8baecec3"], "d": ["ジョージアの分離から2日後、アゼルバイジャン民主共和国が宣言され、最初の中心はギャンジャとなった。同じ日にエレヴァンでアルメニア共和国も成立し、ザカフカースは3つの別々の国家に分かれた。この宣言により、シャマヒ、カバラ、エレシュ、シャーブラン、サリヤン、クバ、シェキ、バルダはアゼルバイジャン民主共和国に移った。", "474c35d5"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["アレッポのアラブ軍とイギリス軍による占領", "00efb2da"], "d": ["パレスチナ戦線の崩壊の後、北に進んだ軍がアレッポに入った。都市はまずアラブ、次いでイギリスの部隊の手に渡った。ムドロス休戦の3日前に起きたこの占領は、オスマン国家のシリアにおける4世紀の統治を事実上終わらせた。", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["赤軍がアゼルバイジャンを占領 — 民主共和国の終焉", "ebbb4566"], "d": ["赤軍はアゼルバイジャンに入り、議会と政府を解散させた。2年続いたアゼルバイジャン民主共和国は終わった。バクーの油田地帯とギャンジャはこうしてソヴィエトの統治に移った。この占領により、シャマヒ、カバラ、エレシュ、シャーブラン、サリヤン、クバ、シェキ、バルダはソヴィエト・ロシアの統制下に入った。", "e475b579"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["マイサルーン(Han Meyselûn) — ファイサルの時代の終焉、シリアがフランスの委任統治に移る", "80a932b0"], "d": ["ベイルート・ダマスクス道のマイサルーンで、フランス軍はシリア軍に大敗を与え、ファイサルのダマスクスにおけるアラブ王国は終わった。フランスはサン・レモで与えられた委任統治の権限を事実上確立した。アレッポからダマスクスまで、イスケンデルンからデイルッゾールまで延びる地域は、フランスの委任統治下に結びつけられた。", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["トランスヨルダン首長国の成立 — アブドゥッラー・ブン・フサインが首長国を宣言", "5ef520c2"], "d": ["シャリーフ・フサインの息子アブドゥッラーは、マアーンを経て北に来て、トランスヨルダン首長国を宣言した。イギリスは間もなくこの統治を委任統治の枠内で承認した。アンマンは首長国の中心となり、カラクを含むヨルダン高原がこの新たな統治に結びつけられた。", "113f01ba"]},
"OLAYLAR_2S0920:1941-05-03:0":{"b": ["イタリアがリュブリャナ州を王国に併合 — リュブリャナがユーゴスラヴィアから切り離される", "c451f492"], "d": ["1941年4月のユーゴスラヴィアの崩壊に際して、リュブリャナとスロヴェニアの西半分を占領したイタリアは、1941年5月3日付の布告により、地域をリュブリャナ州の名で王国に併合した。高等弁務官はグラツィオーリであった。リュブリャナはユーゴスラヴィアを離れてイタリアの統治に入った(1943年9月まで)。", "894bdb8c"]},
"OLAYLAR_2S0920:1941-05-05:0":{"b": ["ハイレ・セラシエがアディスアベバに戻る — エチオピアがイタリア領東アフリカから分離", "42470af3"], "d": ["英・エチオピア軍が4月初めにアディスアベバを取った後、皇帝ハイレ・セラシエは1941年5月5日に首都に凱旋した。イタリアの占領(1936〜41年)の正式な終わりはこの日とされる。atlasはこの日を、エチオピアのイタリア領東アフリカからの復帰の境界として用いる。", "b9c24f62"]},
"OLAYLAR_2S0920:1942-01-01:0":{"b": ["日本軍が無防備のラブアン島を占領 — イギリス領マラヤ(海峡植民地)が北ボルネオの島を失う", "a946e926"], "d": ["ボルネオ作戦の際、小規模な日本軍の部隊が防衛されていなかったラブアン島に上陸して占領した。島は1942年1月から1945年9月まで日本軍の占領下にあった。日は資料により1月1日または3日と異なる(ic_notを参照)。", "f83ac693"]},
"OLAYLAR_2S0920:1955-11-23:0":{"b": ["ココス(キーリング)諸島がシンガポール植民地から外されオーストラリアに移管", "5c2d70c7"], "d": ["イギリスの1955年のココス諸島法に基づいて出された枢密院令と、オーストラリアのココス(キーリング)諸島法1955の布告日である1955年11月23日に、諸島はシンガポール植民地の一部であることをやめ、オーストラリア連邦の権限下に入った。ホーム島(クルーニーズ=ロス家の所有地とココス・マレー人の居住地)は、この日以降オーストラリアの統治下にある。", "0edcf278"]},
"OLAYLAR_2S0920:1958-10-01:0":{"b": ["クリスマス島がイギリスからオーストラリアに移管", "c971c518"], "d": ["イギリスの1958年のクリスマス島(オーストラリアへの移管)枢密院令が1958年10月1日に発効し、島の主権はイギリスのシンガポール植民地からオーストラリア連邦に移った。フライング・フィッシュ・コーヴは島の居住・港の中心である。", "7c935123"]},
"OLAYLAR_2S0920:1991-11-18:0":{"b": ["ヴコヴァルが陥落 — ユーゴスラヴィア人民軍とセルビアの部隊が3か月の包囲の後に都市を取る", "30db2698"], "d": ["包囲されたヴコヴァルの残りのクロアチア人守備兵は1991年11月18日に降伏し、都市はユーゴスラヴィア人民軍とセルビアの勢力の手に渡った。都市はのちに国連東スラヴォニア暫定統治機構(UNTAES)の時期を経た。", "09aa356a"]},
"OLAYLAR_2S1019:0330-05-11:0":{"b": ["コンスタンティノープルがビザンツ(東ローマ)の首都として開かれた", "9d155dd6"], "d": ["コンスタンティヌスが再建させたビュザンティオンは、幾日にもわたる式典を経て、帝国の新しい首都として開かれた。アトラスのビザンツ(東ローマ)の記録は、コンスタンティノープルにおいてこの日から始まる。", "c4468b48"]},
"OLAYLAR_2S1019:0969-07-06:0":{"b": ["ファーティマ朝がエジプトを奪った:ジャウハル・アッ=スィッキリーがフスタートに入り、カイロの礎が築かれた", "500aef7a"], "d": ["ファーティマ朝の司令官ジャウハル・アッ=スィッキリーはエジプトのイフシード朝の支配に終止符を打ってフスタートに入り、北方のマナーフに新首都カイロの宮殿と城壁を築かせた。", "d9599f90"]},
"OLAYLAR_2S1019:0990-03-31:0":{"b": ["ウカイル朝がモスルを奪った:モスルのウカイル王朝の成立", "49eb93a6"], "d": ["アブー・アッ=ザッワードはアブー・ターヒル・イブラーヒームとその子を殺してモスルを奪い、都市にブワイフ朝に従属するウカイル王朝が成立した。", "affdc0ec"]},
"OLAYLAR_2S1019:1084-12-12:0":{"b": ["クタルムシュの子スレイマン・シャーがアンティオキアをビザンツから奪った", "17d1c6f0"], "d": ["1世紀以上ビザンツの手にあったアンティオキアを、ルーム・セルジューク朝の君主スレイマン・シャーが奪った。抵抗した内城塞は1085年1月12日に降伏した。", "a6f1f783"]},
"OLAYLAR_2S1019:1098-06-03:0":{"b": ["十字軍がアンティオキアを奪った:アンティオキア公国の成立", "c9f47942"], "d": ["長い包囲に耐えたアンティオキアは、ヤギ・スィヤーンの司令官フィールーズの裏切りによって十字軍の手に渡った。成立したアンティオキア公国はイスケンデルンも領内に含んだ。", "f6409190"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["ギヤース・アッディーン・カイフスラウがアンタルヤを征服した:セルジューク朝が地中海に到達した", "9812e629"], "d": ["ラテン人によるコンスタンティノープルの占領の後、イタリア人アルドブランディーニの手に渡っていたアンタルヤを、ラテン人の統治に不満をもつギリシア人の支援も得て、ルーム・セルジューク朝のスルタン、カイフスラウ1世が奪った。", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["イッズ・アッディーン・カイカーウスがアンタルヤをキプロス人から奪還した", "ec2446f9"], "d": ["1212年にキプロス王の支援を受けた反乱で失われたアンタルヤを、イッズ・アッディーン・カイカーウス1世が再征服し、総督職を再び Mübârizüddin Ertokuş に与えた。", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["バイバルスがヤッファを十字軍から奪った:エルサレム王国のヤッファにおける支配が終わった", "c7629d70"], "d": ["マムルーク朝のスルタン、バイバルス1世はヤッファにおける十字軍の支配に終止符を打ち、都市を破壊させた。内城塞の木材と大理石は、カイロの自らのモスクの建設のために送らせた。", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["バイバルスがアンティオキアを奪った:アンティオキア公国の終焉", "da2b511a"], "d": ["マムルーク軍は総攻撃でアンティオキアの城壁を越えた。170年続いた十字軍の公国は終わり、イスケンデルンも再びイスラームの領土に編入された。", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["カラマン朝がコンヤをイルハン朝から奪還した", "057ec073"], "d": ["イルハン朝のアナトリア総督 Demirtaş がエジプトに逃れた後、コンヤは再びカラマン朝の手に渡った。都市は1350年にエレトナに移ることになる。", "c2d583f3"]},
"OLAYLAR_2S1019:1344-03-26:0":{"b": ["カスティーリャ王アルフォンソ11世がアルヘシラスを奪った:20か月の包囲の後、マリーン朝の支配が終わった", "5de2a877"], "d": ["カスティーリャ王アルフォンソ11世の約20か月続いた包囲の後、1344年3月21日に始まった交渉の末、マリーン朝の君主アブー・アル=ハサンはムスリムに都市を離れるよう通告した。3月26日にビリャ・ヌエバが、翌日にビリャ・ビエハが明け渡され、カスティーリャ人は都市を接収した。アルフォンソ11世は1344年3月28日(枝の主日)に儀式をもって都市に入った。アルヘシラスは1369年までカスティーリャの手に残った。", "ceda27c4"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["ステファン・ドゥシャンがセレスをビザンツから奪った", "2cc79d36"], "d": ["ビザンツの内戦に乗じたセルビア王ステファン・ドゥシャンはセレスを奪い、都市をセルビア帝国の首都とした。", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["フェルトキルヒ伯領がハプスブルク領オーストリアに売却された", "fe4a0306"], "d": ["モンフォール=フェルトキルヒ家の最後の伯ルドルフは、1375年に全所領をオーストリア公であるハプスブルク家に売却した。実際の移譲は彼の死(1390年)によって完了した。フェルトキルヒは、フォアアールベルクでハプスブルクの手に渡った最初の大きな部分となった。", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["バルチクとドブルジャ沿岸がオスマンの統治下に入った", "dfd348b9"], "d": ["コソヴォでの勝利の後、ドブルジャ沿岸のバルチクがオスマンの統治下に入った。直後にワラキアのヴォイヴォダ、ミルチャがこの地方を占領し、オスマンの支配は1393年に再び確立されることになる。", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["Mar'aşî のサイイド家がマーハーナサルでティムールに降伏した:マーザンダラーンがティムール朝に移った", "125dbed8"], "d": ["5年にわたる遠征でマーザンダラーンに入ったティムールは、カラトガーンで立ち向かった Mar'aşî 家をマーハーナサル城塞に追い詰めて降伏させた。サーリーとアーモルで大虐殺が行われた。サーリーは Kiyâ Efrâsiyâb の子 İskender Şeyhî に与えられた。", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["シベニクが再びヴェネツィア共和国の統治下に入った", "9b7998bf"], "d": ["ナポリのラディズラーオがダルマチアに対する権利を1409年にヴェネツィアに売った後、抵抗したシベニクは、1412年に再びヴェネツィアの統治下に入った。都市は1797年に共和国が滅ぶまでヴェネツィアのダルマチア領であり続けた。", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["チェレビ・メフメトのジャンダル朝遠征:チャンクルがオスマンの庇護下にある Kasım Bey に与えられた", "da03b919"], "d": ["シェイフ・ベドレッティンのワラキアへの脱出を助けた Candaroğlu İsfendiyar Bey に対して進軍したチェレビ・メフメトは、カスタモヌに進み、İsfendiyar が退いたスィノプを包囲した。İsfendiyar はオスマンの宗主権を認めた。ウルガズ山を境界とし、オスマンに身を寄せていた子の Kasım Bey にチャンクルとその周辺が与えられた。", "f88b8d5e"]},
"OLAYLAR_2S1019:1439-08-27:0":{"b": ["スメデレヴォの攻略でヒサルジク(グロツカ)もオスマンに移った", "ab724ec9"], "d": ["3か月の包囲の後、スメデレヴォが奪われた。スメデレヴォから17km離れたヒサルジク(グロツカ)は、アトラスでは兄貴分の中心スメデレヴォの命運に従い、同じ日にセルビア専制公領からオスマンに移る(1444年に返還されることになる)。", "81989831"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["ブレゲンツ伯領の前半分がハプスブルク領オーストリアに売却された", "3a9598db"], "d": ["モンフォール=ブレゲンツの相続人であるホッホベルク家のエリーザベトは、1451年にブレゲンツ伯領の半分をハプスブルク家に売却した。残りの半分は1523年に取得された。ブレゲンツはこうしてハプスブルクのフォアアールベルクの一部となった。", "c02a452c"]},
"OLAYLAR_2S1019:1458-08-06:0":{"b": ["ゴルドゥス(コリントス)の降伏でシキオンもオスマンに移った", "c7b0d22d"], "d": ["征服王はモレア遠征で3か月の包囲の後、ゴルドゥス(コリントス)を和平によって取った。コリントスから17km離れたシキオンは、アトラスでは兄貴分の中心ゴルドゥスの命運に従い、同じ日にオスマンに移る。", "42b1e20d"]},
"OLAYLAR_2S1019:1459-06-20:0":{"b": ["スメデレヴォの降伏でヒサルジク(グロツカ)もオスマンに移った", "e3d76f5c"], "d": ["ラザル・ブランコヴィッチの未亡人ヘレナがスメデレヴォ城塞をオスマンに引き渡し、セルビア専制公領は終わった。スメデレヴォが兄貴分の中心であるヒサルジク(グロツカ)は、同じ日にオスマンに移る。", "13f15640"]},
"OLAYLAR_2S1019:1475-06-06:0":{"b": ["カッファの降伏とクリム・ハンの臣従:チェルケシア沿岸(ソチ、トゥアプセ、マイコプ)が緩やかな保護圏としてクリム・ハン国に属した", "e99eb8e8"], "d": ["4日間の包囲の後、カッファはアフメト・パシャに降伏し、メングリ・ギライはオスマンのスルタンへの臣従を受け入れた。クリム・ハンを宗主と認めるチェルケス諸部族の故地であるソチ、トゥアプセ、マイコプ周辺は、アトラスではこの日付から緩やかな保護としてクリム・ハン国に属するものとして示される。", "63b788a5"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["モスクワがブリャンスクをリトアニア大公国から奪った", "fb1c3a61"], "d": ["1500-1503年のモスクワ=リトアニア戦争でロシア軍はブリャンスクを奪い、都市はモスクワ国家に編入された。1503年の休戦がこの獲得を認めた。", "8e507991"]},
"OLAYLAR_2S1019:1500-04-12:0":{"b": ["最後のゲルツ伯レオンハルトが死去:リエンツとプスター谷がハプスブルク領オーストリア(チロル)に移った", "93331339"], "d": ["ゲルツ(ゴリツィア)伯家の最後の当主レオンハルトは1500年4月12日にリエンツで死去した。事前の相続協定に従い、リエンツとプスター谷を含む前伯領はマクシミリアン1世に移り、チロルに編入された。", "996079fc"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["ブユクル・メフメト・パシャがモスル、スィンジャル、イマーディーヤをサファヴィー朝から奪った", "3039d6af"], "d": ["コチヒサルでカラ・ハンを破ったブユクル・メフメト・パシャは、マルディンを包囲しながら周辺の城塞をサファヴィー朝から奪った。モスル、ルハ、ビレジク、スィンジャルが占領され、イマーディーヤとその他のクルドの領主はオスマンの宗主権を受け入れた。マルディン城塞はパシャがマルジュ・ダービクから戻った後に接収されることになる。", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["グスタフ・ヴァーサがストレングネースで王に選出された:スウェーデン王国がカルマル同盟から離脱した", "a6e95f4c"], "d": ["ストックホルムの血浴(1520年)の後、デンマーク王クリスチャン2世に対して蜂起したグスタフ・エリクソン・ヴァーサは、1523年5月にストレングネースで開かれたスウェーデンの議会で、1523年6月6日に王に選出された。スウェーデンとそれに属するフィンランドは、こうして1397年から続いたカルマル同盟から決定的に離脱し、独立したスウェーデン王国のヴァーサ朝時代が始まった。", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["シュレージエンの身分制議会がフェルディナント1世を王と認めた:シュレージエンがハプスブルク領オーストリアに移った", "a28e10c2"], "d": ["モハーチでのラヨシュ2世の死によって空位となったボヘミア王冠に1526年10月に選出されたハプスブルク家のフェルディナントを、上シュレージエンと下シュレージエンの身分制議会は、総会で特権の確認を条件に、1526年12月5日に王、妃のアンナを王妃と認めた。シュレージエンの諸公領はこうしてボヘミア王冠とともにハプスブルクの統治下に入った。", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["スウェーデン王グスタフ・ヴァーサがヘルシンキを建設した", "43468b54"], "d": ["スウェーデン王グスタフ・ヴァーサは1550年、ヴァンター川の河口に、レヴァル(タリン)とバルト海交易で競わせるための新たな交易都市としてヘルシンキを建設させた。都市は1640年に現在の場所、海に面した方へ移された。", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["オマーンのヤアルビ朝のイマーム、ナースィル・ブン・ムルシドがジュルファールをポルトガルから奪った", "6ca9fb0c"], "d": ["1622年のホルムズの陥落後もジュルファールに踏みとどまっていたポルトガル人は、オマーンのヤアルビ朝のイマーム、ナースィル・ブン・ムルシドが1633年に攻略したことで、この地域から追われた。", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["スィン(Sinj)城塞のヴェネツィアへの喪失:ダルマチア内陸部", "3af8e103"], "d": ["モレア戦争の際、ヴェネツィア軍は1686年にダルマチア内陸部のスィン(Sinj)城塞をオスマンから奪った。城塞は1715年のオスマンの包囲にも耐え、ヴェネツィアの手に残った。", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["ヴァラディンとバチがハンガリー王国(ハプスブルク王冠)の手に渡ったこと:モハーチの後のバチュカからの撤退", "6bc2b1ac"], "d": ["モハーチの敗戦から退いた Sarı Süleyman Paşa の軍は1687年9月1日にヴァラディンを通過し、城塞を Câfer Paşa に残した。まもなくヴァラディンとバチュカのバチは同盟するハプスブルク軍の手に渡った。カルロヴィッツでサヴァ川が国境と認められたため、ヴァラディンはオーストリア側に残った。", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["オシエクがハンガリー王国(ハプスブルク王冠)の手に渡ったこと:スラヴォニア喪失の始まり", "7af97ffe"], "d": ["モハーチの敗戦の後、ドラヴァ川上の橋頭堡の城塞オシエクは1687年9月26日にハプスブルク軍の手に渡った。スラヴォニアにおけるオスマンの軍事的存在とテュルク系住民は、1686-1688年の間に徐々に撤退した。地方はハプスブルクの統治下に入った。", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["ヘルツェグ・ノヴィのヴェネツィアへの喪失:コトル湾の入口", "b88046d8"], "d": ["モレア戦争の際、ヴェネツィア艦隊とその同盟軍は1687年にコトル湾の入口にあるヘルツェグ・ノヴィ城塞を包囲して奪った。都市は1797年にヴェネツィア共和国が滅ぶまでヴェネツィアの手にあった。", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["コルシカのイギリス王冠への帰属:英国=コルシカ王国", "10f18bde"], "d": ["革命フランスに対して蜂起したパオリは、イギリス艦隊の支援を得て島からフランスの守備隊を一掃した。コルテで開かれたコンスルタは、コルシカをイギリス王に結びつける憲法を採択した。島は2年間、英国=コルシカ王国として、イギリス総督ギルバート・エリオットの統治下にあった。", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["イギリスのコルシカ撤退:島が再びフランスに帰属", "c9f986fe"], "d": ["ボナパルトのイタリアでの勝利とスペインのフランス側への転換により、地中海で窮地に陥ったイギリスはコルシカから撤退した。英国=コルシカ王国は終わり、島は再びフランスに帰属した。", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["オーストリア=ハンガリー軍が抵抗を破ってビハチを奪った", "ffec53e0"], "d": ["ベルリン条約でボスニア・ヘルツェゴヴィナの占領権を得たオーストリア=ハンガリーは、ビハチで現地のムスリムの抵抗に遭った。ヴィルヘルム・フォン・ラインレンダー将軍の指揮する部隊は1878年9月18日に都市を奪い、ウナ川流域のオストロヴィツァの守備隊も同じ作戦でオスマンの手を離れた。", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["イギリスがソコトを占領した:ソコト・カリフ国が首都を失った", "e744f986"], "d": ["1900年に北ナイジェリアを植民地と宣言したイギリスの総督ラガードは、首長国を次々に奪った後、ソコト軍に大敗を与え、1903年3月15日に首都を占領した。逃れたカリフの Tâhir が7月にブルミで殺害されたことで、カリフ国の政治的支配は終わった。", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["イブン・サウードがラシード家の首長を破った:カスィームがシャンマル首長国からサウード家の手に移った", "a32201dd"], "d": ["1902年にリヤドを奪回したアブド・アル=アズィーズ・ブン・サウードは、1906年4月13日にラシード家の首長アブド・アル=アズィーズ・ブン・ミトイブを破って殺害した。この戦いの後、カスィーム地方(ブライダ、ウナイザ)を手に入れた。ラシード家はこれ以後ハーイルとその周辺のみを統治した。", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["カマラン島がイギリスに占領された", "c514bb66"], "d": ["紅海のイエメン沿岸にあるカマラン島は、第一次世界大戦中の1915年にイギリスに占領され、アデンから統治されるようになった。", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["ナーブルスのイギリスによる占領:パレスチナ戦線の崩壊", "b5e85950"], "d": ["1918年9月のパレスチナ戦線でのアレンビーの大攻勢はオスマンの第7軍と第8軍を壊滅させた。ナーブルスはイギリスの手に渡り、都市における4世紀のオスマンの支配は終わった。都市は1920年までイギリスの軍政下にあった。", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["イギリス軍のモスル入城:モスル州の休戦協定に反する占領", "ed5e8e33"], "d": ["ムドロス休戦協定が調印された時、モスルはテュルク軍の手にあった。イギリス軍は休戦協定第7条を根拠として1918年11月8日(または10日)に都市に入り、11月15日にテュルク軍部隊は州から撤退せざるをえなかった。モスル問題はローザンヌでも解決できず、1926年のアンカラ条約に持ち越された。", "168f5310"]},
"OLAYLAR_2S1114D5:1923-07-24:0":{"b": ["ローザンヌ条約:パトモスがイタリアに残された。エーゲ海諸島におけるギリシアの主権が確認された", "185960b3"], "d": ["ローザンヌ条約第15条によって、トルコはパトモスを含むドデカネス諸島に関するすべての権利と権原をイタリアのために放棄した。諸島は1912年から事実上イタリアの占領下にあった。第12条はリムノス、サモトラキ、ミディッリ、ヒオス、サモス、イカリアに対するギリシアの主権を確認した。Bozbaba(アイオス・ストラティス)とフルニは1912年からギリシアの手にあり、ローザンヌの後もギリシアに残った。この2島の名そのものはローザンヌ条約第12条には挙げられていない。", "73a0b71c"]},
"OLAYLAR_2S1114D5:1935-12-25:0":{"b": ["トゥンジェリ法:デルスィム県に代わってトゥンジェリ県が設けられた(中心はカラン)", "1ae9ad50"], "d": ["法律第2885号によって、デルスィム地方にトゥンジェリという名の新たな県を設けることが決められた。県の行政中心はカラン集落となり、集落は後にトゥンジェリの名を得た。地方はトルコ共和国の内にとどまった。変わったのは行政上の地位と名称である。", "7970d4ac"]},
"OLAYLAR_2S1114D5:1956-03-02:0":{"b": ["モロッコの独立:フランスの保護領が終わり、サレとラバトがモロッコ王国に残された", "a62a3fdb"], "d": ["1956年3月2日に調印された独立条約によって、1912年から続いたフランスの保護領は終わった。サレとラバトは独立したモロッコ王国の領土となった。スペインは1956年4月5日にモロッコの独立を承認した。", "e888afb6"]},
"OLAYLAR_2S1114D5:1980-07-30:0":{"b": ["ニューヘブリディーズが独立:バヌアツ共和国の成立", "cc93330f"], "d": ["フランスとイギリスの共同統治下にあったニューヘブリディーズ共同統治領は、1980年7月30日にバヌアツの名で独立した。エファテ島の首都ポートビラとテウマ集落は、共同統治領の統治からバヌアツに移った。", "29b000d6"]},
"OLAYLAR_2S1114D5:1994-03-01:0":{"b": ["南アフリカがウォルビスベイをナミビアに引き渡した", "96bb0184"], "d": ["南アフリカ共和国は1994年3月1日、ウォルビスベイの港と沖合の12の島をナミビア政府に引き渡した。84年に及ぶ南アフリカの支配は終わった。", "fdd93117"]},
"OLAYLAR_2S_0918:1284-01-01:0":{"b": ["ベオグラードとマチュヴァがハンガリー王によりドラグティンに与えられる", "a4c2c535"], "d": ["1282年に退位したセルビア王ステファン・ドラグティンに、ハンガリー王は1284年にマチュヴァとベオグラードの統治を与えた。ベオグラードは30年以上にわたりドラグティンの手にあった(ハンガリーの従属下のスレム王国)。", "2fb699cd"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["アランヤ(アライイェ)がセルジューク朝後の時期に地方侯国の統制下に入る", "7b1489b3"], "d": ["アナトリア・セルジューク国家が1290年代に事実上解体したことで、地中海沿岸のアライイェ(アランヤ)の港は中央の権威から独立し、地域の侯国(この時期にはカラマン家の勢力圏)の統制下に入った。正確な日付とどの侯国が直接支配したかは、資料に明確でない。", "78a4ff46"]},
"OLAYLAR_2S_0918:1319-01-01:0":{"b": ["ハンガリー人がベオグラードをミルティンから取り戻す", "16d254a2"], "d": ["ドラグティンの1316年の死の後、セルビアはベオグラードを保持しようとし、ハンガリーは返還を求めた。1319年にハンガリー人が攻撃し、数か月にわたる戦闘の後にセルビア軍は撤退し、都市は荒廃したままハンガリーのマチュヴァ太守領に編入された。ベオグラードは、1403〜04年にステファン・ラザレヴィチに譲られるまでハンガリーの統治下にあった。", "feb8ea91"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["スィノプがガージ・チェレビに奪取され、チャンダル侯国の影響下に入る", "f107586a"], "d": ["イルハン朝の支配の弱まりとともにカスタモヌとスィノプの地方で強まったチャンダル(イスフェンディヤル)侯国の創設家に属するガージ・チェレビは、1322年ごろにスィノプを奪取し、都市を侯国の港の中心とした。", "35c2fa9c"]},
"OLAYLAR_2S_0918:1322-03-01:0":{"b": ["シベニクがシュビッチ家とヴェネツィアのあいだに挟まれ、ヴェネツィアに従属", "99b341e0"], "d": ["クロアチアの領主ブリビル家のシュビッチ伯とヴェネツィアのあいだに挟まれたシベニクは、1322年3月1日に自らをヴェネツィアに委ね、1357年までヴェネツィア統治下にとどまった。", "120581de"]},
"OLAYLAR_2S_0918:1322-04-17:0":{"b": ["トロギルがブリビル家の諸侯に対抗してヴェネツィアに従属", "4ccf9ce4"], "d": ["ブリビル家のシュビッチ伯の圧力下にあったトロギルは、自由を守るために1322年4月17日に自らをヴェネツィアに委ね、1357年までヴェネツィアの保護下にとどまった。", "e69237c1"]},
"OLAYLAR_2S_0918:1327-09-18:0":{"b": ["スプリトにおけるハンガリーの主権が終わる — ヴェネツィアの統治が始まる", "4b04ca1a"], "d": ["スプリト・コムーネにおける1133年から続いたハンガリーの主権は、1327年9月18日に終わった。都市はヴェネツィアの統治に入り、1357年までそこにとどまった。", "75ef7dfc"]},
"OLAYLAR_2S_0918:1357-01-01:0":{"b": ["スプリトにおけるヴェネツィアの統治が終わる — ハンガリーの支配が再開", "e99628fc"], "d": ["スプリトで1327年に始まったヴェネツィアの統治は1357年に終わった。都市は再びハンガリーの直接の支配に入った(1420年まで)。", "84447172"]},
"OLAYLAR_2S_0918:1357-07-09:0":{"b": ["トロギルがヴェネツィアの保護を離れる — ハンガリーの支配が再開", "7f112aa8"], "d": ["トロギルは1357年7月9日までヴェネツィアの保護と統治の下にあった。アンジュー家のラヨシュがダルマチアをヴェネツィアから切り離し始めたとき、この保護を離れてクロアチア・ハンガリー王国の主権に戻った。", "6a7c7a44"]},
"OLAYLAR_2S_0918:1357-12-14:0":{"b": ["シベニクがヴェネツィアから離れる — ハンガリーの支配に移る", "adb9d6ca"], "d": ["シベニクは、アンジュー家のラヨシュがダルマチアをヴェネツィアから切り離しつつあった1357年12月14日にヴェネツィアから離れ、ハンガリーの支配に入った。", "7af69a3b"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["ザダル条約 — ドゥブロヴニクがヴェネツィアからハンガリーの保護に移る", "57fb81f9"], "d": ["1358年2月18日に調印されたザダル条約は、ヴェネツィアのダルマチアにおける150年の支配に終止符を打った。ドゥブロヴニク(ラグーザ)はこうしてヴェネツィアの統治を離れ、ハンガリー王ラヨシュ1世の保護下に入る半自治の共和国の地位を得た。", "e207c893"]},
"OLAYLAR_2S_0918:1358-05-27:0":{"b": ["ヴィシェグラード特権 — ドゥブロヴニクがハンガリー王ラヨシュ1世に従属", "9d3d02a8"], "d": ["ザダル和約(1358年2月)によりヴェネツィアがダルマチアに対する権利を放棄すると、ドゥブロヴニクは国王ラヨシュ1世と個別に交渉した。1358年5月にヴィシェグラード特権によりハンガリー王冠に従属した(保護の見返りとして忠誠、毎年の貢納、兵の提供)。", "d37ccc8a"]},
"OLAYLAR_2S_0918:1390-06-01:0":{"b": ["ボスニア王トヴルトコ1世がダルマチア沿岸都市(シベニクを含む)の支配権を取得", "c53aad4d"], "d": ["ボスニア王トヴルトコ1世は1390年にザダルを除くダルマチア沿岸都市の支配権を得た。シベニクもハンガリーの支配を離れ、ボスニア王の優位を承認した。", "dfb86467"]},
"OLAYLAR_2S_0918:1391-01-01:0":{"b": ["トヴルトコ1世の死。シベニクがハンガリーの支配に戻る", "ef2d3b2f"], "d": ["ボスニア王トヴルトコ1世が1391年に死ぬと、シベニクに対するボスニアの優位は終わり、都市はハンガリー王ジギスムントの支配に入った(1391〜1402年)。", "0f8c4ab3"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["エルズルムとアシュカレの地方がカラ・コユンルとティムール朝の争いのなかで支配者を替える", "ca64775a"], "d": ["ティムールの1405年の死の後に生じた権力の空白のなかで、カラ・コユンルの君主カラ・ユースフは、1406〜1408年に東アナトリアのティムール朝の総督たちに対して行動を起こした。エルズルムとその周辺のアシュカレは、この争いでティムール朝の統制を離れ、カラ・コユンルの影響下に入った。", "10b1b07c"]},
"OLAYLAR_2S_0918:1409-07-31:0":{"b": ["ザダルがヴェネツィアの統治に入る — サンタ・イントラーダ", "820c9276"], "d": ["ナポリ王ラディスラーオがダルマチアをヴェネツィアに売却した後、ザダルの住民はナポリ兵を都市から追い出した。1409年7月31日にヴェネツィアの総督代理(プロヴヴェディトーレ)が都市に入り、1797年まで続くヴェネツィアの統治を確立した。", "06e4d6fa"]},
"OLAYLAR_2S_0918:1420-06-22:0":{"b": ["トロギルがヴェネツィアの統治に入る", "fbca501f"], "d": ["ヴェネツィアがハンガリーと戦っていたとき、総司令官ピエロ・ロレダンの艦隊の到着により、1420年6月22日にトロギルはヴェネツィアの統治に移った。ダルマチア諸都市の最後にヴェネツィアに加わった都市は、1797年までヴェネツィアの旗の下にとどまった。", "8ebaf8eb"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["アク・コユンルのウズン・ハサンが、ヒスン・カイファのアイユーブ家の支流を消す", "2b464a1f"], "d": ["上チグリスで、ハマとともにアイユーブ朝の生き残った最後の二つの支流のひとつであったヒスン・カイファ(ハサンケイフ)とスィイルトは、1462年にアク・コユンルの君主ウズン・ハサンによって併合され、アイユーブの支配に終止符が打たれた。", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["ポルトガルがホルムズ海峡沿岸における支配を完成させる", "bef031f0"], "d": ["アフォンソ・デ・アルブケルケが1507年に始めたペルシア湾遠征は、1515年にホルムズ島と対岸のケシュム、ブライミを含む形で完成した。イランに従属するホルムズ王国は事実上ポルトガルの保護下に入り、ポルトガルは湾岸の貿易の統制を握った。", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["ルブリン合同 — ウクライナの土地がリトアニアからポーランドに移る", "1881ceff"], "d": ["1569年7月1日に調印されたルブリン合同は、リトアニア大公国とポーランド王国をひとつの国家(Rzeczpospolita)に統合した。合意の条件により、ポドリア、ヴォルィーニ、キエフ地方(Bar、Berdiçev、Białystok、Braslavを含む)は、行政上リトアニアからポーランド王国に直接移された。", "184b03dd"]},
"OLAYLAR_2S_0918:1776-02-14:0":{"b": ["フィウメの統治がハンガリー王冠に従属するクロアチアに移管", "dfedccf8"], "d": ["女帝マリア・テレジアは1776年2月14日の勅令により、フィウメの統治をザグレブ評議会を通じてハンガリーに与えた。1779年の証書は、都市をハンガリー王冠に直接従属する別個の体(corpus separatum)とした。", "bbf160dd"]},
"OLAYLAR_2S_0918:1809-10-14:0":{"b": ["フィウメがシェーンブルンの和約によりフランスに割譲(イリュリア諸州)", "16bf1fca"], "d": ["1809年10月14日のシェーンブルンの和約により、フィウメはオーストリアからフランスに移り、1813年までナポレオンのイリュリア諸州の一部となった。", "417a8ae7"]},
"OLAYLAR_2S_0918:1813-01-01:0":{"b": ["フィウメのフランス領イリュリア統治からハプスブルクへの復帰", "1b5b9954"], "d": ["1813年、ナポレオンのロシアでの敗北の後、フィウメはイリュリア諸州を離れてオーストリア帝国に戻った。", "5db16c92"]},
"OLAYLAR_2S_0918:1822-10-15:0":{"b": ["フィウメがハンガリー王国に返還される", "aafdd0ee"], "d": ["フランツ1世の1822年7月5日の決定の後、ハンガリー政府の名のもとでマイラート・ジェルジュ伯が1822年10月15日に都市を引き取り、フィウメはハンガリー王国に戻った。", "e30af380"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["エジプト軍がアフサー(ラフサー)地方から撤退", "5ea75c8d"], "d": ["ムハンマド・アリー・パシャのエジプト軍は、1836年にネジドと東アラビア(アフサー、カティーフ、ウカイル、ジュバイルを含む)を占領していた。1840年のロンドン海峡条約がエジプトにアラビア半島での征服を放棄させたことで、軍は1841年に地域から撤退し、統治は再び地元の勢力(サウード家/アール・ハリーファの影響)に戻った。", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["アク・メチト要塞がロシア軍に奪取される — コーカンド・ハン国のシルダリヤ線が崩壊", "e9f9a9c7"], "d": ["将軍ヴァシーリー・ペロフスキーの指揮するロシア軍は、コーカンド・ハン国に属するシルダリヤ沿岸のアク・メチト要塞を、1853年7月に長い包囲の末に奪取した。要塞はのちにペロフスクの名でロシア領トルキスタンの前哨となった。", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["ゲオク・テペの戦い — アハル・テケ・トルクメンがロシアに敗れる", "76c7a102"], "d": ["将軍ミハイル・スコベレフの指揮するロシア軍は、1881年1月24日にゲオク・テペ(Geok Tepe)要塞を陥落させ、アハル・テケ・トルクメンの抵抗を砕いた。ディヒスタン平原、アビヴェルド、ニサを含む外カスピ地方のトルクメンの地は、ロシア帝国に編入される過程に入った(外カスピ州は1881年に設置された)。この事件により、Kızılarvatとアシガバート(アハル・トルクメンの土地)はロシアに移った。", "f294fbe6"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["ルーマニア王国の宣言 — 公国が王国に転換", "4d413f0c"], "d": ["1877〜78年のオスマン・ロシア戦争の後、ベルリン会議で独立が承認されたルーマニア公国は、1881年3月26日(ユリウス暦では3月14日)に国王カロル1世が戴冠して王国に転換された。Babadağı、Birlad、Buzău、首都ブカレストを含む全土が行政上新しい王国の一部となった。王国の宣言により、ルーマニアの全体(ヤシ、Kalas、ブライラ、コンスタンツァ、トゥルチャ、Calafatとその他の都市)がルーマニア王国となった。", "fbab3abf"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["イタリアがアスマラとケレンを含むエリトリア高原を併合", "31308dc8"], "d": ["エチオピア皇帝ヨハンネス4世が1889年に死んで生じた権力の空白を利用したイタリアは、ウッチャリ(ウチャレ)条約(1889年5月2日)の後、アスマラとケレンを含むエリトリア高原を事実上併合した。1890年1月1日に正式に「エリトリア」の名で植民地が宣言された。この事件により、Kereneはイタリアの統治に移った。", "b6bbb0a5"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["ケニアの北東地域(ガリッサ・マルサビット線)がイギリス領東アフリカ保護領に編入", "e45c6d43"], "d": ["イギリス東アフリカ会社の特許が1895年に王室に移されて成立したイギリス領東アフリカ保護領は、ガリッサ、キトゥイ、マルサビット、ワジル(Wajir)など北東の地域をも含むように拡大した。これらの内陸地方の実効統治への取り込みは、1890年代の後半に及んだ。", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["イロリン首長国が王立ニジェール会社軍によって奪取される", "b111cb7d"], "d": ["ソコト・カリフ国に従属するイロリン首長国は、ジョージ・ゴールディ卿の指揮する王立ニジェール会社軍の1897年2月の遠征で奪取された。首長国の軍事力は砕かれ、地域は事実上イギリスの影響下に入った(正式な併合は1900年の北ナイジェリア保護領の成立で完了した)。", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["ブニョロ王カバレガが捕らえられ、王国がイギリス領ウガンダ保護領に従属", "62bc7c64"], "d": ["1894年からイギリス軍に抵抗していたブニョロ王カバレガは、1899年4月9日にランゴ地方(ドコロ近く)で捕らえられ、セーシェルに追放された。首都ホイマとマシンディを含む王国の領土は、イギリス領ウガンダ保護領に編入された。", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["トロ条約 — トロ王国がイギリス領ウガンダ保護領の自治的な一部となる", "c55340a2"], "d": ["1899年のブニョロの陥落の後、隣のトロ王国は、1896年から続いていたイギリスの保護を、1900年のウガンダ協定の枠内で公式化した。首都フォート・ポータルを含む王国は、イギリス領ウガンダ保護領のなかで自治的な地方統治の地位を得た。", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["アダマワ首長国がドイツとイギリスのあいだで分割される", "b9230d3d"], "d": ["ソコト・カリフ国に従属するアダマワ(Fombina)首長国は、ドイツとイギリスの植民地軍の1899〜1901年の遠征の末に二つに分割された。東部(Garua、Banyo、Marua、Ngaunderを含む)はドイツ領カメルーンに、西部(首都Yola)はイギリス領北ナイジェリアに編入された。首長Zübeyrは追放された。この事件により、Rey Buba(アダマワ(ドイツの持分))はドイツ領カメルーンの統治に移った。", "e3ebfafa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["ティトの戦い — アハッガルのトゥアレグがフランス軍に敗れる", "831143d6"], "d": ["コトゥネスト遠征の際の1902年5月7日にティトのオアシス近くで行われた戦いで、フランス軍はケル・アハッガルのトゥアレグを決定的に破った。アハッガルの中心アバレッサとイデレスを含むサハラのこの内陸地方は、フランス領アルジェリアの統制下に入った。", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["フランス軍がウバンギ・シャリの内陸部(バンバリ・ブリア線)を掌握", "0b9a9f72"], "d": ["フランス領コンゴの北方遠征は、1900年代初頭にバンバリ、バタンガフォ、ボサンゴア、ブリアを含むウバンギ・シャリの内陸地方を事実上統制下に置いた。地域は1903年12月29日に正式にウバンギ・シャリ植民地として組織された(フランス領赤道アフリカの一部)。", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["スルタン・ムハンマド・アッ=サヌーシーのダール・アル=クーティ・スルタン国がフランス軍によって排除される", "644b2c3f"], "d": ["1897年にフランスの保護下に入った、首都をンデレとする奴隷貿易を基盤としたダール・アル=クーティ・スルタン国は、スルタン・ムハンマド・アッ=サヌーシーがフランスの権威に抵抗を続けたため、1911年に行われた遠征によって事実上排除された。サヌーシーは戦闘で殺され、スルタン国は1912年に正式に廃止された。", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["リヴォニア騎士団がクライペダ(メーメル)の土地をドイツ騎士団のプロイセン支部に譲渡", "e61e5d50"], "d": ["リヴォニア騎士団は、ネマン川河口のクライペダ(メーメル)城とその周辺の土地を、ドイツ騎士団のプロイセン支部に譲った。クールラント司教も自らの持分を1392年に同じ支部に譲渡した。クライペダは1411年のトルンと1422年のメルノの和約により騎士団にとどまり、1525年にプロイセン公国に移った。", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["ウムル・ベイがイズミルの港の城をジェノヴァ人から奪う", "ab92d96e"], "d": ["アイドゥン家のウムル・ベイは、ラテン人の手に残っていたイズミルの港の城を2年半包囲した。城のジェノヴァ人統治者マルティーノ・ザッカリアは、城を引き渡してヒオス島へ去った。", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["スタイ家のİbrâhim Şahがディヤルバクルを支配", "179196cf"], "d": ["イルハン朝国家の解体の後、ジャライル家とチョパン家のあいだの争いの舞台となったディヤルバクル地方を、スタイ家のİbrâhim Şahが支配した。その支配は1353年まで続いた。", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["ベラトがビザンツからセルビアの手に渡る — ステファン・ドゥシャンのアルバニア征服", "1eba202e"], "d": ["1281年にアンジュー家の包囲を破り、その時以来ビザンツのアドリア海における最後の州の中心であったベラト城は、ビザンツの内戦が続くなか、ステファン・ドゥシャンのアルバニア進出でセルビアの手に渡った。クルヤが1343年5月または6月に降伏したのち、ベラト、カニナ、アヴロナは2年のうちにセルビア人のものとなり、州の長にはドゥシャンの義兄弟ジョン・コムネノス・アセンが据えられた。", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["アブドゥルワード朝(ザイヤーン朝)がトレムセンでマリーン朝の支配から脱する", "a4aa9573"], "d": ["トレムセンのアブドゥルワード朝は、ウスマーン2世とその兄弟アブー・サービトの指導のもとでマリーン朝の支配から脱した。この独立は短命であった。", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["Bayram Hocaが独立を獲得 — カラ・コユンル侯国の誕生", "37964815"], "d": ["カラ・コユンルの最初のベイとされるBayram Hocaは、スタイ家の君主Akçasakal Hüseyin Beyを殺して独立を獲得した。モスルを取り、その統治を兄弟のBirdi Hocaに委ねた。", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["İbrâhim Şahの死によりディヤルバクルがジャライル家の統治に入る", "11c338ef"], "d": ["1343年からディヤルバクル地方を支配していたスタイ家のİbrâhim Şahの死により、地方はジャライル家の統治に入った。", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["エネズがジェノヴァの統治に移る(ガッティルジオ家)", "5dc12940"], "d": ["ビザンツの時代に重要な港町であったエネズは、1355年にジェノヴァの統治に移り、ガッティルジオ家が治めた。", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["リトアニア大公アルギルダス(オルゲルド)がブリャンスクを取る", "3cad9caf"], "d": ["リトアニア大公アルギルダスの軍がブリャンスクを取った。都市は1500年までリトアニア大公国に従属した。", "03107c6d"]},
"OLAYLAR_2S_0919:1362-01-01:0":{"b": ["キエフ公国がリトアニアの主権下に移る", "c4fda115"], "d": ["キエフ公国はリトアニアの主権下に入り、リトアニア・ルーシ国家のなかでゲディミナス家系の公たちが治める従属公国となった。", "d4a2f5ec"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["İnançoğlu家がゲルミヤン家の支配を承認", "0679db27"], "d": ["デニズリ周辺を治めていたİnançoğlu侯国は、おそらく1368年にゲルミヤン家の支配を承認した。", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["テッサロニキのデスポトであるマヌエルが、セレスとドラマの地方をビザンツの統治下に置く", "abb99c3e"], "d": ["チルメン(1371年9月26日)でヴカシン王とセレスのデスポトであるウグリェシャが死ぬと、セレス地方におけるセルビアの統治は終わった。テッサロニキで統治していたビザンツの皇子マヌエル2世パレオロゴスは、1371年11月にセレスとドラマを含む地方をビザンツの統治下に置いた。地方は1383年9月にオスマンに移った。", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["Pîr Hüseyin Beyの死によりエルズィンジャンとバイブルトがMutahhartenに移る", "3269e55d"], "d": ["エルズィンジャンのエミールPîr Hüseyin Beyの死により、エルズィンジャンとバイブルトは、エレトナのエミールのひとりMutahhartenの手に渡った。Mutahhartenはエルズィンジャンのエミールとなった。", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["Tâceddin Beyがエレトナ軍をニクサルで破り、独立して行動する", "42982ea7"], "d": ["1379年春にニクサルを攻撃したカーディー・ブルハーネッティンとエレトナのベイAlâeddin Aliの軍を、Tâceddin Beyが破った。エレトナ侯国に税を納めるのをやめ、781年(1379年)から独立して行動した。", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["ティムールがホラズムを最終的に掌握", "ef76d2c9"], "d": ["ティムールは、1371年の最初のホラズム遠征の後、さらに3度遠征を行った。1379年の遠征で地方を最終的に掌握し、略奪し、豊富な戦利品とともに帰った。", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["ボスニア王トヴルトコ1世がヘルセグ・ノヴィを建設", "1628221a"], "d": ["ボスニア王トヴルトコ1世は、塩の交易でドゥブロヴニクに対抗するために、トプラ湾に新しい町を建設した。町はのちにノヴィ(ヘルツェグ・ノヴィ)の名で呼ばれた。", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["ティムールがカンダハールをカルト朝から取り、孫のピール・ムハンマドに与える", "84760f70"], "d": ["1281年からイルハン朝の臣下であったヘラートのカルト家の手にあったカンダハールは、ティムールのホラーサーン遠征の際に攻略され、孫のピール・ムハンマドに与えられた。都市はこの後、ティムール朝の総督によって治められた。", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["ドゥルカディル家のHalil Beyがエルビスタンをマムルークから取り戻す", "ee3da686"], "d": ["1381年にマムルークの手に渡ったエルビスタンを、1384年にドゥルカディル家のHalil Beyが取り戻した。", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["ティムールがディヤルバクル(アーミド)を攻略して略奪", "f8d200a8"], "d": ["ティムールは1394年4月25日または26日にディヤルバクルを攻略し、都市を略奪した。", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["ゲラルド・アッピアーニがピサをヴィスコンティに譲り、ピオンビーノ領主国を建てる", "ac45a9dd"], "d": ["ピサの領主ゲラルド・アッピアーニは、都市を20万フロリンでミラノの支配者ジャン・ガレアッツォ・ヴィスコンティに譲った。ピオンビーノ、スヴェレート、スカルリーノとエルバ、ピアノーザ、モンテクリスト諸島からなるピオンビーノ領主国を自らのために確保した。", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["ディヤルバクルがKarayülük Osman Beyに与えられる — アク・コユンルの支配が始まる", "38262401"], "d": ["ティムールが1394年に攻略したディヤルバクルは、1401年にKarayülük Osman Beyに与えられ、こうして地方でアク・コユンルの支配が始まった。", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["エルズィンジャンがカラ・コユンルの支配下に入る", "5729a50b"], "d": ["Mutahhartenの後、エルズィンジャンはカラ・コユンルの君主カラ・ユースフの手に渡った。カラ・ユースフは都市にまず、信頼する部下のひとりPîr Ömerを総督に任じた。", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["アスキア・ムハンマドがザーガ(ディア)を取る", "24561a8c"], "d": ["ソンガイの王位に就いたアスキア・ムハンマドは、ヒジュラ暦899年の末に、兄弟のクルミナ・ファーリ・アマル・コムザーゴを通じて、ニジェール内陸デルタの西のザーガ(ディア)市を取った。", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["シャイバーニー・ハンがブハラとサマルカンドを取る", "8f8f40eb"], "d": ["ムハンマド・シャイバーニー・ハンは、ティムール朝の混乱を利用してブハラとサマルカンドを取り、シャイバーニー朝(ウズベク)を築いた。1500〜1507年のあいだに、マーワラーアンナフル、ホラズム、ホラーサーンのほとんどすべての都市を手にした。", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["スペイン人がブジーを占領", "8faa0133"], "d": ["船で来た8000人のスペイン軍がブジーを占領し、都市の住民は恐慌に陥って故郷を去った。", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["アガデスがソンガイに従属", "997362b0"], "d": ["アイル地方の中心アガデスは、ソンガイのスルタン、アスキア・ムハンマドによってガオに従属させられた。都市は1591年のソンガイのトンディビでの崩壊まで、この従属を負った。", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["バギルミ・スルタン国の成立", "03829f94"], "d": ["ケンガ部族はBirni Besiの指導のもと、チャド湖の東のマッセニャ(Masinya)を中心とする強力な国家を築いた。バギルミ王朝の成立は慣例的に1522年とされる。", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["最後のスフォルツァ公が死に、ミラノがカール5世に移る", "53230b5c"], "d": ["ミラノ公フランチェスコ2世・スフォルツァは、1535年11月1〜2日の夜に子なくして死去した。公国は皇帝カール5世に移り、スペイン人の総督によって統治されるようになった。", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["ジェノヴァ人がタバルカ島に定住", "0cb474f8"], "d": ["カール5世がチュニスの支配者と結んだ、沿岸に要塞を築くことと珊瑚漁を許す条約により、ペッリ出身のジェノヴァ人の共同体がタバルカ島に入植させられた。島はロメッリーニ家が治める交易拠点となった。", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["フマーユーンの死後、サファヴィー朝がカンダハールをムガル朝から奪う", "318eabc8"], "d": ["フマーユーンが1556年にデリーで死んだ後、シャー・タフマースプは、カンダハールとザミーンダーワルのムガル朝の総督たちのあいだの争いを利用した。ザミーンダーワルの総督の招きで来たサファヴィー朝の部隊がカンダハールに入り、タフマースプは従兄弟の子スルタン・ホセイン・ミールザーを都市の総督に任じた。都市は1595年までサファヴィー朝の手にとどまった。", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["ロシアがリヴォニアに侵攻、ドルパトが陥落", "dcb46a8a"], "d": ["イヴァン4世はバルト海への出口を求めてリヴォニアに侵攻し、リヴォニア戦争を始めた。ナルヴァとドルパト(タルトゥ)を奪取し、レヴァルを包囲した。", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["カルロヴァツ要塞の建設", "9b28e6ad"], "d": ["クロアチアとオーストリア世襲領をオスマンから守るために、クパ川とコラナ川のあいだの氾濫原にカルロヴァツ要塞が築かれた。要塞はクロアチア軍政国境の司令官である大公カール2世が築かせた。", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["ザモシチの建設(ロカツィオ)文書", "e1157f3b"], "d": ["ポーランドの大法官ヤン・ザモイスキは、ザモシチ市の建設(ロカツィオ)文書を与えた。", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["ヤム・ザポルスキ休戦 — リヴォニアとドルパトがポーランドに移る", "7d02d8ad"], "d": ["ポーランド・リトアニアとロシアのあいだでヤム・ザポルスキ休戦が調印された。モスクワはリヴォニアに対する主張を放棄し、ポロツクの土地を返還した。ドルパト(タルトゥ)は1582年からポーランドの手にとどまった。", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["ツァリーツィン要塞が初めて文書に言及される", "ddf65b06"], "d": ["ツァーリ・フョードル・イヴァノヴィチの1589年7月2日付の勅令は、ヴォルガ川の南の国境を守るために築かれたツァリーツィン要塞に言及している。この日付が都市の建設日とされる。", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["サラトフ要塞の建設", "a3ca702c"], "d": ["サラトフは、ヴォルガ水路と国家の東の国境を遊牧民の襲撃から守るために、ザセーキン公によって要塞・哨所として築かれた。", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["ペルィム要塞の建設", "baf3e7eb"], "d": ["ヴォイヴォダのピョートル・ゴルチャコフは、タヴダ川の岸にペルィムを築いた。要塞は西シベリアにおけるロシアの進出の拠点のひとつとなった。", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["ヴェルホトゥーリエ要塞の建設", "81be29bb"], "d": ["トゥラ川の岸で、旧ネロムカル集落の跡地にヴェルホトゥーリエの要害が築かれた。その建設はシベリアへのより短い道の探索と関連している。", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["トゥラ川沿いのトゥリンスク要塞の建設", "c1d8534e"], "d": ["1600年に現在のトゥリンスクの地域に、ロシアのコサック・ヤサーク要塞(オストログ)トゥリンスクが築かれた。要塞は、ロシアの西シベリアへの進出の途上にある防備のひとつである。", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["シャー・アッバース1世がマーザンダラーンにファラハーバード市を建設", "cab4d0fe"], "d": ["サファヴィー朝の君主アッバース1世は、マーザンダラーンのカスピ海岸に近い場所にファラハーバード市を建設させ、国中から人々をここに入植させた。建設は1020年/1611年に始まった。", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["アンガラ川沿いのロシアのブラーツク要塞の建設", "e7b4be59"], "d": ["ロシアの東シベリアへの進出の際、アンガラ川のほとりにブラーツク要塞が築かれた。", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-03-08:0":{"b": ["ロスキレ条約 — スコーネ、ハッランド、ブレーキンゲ、ボーンホルムがスウェーデンに移る", "afcae41b"], "d": ["第一次カール・グスタフ戦争を終わらせたロスキレ条約が調印された。デンマーク・ノルウェーはスコーネ、ハッランド、ブレーキンゲ、ボーンホルムをスウェーデンに譲った。", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["ロシアがスーラ川沿いにペンザ要塞を建設", "49e8d90b"], "d": ["ペンザは、ペンザ川とスーラ川が合流する場所に大きな要塞として築かれた。1684年以降は、スィズラン防衛線の西端を形成した。", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["マルケットがスー・セント・マリーにフランスの伝道所を設立", "86612bcd"], "d": ["イエズス会士ジャック・マルケットは、スペリオル湖とヒューロン湖のあいだのスー・セント・マリーの急流の上に伝道所を設けた。", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["ハドソン湾会社の最初の拠点(ワスカガニッシュ)が設立される", "07b32d57"], "d": ["ジェームズ湾のルパート川の河口で、メダール・シュアール・デ・グロゼイエは、のちにハドソン湾会社の最初の拠点とされる集落を築いた。", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["スペイン植民地行政がピティック(エルモシージョ)を建設", "11e5cc04"], "d": ["スペイン植民地行政は、古い先住民の集落の跡地に町を建設した。町は1828年にホセ・マリア・ゴンサレス・デ・エルモシージョの名を取った。", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["イルティシュ・オム合流点にロシアのオムスク要塞が建設される", "13dcce5e"], "d": ["オムスクは、トボル川とイルティシュ川のあいだのイシム防衛線の東端に、要塞として築かれた。1804年に都市となった。", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["ジュンガルがラサを襲う — ラサン・ハンが殺され、チベットはジュンガルの占領下に入る", "65beea29"], "d": ["ツェリン・ドンドゥプの率いるジュンガル軍は、ホシュート部の君主ラサン・ハンが守るラサに、真夜中過ぎにあらゆる方向から攻撃した。内側からの支援を得たジュンガルは都市を奪取して略奪し、ポタラ宮も荒らした。ラサン・ハンは逃げる途中で殺された。ジュンガルはsTag-rtse-paを長とする傀儡のチベット政府を樹立した。", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["清軍がラサに入る — ジュンガルの占領が終わり、清の保護が始まる", "083358c1"], "d": ["康熙帝がチベットに送った二つの軍のうち、ガルビが指揮する四川の隊は、厳しい行軍の末にラサに達し、都市を抵抗なく取った。ジュンガルは全兵力を、北から来るココノールの軍に対してダムに集めていた。ジュンガルのチベットからの撤退により、清はラサに恒久的な保護の体制を築いた。", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["アグアヨ遠征がロス・アダエスのプレシディオを建設", "2031793a"], "d": ["アグアヨ侯爵の遠征は、ロス・アダエスにプレシディオ(軍事拠点)を築き、伝道所を再入植させた。拠点は、ヌエバ・エスパーニャにとってフランス領ルイジアナに対する東テキサスの国境の拠点となった。", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["バラバ草原にロシアのカインスク哨所が建設される", "b14552a8"], "d": ["バラバ草原に築かれた3つの恒久的なロシアの防備(哨所)のうち、カインスク哨所は、オム川の中流でカインカ川が合流する場所に築かれた。", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["ウイ川沿いにロシアのトロイツク要塞が建設される", "623d75f2"], "d": ["トロイツクは、ウイ川にウヴェルカ川が合流する場所に要塞として築かれ、1784年に都市の勅許を得た。", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["エリザヴェータの勅令によりドン川河口にテメルニク税関が設立(ロストフの核)", "46519168"], "d": ["女帝エリザヴェータ・ペトロヴナは、ドン川のテメルニク川の河口に税関を設けるよう勅令を出した。テメルニク税関はロストフ・ナ・ドヌー市の初期の歴史の始まりである。", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["フランス人がトロントのハンバー川に交易拠点を築く", "18975f4c"], "d": ["フランス人はハンバー川に2つ目の拠点を築いた。翌年、現在のエキシビション・プレイスにフォート・ルイエを建てた。", "66aeb450"]},
"OLAYLAR_2S_0919:1750-01-01:1":{"b": ["ガージャールのムハンマド・ハサン・ハーンが独立を宣言、マーザンダラーンとギーラーンを取る", "42fc62e8"], "d": ["アフシャール朝のスレイマン・シャーが退位させられると、アスタラーバードのガージャール族長ムハンマド・ハサン・ハーンは独立を宣言した。アスタラーバードとゴルガーンのほか、マーザンダラーンとギーラーンも統治下に置いた。", "f5398386"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["アフマド・シャー・ドゥッラーニーがバルフを領土に編入", "12c6bbf1"], "d": ["アフガンの君主アフマド・シャー・ドゥッラーニーは、バルフを自らの主権領域に編入した。", "e3ef9016"]},
"OLAYLAR_2S_0919:1751-01-01:1":{"b": ["カリーム・ハーン・ザンドがイスファハーンを掌握 — イランにおけるアフシャール朝の支配がザンド朝の統治に替わる", "73cdc1e8"], "d": ["ナーディル・シャーの死(1747年)の後、イスファハーンとイラーク・アジャミーは、アフシャール朝のシャー、アーディル・シャー(1747年7月6日)とイブラーヒーム・シャー(1748年12月8日)の名で治められた。カリーム・ハーン・ザンドは1751年1月にイスファハーンに戻り、状況を掌握した。ホラーサーンは、シャールフの統治のもとでアフシャール朝にとどまった。", "daab8159"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["イシム川沿いにロシアのペトロパヴロフスク要塞が建設される", "5d16ef42"], "d": ["ペトロパヴロフスクはロシアの要塞として築かれ、間もなくロシアと中央アジアおよびカザフ草原のあいだの交易の重要な中心となった。", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["アガデスのトゥアレグがBilmaの塩田をカネム・ボルヌから奪う", "1a563a74"], "d": ["18世紀に衰退していたカネム・ボルヌは、1759年にアガデスのトゥアレグがBilmaの塩田を奪ったことで、サハラの多くの居住地を失った。", "ebfc53c3"]},
"OLAYLAR_2S_0919:1759-02-13:0":{"b": ["ガージャールのムハンマド・ハサン・ハーンがカリーム・ハーン・ザンドの軍に敗れて殺される。アスタラーバード、マーザンダラーン、ギーラーンがザンド朝の統治に移る", "38f0a375"], "d": ["カリーム・ハーンの軍はガージャール家に大敗を与えた。ムハンマド・ハサン・ハーンは逃げる途中で殺され、息子のアーガー・ムハンマドはシーラーズに連れて行かれた。ガージャール侯国のカスピ海沿岸の領土はザンド朝の統治に入った。", "aa7e4a1e"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["ウスマーン・ブン・フーディーのジハード軍がザリアを取る", "41279ca7"], "d": ["ウスマーン・ブン・フーディーが始めたジハードの際、ゴビルの首都アルカラワへの最初の攻撃は失敗したが、1806年にザリアが取られた。", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["スルターナーバード(アラーク)市の建設", "674237a0"], "d": ["ガージャール朝の時代に、将軍Yûsuf Han Gürcîが現在のアラーク市を築き、スルターナーバードの名を与えた。", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["ボーフォート(ボーフォート・ウェスト)の町の建設", "c5cb1776"], "d": ["イギリスのケープ植民地で、カルーのHooyvlakte農場の上にボーフォートの町が築かれた。", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["バルフがブハラのアミールの占領を受ける", "cd255a5d"], "d": ["ドゥッラーニー朝アフガンの支配下にあったバルフは、1826年にブハラのアミールの占領を受けた。都市は1841年にアフガン人によって再び取られた。", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["ロシアがイシム川にアクモリンスク要塞を建設", "6c727ca9"], "d": ["ロシアは、イシム川のカラウトクルにアクモリンスク要塞を築き、これをシベリア・キルギス人(カザフ人)の国の中心の町とした。", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["コパル要塞の建設 — 北ジェティスーがロシアに従属し始める", "8d4c24c6"], "d": ["ロシアは、年長ジュズのカザフの要請により、ジェティスー・アラタウの麓にコパル要塞を築いた。資料によれば、これがイリ川に至る北ジェティスーのロシアへの編入を容易にした。", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["沿岸の商人がカゼ(タボラ)に定住", "173223b0"], "d": ["地元の君主との衝突の後、東アフリカ沿岸から来た商人は南に移った。ウニャニェンベの首長フンディキラが、彼らに中心地イテテミア近くの定住地を与えた。この集落はタボラの隊商の中心の核となった。", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["アル=ハーッジュ・ウマルのフラニ人がジェンネを取る", "aa4e37f8"], "d": ["マシーナ国家が守備隊を置いていたジェンネは、1861年にアル=ハーッジュ・ウマルの率いるフラニ人の手に渡った。", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["アル=ハーッジュ・ウマルがハムダッラヒを取る — マシーナ国家の終焉", "542f1c0d"], "d": ["セグーから逃れたビナ・アリが身を寄せたマシーナの同盟軍は敗れた。マシーナの中心ハムダッラヒはアル=ハーッジュ・ウマルの手に渡り、ビナ・アリとアフマドゥ・アフマドゥは処刑された。", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["ブラザがフランスヴィルを建設", "d28410d7"], "d": ["ピエール・サヴォルニャン・ド・ブラザは、ムパッサ川を見下ろす岩の突出部に、フランスの名でフランスヴィル哨所を築いた。", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["コンゴ自由国とポルトガルの国境協定 — コンゴ河口の南岸がポルトガルに", "08a16627"], "d": ["ベルリン会議のさなかに調印された協定により、コンゴ自由国とポルトガルの国境は、コンゴ(ザイール)川の河口からウアンゴ・ウアンゴ川まで、川そのものとして引かれた。ソヨのある南岸はポルトガルに、カビンダは川の北にありながらポルトガルに残された。", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["ハドラマウト沿岸(ムカッラー)がイギリスの保護下に入る", "dc824725"], "d": ["シフルとムカッラーを含むハドラマウト沿岸を支配するヤーフィイー家(クアイティー家)とイギリスのあいだで保護条約が調印された。イギリスは沿岸のヤーフィイーの統治の外交を完全に引き受けた。", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["フランスがジョロフの全域を支配", "c6d28eaa"], "d": ["部族の首長との合意によって地域を植民地化したフランスは、1890年にジョロフの全域を支配した。", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["ジェンネがフランスに占領される", "b207bf62"], "d": ["アル=ハーッジュ・ウマルが築いた国家の手にあったジェンネは、1893年にフランス軍に占領され、フランス領スーダンに編入された。", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["グウェルが軍事哨所として建設される", "bd37b323"], "d": ["現在のジンバブエ中部で、グウェル市は軍事哨所として築かれた。のちに農業の中心となり、1914年に自治体の地位を得た。", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["バギルミ・スルタン国がフランスの保護下に入る", "59f20c32"], "d": ["ラービフの脅威を前に、バギルミの君主ガヴランはフランスとやむなく保護条約を結んだ。これに反発したラービフがバギルミの占領に向かうと、ガヴランは首都マッセニャを自らの手で焼いた。", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["カッファ王国がエチオピアに編入 — 最後の王ガキ・シェローチョが捕虜となる", "c03c44c5"], "d": ["メネリク2世の、ラス・ワルダ・ギヨルギスが率いる軍は、1897年3月にカッファに入った。激しい戦闘の後にカッファは征服され、最後の王ガキ・シェローチョは1897年10月に捕らえられて降伏した。", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["ガオがフランスに占領される", "01eabb4c"], "d": ["ニジェール川岸の旧ソンガイの首都ガオは、1898年にフランスに占領された。占領の後、都市は再び大きくなり、地域の中心となった。", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["ウガンダ鉄道のナイロビ補給所の設立", "a3ce3389"], "d": ["現在のナイロビがある、それまでほとんど無人であった沼地で、イギリスはモンバサをウガンダに結ぶウガンダ鉄道の補給所を築いた。", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["アダマワが分割される — ヨラはイギリス領北ナイジェリアにとどまる", "11104686"], "d": ["アダマワは、イギリスに従属する北ナイジェリアとドイツに従属するカメルーンのあいだで分割された。アダマの四男ボッボ・アフマドゥはイギリス側の地域でヨラの首長となった。", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["ブルミの戦い — ソコト・カリフ国の政治的支配が終わる", "c7d87e2c"], "d": ["イギリスによるソコトの占領の後に逃れたカリフ、ムハンマド・ターヒルは、イギリスとの新たな戦いで殺された。約1世紀続いたソコト・カリフ国の政治的支配は終わった。", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["ナクルが正式に町として設立される", "d82a2d76"], "d": ["ウガンダ鉄道上の位置により、ナクルは正式に町として設立され、地域の農産物の中心となった。", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["オレンブルク・タシュケント鉄道でアラル海駅が開業 — アラルスク集落の建設", "85803dcb"], "d": ["ロシア帝国のオレンブルクとタシュケントを結ぶ鉄道がアラル海の北東端を通るとき、沿岸に「アラリスコエ・モーレ」駅が開業した。駅のそばに漁民の集落が生まれた。集落は1938年に都市の地位を得てアラルスクの名を取った。", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["フランスがアベシェを取る — ワダイ・スルタン国の終焉", "3c9b117b"], "d": ["東への進出を続けたフランスは、ワダイの首都アベシェ(Ebîşe)を奪取してワダイ・スルタン国を終わらせた。最後のスルタンは首都を守れずに退いた。", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["南アフリカ連邦の成立", "7434a47f"], "d": ["1909年の南アフリカ法により、ケープ、ナタール、トランスヴァール、オレンジ川の諸植民地は、1910年5月31日に大英帝国に属する南アフリカ連邦の名で統合され、行政の中心はプレトリア、立法の中心はケープタウンとなった。この統合により、ケープ、ナタール、トランスヴァール、オレンジの諸植民地の都市(キンバリー、ダーバン、ピーターマリッツバーグ、ポチェフストルーム、ポート・エリザベスなど)は南アフリカ連邦に移った。", "7fc35ce0"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["フランスがジャネットを占領", "f32997c8"], "d": ["ガトに属するオスマンの郡ジャネットは、1911年にフランスに占領された。郡長のシェイフ・アムドは、この日までオスマン国家から俸給を受けていた。", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["アンカレッジがアラスカ鉄道の中心として設立される", "f5014711"], "d": ["議会が1914年3月12日にアラスカ鉄道法を可決した後、1915年春にアラスカ技術委員会がシップ・クリークに鉄道の工事現場を設けた。沿岸にテント都市が生まれ、1915年4月に郵便局が新しい町にアンカレッジの名を与えた。都市は、北のフェアバンクスに延びるアラスカ鉄道の中心となった。", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["サヌーシー教団の砂漠の中心Cağbûbのオスマン体制への編入——アブデュルメジトの免税勅令", "039fce6d"], "d": ["長年メッカに滞在したムハンマド・ブン・アリー・サヌーシーは、トリポリタニアに戻った後、エジプト国境のCağbûbオアシスに居を定め、見晴らしのよい岩場に大きなザーウィヤを建てさせた。数軒の小屋にすぎなかった地は、短期間で都市に変わった。1856年、スルタン・アブデュルメジトの勅令により、教団員に属する財産は課税を免除され、信徒からザカートを集める権限が与えられた。この勅令は、西アフリカとスーダンをカイロに結ぶ隊商路上のオアシスを、オスマンの財政・行政制度の一部とし、Cağbûbを交易の中心として強化した。地域の人々のカリフへの忠誠は、1884年と1893年にここを訪れた大佐Sâdık el-Müeyyedの旅行記によっても裏づけられる。", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["スエズ運河の掘削開始とポートサイドの建設", "cef0be8d"], "d": ["Bâbıâliが1856年1月5日に承認したレセップスの計画の掘削作業は、1859年4月25日に始まった。運河は10年後の1869年11月16日に完成することになる。掘削の地中海側の端で、メンザラ湖と海の間の海岸砂州に労働者のために設けられた5軒の小屋の村が、ポートサイドの核となった。市には、運河会社の関係者により、当時のエジプト総督サイード・パシャに捧げて、1860年に「サイードの港」を意味するこの名が与えられた。こうしてオスマンの地図上に、それまで集落がまったくなかった海岸の細長い土地に新しい港が生まれた。", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["スルタン・アブデュルアズィズのエジプト訪問とスエズ地峡におけるイスマイリアの建設", "bcfacf38"], "d": ["スルタン・アブデュルアズィズは、大宰相Yûsuf Kâmil Paşaの勧めにより1863年4月3日にエジプトに赴き、盛大な歓迎を受けた。目的は、カヴァラのメフメト・アリー・パシャの反乱以来、事実上別個の国家の状態になりつつあった州の、中央への帰属を強めることにあった。同年、地峡のティムサーフ湖畔のTilâlülcisr丘陵に運河会社の管理拠点が設けられた。まず技術者のためにKaryetüttimsah、次いで労働者のためにKaryetülarab村が置かれた。副王イスマーイール・パシャが淡水運河に強い関心を寄せ、この丘に自らの別荘を建てさせたことから、集落は彼の名にちなんでイスマイリアと呼ばれるようになった。市の創設は1863年とされ、正確な日は不明である。", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Midhat Paşaのバグダード総督在任と部族の定住化——ラマーディーとナーシリーヤの建設", "0fa98f06"], "d": ["Şûrâ-yı Devlet議長の職から外され、イスタンブルから遠ざけられたMidhat Paşaは、モスルとバスラをも含むバグダード州を、1869-1872年のあいだ、第六軍司令官の職を兼ねる広範な権限をもって統治した。彼は土地法令と新しい州法をここで適用し、土地を地券(tapu)により分配し、遊牧部族を定住生活と国家の権威に結びつけた。この定住化政策の産物として、1869年にユーフラテス川のほとりにDülaym部族のためにラマーディーが、南部ではMüntefik県知事Nâsır Paşa es-Sa'dûnの手によってナーシリーヤが建設された。いずれもそれまで集落のなかった地点に生まれ、地図にはこの日付で初めて登場した。", "7babb36f"]},
"OLAYLAR_ALM1115B:1024-09-08:0":{"b": ["コンラート2世がドイツ王に選ばれ、マインツで戴冠した:ザリエル朝の開始", "c88123e8"], "d": ["ハインリヒ2世の死後、ドイツの諸侯は1024年9月4日にライン右岸のカンバに集まった。選挙はマインツ大司教アリボが主宰した。年長のコンラートは甥の若いコンラートに対して勝利し、聖母マリア誕生の祝日(9月8日)にマインツでアリボによって王として戴冠された。", "1d5ce932"]},
"OLAYLAR_ALM1115B:1039-06-04:0":{"b": ["皇帝コンラート2世がユトレヒトで死去した", "f967406b"], "d": ["ザリエル朝の最初の皇帝コンラート2世は、1039年6月4日に短く苦しい病の末にユトレヒトで死去した。", "6af4f169"]},
"OLAYLAR_ALM1115B:1122-09-23:0":{"b": ["ヴォルムス協約:叙任権闘争の終結", "8073e4a0"], "d": ["教皇使節の仲介により、皇帝ハインリヒ5世と教皇カリクストゥス2世の間の和約は、1122年9月23日にヴォルムス(市のすぐ脇のロブヴィーゼン)で宣言された。ハインリヒは指輪と杖による叙任を放棄し、司教と修道院長の教会法に則った選挙を受け入れた。", "a915c2e7"]},
"OLAYLAR_ALM1115B:1125-05-23:0":{"b": ["皇帝ハインリヒ5世がユトレヒトで死去した", "790cadc4"], "d": ["皇帝ハインリヒ5世は1125年5月23日にユトレヒトで死去した。ヴォルムス協約(1122年)の皇帝として記憶される。", "8402ca28"]},
"OLAYLAR_ALM1115B:1152-03-05:0":{"b": ["フリードリヒ1世バルバロッサがフランクフルトでドイツ王に選ばれた", "b91f29a3"], "d": ["諸侯は1152年3月5日にフランクフルトでフリードリヒを王位に推挙し、彼は3月9日にアーヘンで戴冠した。ホーエンシュタウフェン朝のバルバロッサの時代はこうして始まった。", "26fcdb8c"]},
"OLAYLAR_ALM1115B:1156-09-17:0":{"b": ["特許状(プリヴィレギウム・ミヌス):オーストリアが公領となり、バイエルンがハインリヒ獅子公に与えられた", "a64c125b"], "d": ["レーゲンスブルクにおける諸侯の判決によってオーストリアは公領に昇格し、ハインリヒ・ヤゾミルゴットに特別の権利が認められた。同じ取り決めでハインリヒはバイエルンを皇帝に返還し、皇帝はバイエルンをハインリヒ獅子公に封土として与えた。", "fe899d87"]},
"OLAYLAR_ALM1115B:1218-01-01:0":{"b": ["ツェーリンゲン家の断絶によってベルンが帝国自由都市となった", "1473c219"], "d": ["ツェーリンゲン家が1218年に断絶すると、ベルンは帝国に直属する自由都市となった。1353年に8番目の加盟地としてスイス盟約者団に加わった。", "8bbdceab"]},
"OLAYLAR_ALM1115B:1264-01-01:0":{"b": ["ヘッセン方伯領:ブラバント家のハインリヒ1世が初代のヘッセン方伯となり、マイセンとの和約は1264年", "57067f04"], "d": ["ヘッセンの独立した国としての歴史はハインリヒ1世(「幼児」)から始まる。マイセンとの和約は1264年に結ばれた。ハインリヒはカッセルに城を建てさせ、そこは後年の通常の居所となった。1292年に帝国諸侯身分(Reichsfürstenstand)に列せられた。", "43d237e5"]},
"OLAYLAR_ALM1115B:1358-12-01:0":{"b": ["シュヴェリーン伯領が協定によってメクレンブルク公アルブレヒト2世の手に渡った", "013b6860"], "d": ["アルブレヒト2世は1358年12月1日付の契約で、伯ニコラウスに銀1万マルクを支払ってシュヴェリーン伯領を取得した。都市はそれ以後メクレンブルク公領の領土となった(首都として定着するのは16世紀のことである)。", "1d69a777"]},
"OLAYLAR_ALM1115B:1567-03-31:0":{"b": ["方伯フィリップ「寛大公」がカッセルで死去:ヘッセンが4人の息子の間で分割された", "c0cb27ed"], "d": ["宗教改革の政治的指導者のひとりであるヘッセン方伯フィリップ1世は、1567年3月31日にカッセルで死去した。1562年の遺言に従い、国はヘッセン=カッセル(ヴィルヘルム4世)、ヘッセン=マールブルク(ルートヴィヒ4世)、ヘッセン=ラインフェルス(フィリップ2世)、ヘッセン=ダルムシュタット(ゲオルク)として4人の息子の間で分けられ、統一されたヘッセン方伯領はこうして終わった。", "288ab83b"]},
"OLAYLAR_ALM1115B:1637-03-10:0":{"b": ["最後のポンメルン公ボギスラフ14世がシュテッティンで死去:グリフェン家が断絶した", "ab96746a"], "d": ["ポンメルンの最後の公ボギスラフ14世は1637年3月10日にシュテッティンで死去し、彼とともに土着のポンメルン王家は絶えた。公領の実際の分割(ブランデンブルクとスウェーデン)は1648年のヴェストファーレン条約で確定された。", "2e5f6d25"]},
"OLAYLAR_ALM1115B:1646-01-01:0":{"b": ["フェルディナント3世がブレーメンに帝国自由都市の特権を与えた", "174142ee"], "d": ["皇帝フェルディナント3世は1646年にブレーメンに帝国自由都市の特権を認めた。スウェーデンはこれに反対し、1666年に都市を武力で屈服させようとして失敗した。ハノーファー選帝侯は大司教領を得ると(1720年)、ブレーメンを自由都市として承認した。", "4a574693"]},
"OLAYLAR_ALM1115B:1810-01-01:0":{"b": ["ブレーメンがフランス帝国に編入された:ヴェーザー河口県の中心となった", "d5d149ae"], "d": ["ブレーメンは1806年にフランス軍に占領され、1810年から1813年までヴェーザー河口(ブーシュ=デュ=ヴェーゼル)県の中心となった。", "0ac80a63"]},
"OLAYLAR_ALM1115B:1810-12-01:0":{"b": ["ナポレオンがリューベックをフランス帝国に併合した", "1ca78afe"], "d": ["1806年11月のブリュッヒャーのリューベック近郊での降伏の後、都市はフランス軍に略奪されていたが、1810年12月にナポレオンは都市を自らの帝国に併合した。リューベックはこの時まで1226年から帝国自由都市であった。", "b7bf744b"]},
"OLAYLAR_ALM1115B:1813-01-01:0":{"b": ["リューベックがフランスの支配に対して蜂起し、自由都市の地位を取り戻した", "84e70d49"], "d": ["1813年にフランスの統治に対して蜂起したリューベックは、1815年にウィーン会議によってドイツ連邦の自由ハンザ都市として承認された。", "f5432e01"]},
"OLAYLAR_ALM1115B:1813-01-01:1":{"b": ["フランスの支配が終わった:ブレーメンが自由都市の地位を取り戻した", "4afa71be"], "d": ["ブレーメンがヴェーザー河口県の中心としてフランスの統治下にあった状態は1813年に終わった。都市は1815年にウィーン会議によって独立を回復し、ドイツ連邦に加わった。", "b4e1a2ef"]},
"OLAYLAR_ALM1115B:1815-01-01:0":{"b": ["メクレンブルク=シュヴェリーン公領が大公国の称号を得た", "3f5d05eb"], "d": ["メクレンブルク=シュヴェリーン公フリードリヒ・フランツ1世は1815年に大公国の称号(「großherzogliche Würde」)を得た。メクレンブルク公領(1348-1815年)の区分はこの時点で終わり、国はドイツ連邦の内の大公国として続く。", "bfbe2246"]},
"OLAYLAR_ALM1115B:1937-04-01:0":{"b": ["大ハンブルク法が施行された:リューベックの独立した州としての地位が終わった", "6df2f92a"], "d": ["1937年1月26日に制定された大ハンブルク法は、1937年4月1日に施行された。リューベックは700年を超える自治を失ってプロイセンのシュレースヴィヒ=ホルシュタイン州に編入され、ハンブルクの境界は拡大した。", "b96594d2"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["バラコアの建設 — キューバのスペイン征服の最初の町", "8c033cf1"], "d": ["ディエゴ・ベラスケス・デ・クエリャルは、イスパニョーラ島から率いた軍勢でキューバの征服を1511年に始め、島で最初のスペイン人の町ヌエストラ・セニョーラ・デ・ラ・アスンシオン・デ・バラコアを築いた。バラコアは、その後の20年にメキシコに向かう遠征(エルナンデス・デ・コルドバ、グリハルバ、コルテス)の基地となった。", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["セントラの戦い — ポトンチャン・マヤ侯国が陥落、サンタ・マリア・デ・ラ・ビクトリアが建設される", "8489a7d8"], "d": ["コルテスのキューバから出航した艦隊は、グリハルバ川の河口のチョンタル・マヤの都市ポトンチャンに上陸した。セントラの平原での戦いで騎兵と火器の優位によって勝ったスペイン人は、都市の跡にサンタ・マリア・デ・ラ・ビクトリアの町を築いた。これはメキシコ本土における最初の恒久的なスペイン人の居住地である。コルテスの通訳となるマリンツィン(ドーニャ・マリーナ)は、ここで贈られた品々のなかにいた。", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["パナマの建設 — 太平洋岸で最初のヨーロッパ人の都市", "c0d86c22"], "d": ["ダリエンの総督ペドラリアス・ダビラは、地峡の太平洋側にパナマ市を築き、植民地の統治をカリブ海沿岸からここに移した。都市は南に向かう探検・征服遠征の出発港となり、フランシスコ・ピサロのペルー遠征はここで整えられた。", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["テペアカの攻略 — コルテスの悲しき夜の後の最初の征服", "a9c27711"], "d": ["1520年6月30日の夜(ノーチェ・トリステ)にテノチティトランから大きな損害を出して撤退したコルテスは、トラスカラに身を寄せた後、最初の攻撃を三国同盟に従属するテペアカ侯国に対して行った。都市を取ってセグラ・デ・ラ・フロンテラの名でスペイン人の町を築き、こうしてベラクルス沿岸とトラスカラのあいだの道が確保され、首都に対する2度目の進軍の基地が整った。", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["サン・セバスティアン・デ・コリマの建設 — ヌエバ・エスパーニャの太平洋岸への進出", "30332cab"], "d": ["コルテスの指揮官のひとりゴンサロ・デ・サンドバルは、西メキシコのコリマ谷を服従させてサン・セバスティアン・デ・コリマの町を築いた。町はヌエバ・エスパーニャの太平洋岸における最初の拠点のひとつとなり、その後の年月の南海探検の造船所を支えた。", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["サン・フランシスコ・デ・キトの建設 — 北のインカの首都でスペインの秩序が始まる", "7bb9f316"], "d": ["インカの将軍ルミニャウイは、北の首都キトをスペイン人に渡す前に焼いた。セバスティアン・デ・ベナルカサルは廃墟の上にサン・フランシスコ・デ・キトを築いた。こうしてクスコに次ぐインカ国家の第2の中心もスペインの統治に服し、北アンデスの征服はここから進められた。", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["リマの建設 — スペイン領ペルーの首都がリマク谷に移る", "1f15658c"], "d": ["フランシスコ・ピサロは、山中のクスコがスペインとの海上の連絡から遠いことから、沿岸のリマク谷にシウダード・デ・ロス・レイエス(リマ)を築いた。都市は間もなくペルー副王領の首都、南アメリカにおけるスペイン統治の中心となった。", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["ポパヤンの建設 — キトとムイスカの国のあいだの橋", "bf451979"], "d": ["キトから北に進んだベナルカサルは、カウカ谷にポパヤンを築いた。都市はペルーから来たスペインの進出の北端となり、翌年ムイスカの国でケサダと遭遇する道を開いた。", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["フンサの攻略 — サケ・ケムエンチャトチャの敗北", "e8c1b661"], "d": ["マグダレーナ川から高原に上ったゴンサロ・ヒメネス・デ・ケサダは、ムイスカ連合の二つの頭のひとつ、サカスゴの中心フンサを襲い、サケ・ケムエンチャトチャを捕虜とした。都市で得られた金は、エル・ドラードの噂を育てる主な戦利品となった。ムイスカの国の北半分はこうしてスペインの支配に入った。", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["アスンシオンの建設 — パラグアイ川のスペインの拠点", "9a6dfa42"], "d": ["リオ・デ・ラ・プラタ遠征がブエノスアイレスで根づかなかったため、スペイン人は川を遡り、フアン・デ・サラサール・デ・エスピノサがグアラニーの共同体との同盟に基づいてヌエストラ・セニョーラ・デ・ラ・アスンシオンを築いた。町は1世紀にわたり、リオ・デ・ラ・プラタ流域のスペイン統治の中心であり続けた。", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["サンタ・フェ・デ・ボゴタの建設 — ムイスカの国におけるスペインの首都", "3ed6c301"], "d": ["ケサダは、シパの中心バカタの隣にサンタ・フェ・デ・ボゴタを築いた。建設の直後に、3つの別々の方向から来た征服隊 — ケサダ、ベナルカサル、ドイツ人指揮官フェーデルマン — が同じ高原で出会い、権利の主張をスペインで解決することで合意した。都市は新グラナダ王国の首都となった。", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["サン・フアン・デ・ラ・フロンテラ・デ・ワマンガの建設 — リマ・クスコ街道の錠前", "3f1cfdbf"], "d": ["マンコ・インカがビルカバンバから行った抵抗は、リマとクスコのあいだの道を断っていた。フランシスコ・ピサロはこの道を確保するために、二つの首都の中間にサン・フアン・デ・ラ・フロンテラ・デ・ワマンガを築いた。町の名の「フロンテラ」(辺境)は、建設の目的を直接に語る。", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["トゥンハがスペイン人の都市として再建される", "c3a12867"], "d": ["ケサダがスペインに戻った後、ゴンサロ・スアレス・レンドンは、サケの中心フンサの跡にトゥンハ市をスペインの秩序に従って再建した。こうしてムイスカの国の北半分は、ボゴタのそれと同じ恒久的な自治体とエンコミエンダの秩序に結びつけられた。", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["サン・フランシスコ・デ・カンペチェの建設 — ユカタン征服の3度目で恒久的な試み", "62af9901"], "d": ["ユカタンを取るための2度の失敗した遠征の後、フランシスコ・デ・モンテホ(子)は、マヤの都市カン・ペチの跡にサン・フランシスコ・デ・カンペチェの町を築いた。この港は半島の内部に進む軍勢の補給基地となり、2年後のメリダの建設に結実する遠征の出発点を形づくった。", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["サンティアゴ・デル・ヌエボ・エクストレモの建設 — チリの征服が始まる", "04cd7c3b"], "d": ["ペルーから南に進んだペドロ・デ・バルディビアは、マポチョ谷にサンティアゴ・デル・ヌエボ・エクストレモを築いた。町は同年の9月にミチマロンコの指導する先住民の攻撃で焼かれて再建された。それでもチリのスペイン征服はこの地点から進められた。", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["ソトゥタのココム侯国がスペインの支配下に入る", "db6a6487"], "d": ["ユカタン内部で最強のマヤ侯国のひとつソトゥタは、ココム王朝のもとでスペインの進出に長く抵抗した。メリダが1542年に建設された後の年月に、侯国はスペインの支配を受け入れた。1546〜47年の東部の大反乱が鎮圧された後、この服従は恒久的なものになった。", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["ビリャ・デ・オロペサの建設 — ポトシを養う穀物の谷の入植", "d6821cbf"], "d": ["総督フランシスコ・デ・トレドの命令により、コチャバンバ谷にビリャ・デ・オロペサが築かれた。谷の肥沃な土地は、ポトシの銀山の多数の労働力を養う穀物地帯として組織され、町は植民地の上ペルーの穀倉となった。", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["ビルカバンバの陥落 — 独立インカ国家の終焉", "31b5a95d"], "d": ["クスコが1533年に陥落した後、マンコ・インカとその後継者たちは、ビルカバンバの山中で40年続く独立インカ国家を維持した。総督フランシスコ・デ・トレドが組織した遠征は、放棄された首都を取った。逃れた最後の君主トゥパック・アマルは捕えられてクスコに連れてこられ、そこで処刑された。アンデス世界における4世紀のインカ王朝の政治的存在はこうして終わった。", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["モンテレイの建設 — ヌエボ・レオンの首都", "ec6e44bc"], "d": ["ディエゴ・デ・モンテマヨールは、2度の失敗した試みの後、サンタ・ルシア泉のほとりにシウダード・メトロポリターナ・デ・ヌエストラ・セニョーラ・デ・モンテレイを築いた。北の辺境のこの居住地は、ヌエバ・エスパーニャの北東(ヌエボ・レオン)への恒久的な拡大の拠点となった。", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["サン・フランシスコ・デ・ボルハの建設 — マイナスにおけるスペインの支配", "7ee32d19"], "d": ["ディエゴ・バカ・デ・ベガは、マラニョン川のポンゴ・デ・マンセリチェ峡谷の下流にサン・フランシスコ・デ・ボルハを築き、マイナス地方をスペインの統治に結びつけた。町は、上アマゾンで以後1世紀続くイエズス会の伝道所網の出発点となった。", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["サン・アントニオ・デ・バレロ伝道所の建設 — スペイン領テキサスの核", "ca9bd147"], "d": ["フランス人がルイジアナから西に浸透してくることに対して、スペインはテキサスに恒久的な拠点を築くことを決めた。オリバレス神父はサン・アントニオ川のほとりにサン・アントニオ・デ・バレロ伝道所を築き、数日後に総督アラルコンがその隣にサン・アントニオ・デ・ベハルのプレシディオを置いた。伝道所の建物はのちにアラモの名で呼ばれることになる。", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["レフヒオ(現在のマタモロス)の建設 — リオ・グランデ河口の入植", "f3b86da7"], "d": ["ホセ・デ・エスカンドンが1740年代から進めたヌエボ・サンタンデール入植計画は、リオ・グランデの下流域を農場と町で満たした。ヌエストラ・セニョーラ・デル・レフヒオ・デ・ロス・エステロスは、川の南岸でこの計画の最後の環のひとつとして築かれ、19世紀にマタモロスの名を取った。", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["中央アメリカ独立宣言 — グアテマラ総督領がスペインから分離", "f998089a"], "d": ["メキシコのイグアラ綱領の後にグアテマラで招集された議会は、総督領のスペインからの独立を宣言した。総督ガビーノ・ガインサは移行政権の長にとどまった。こうして現在のグアテマラ、エルサルバドル、ホンジュラス、ニカラグア、コスタリカの土地におけるスペインの支配は終わった。地域はしばらくメキシコ帝国に編入された後、1823年に中央アメリカ連邦共和国を築いた。", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["ヌエバ・ヘルベシアの建設 — メキシコがサクラメント渓谷を入植に開放", "067a1f2a"], "d": ["スイスからの移民ジョン・サッターは、メキシコ当局から得た許可と土地の特許により、サクラメント川とアメリカン川が合流する場所にヌエバ・ヘルベシアを築いた。要塞化された農場は、メキシコのアルタ・カリフォルニアの内陸における最も進んだ前哨となった。1848年に金が発見されたことで、カリフォルニア移住の中心に変わることになる。", "1c5eab3d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["ラエティアとノリクムがローマに編入された:ティベリウスとドルススがアルプスの向こうを奪った", "be6f2a15"], "d": ["紀元前15年にティベリウスとドルススはアルプスの諸部族を破り、ラエティア(およびノリクムの併合)を完成させた。ドナウ川の上流沿岸がローマの国境となった。", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["アミュンタスの死によりガラティアがローマの属州となった", "e4250ad7"], "d": ["アントニウスが任じたガラティア王アミュンタスがキリキアで殺されると(紀元前25年)、アウグストゥスはガラティアをローマの属州に変え、ピシディアとリュカオニアを併合した。首都はアンキュラ(アンカラ)となった。アウグストゥスの『業績録』の碑文(アンキュラ碑文)はここに記された。", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["オクタウィアヌスが「アウグストゥス」の称号を得た:元首政(帝政)時代が始まった", "310297b6"], "d": ["27年1月16日、元老院はオクタウィアヌスにアウグストゥスの称号を与えた。オクタウィアヌスは属州の大部分の指揮権(インペリウム)を長期にわたって得た。この日付がローマ帝国の始まりとされる。", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["ボックス2世が死去し、マウレタニアがオクタウィアヌスの支配下に入った", "414fa36c"], "d": ["ボックス2世が33年に子なくして死ぬと、マウレタニアはオクタウィアヌスが遺言で継承してローマの統治下に入った。しばらく直接のローマ統治下に置かれ、25年にユバ2世に与えられた。", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["アントニウスがアルケラオスをカッパドキア王とした", "1e83e691"], "d": ["アントニウスは東方を再編するなかで、カッパドキアの王位をアルケラオスに与えた。アルケラオスは紀元17年にティベリウスによってローマへ召還されるまで統治した。カッパドキアは紀元17年にローマの属州となった(この事件は年代記では別の項目である)。", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["ピリッピ:オクタウィアヌスとアントニウスがブルトゥスとカッシウスを破った", "4386016f"], "d": ["42年10月に、ピリッピの近郊で二つの別々の戦闘が行われた。カッシウスとブルトゥスは自害し、共和派の勢力は消えた。三頭政治の指導者たちはローマ世界を自分たちの間で分けた。", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["ユリウス・カエサルがコリントスをローマの植民市として再建させた", "283a5daa"], "d": ["カエサルの暗殺の少し前に、コリントスにローマ市民の入植者(大半は解放奴隷)が置かれた。都市はローマの属州アカイアの重要な中心の一つとなった。再建の決定は紀元前44年のもので、入植は紀元前44/43年である。", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["ブレビスタが暗殺された:ダキア王国が分裂した", "9b9edb14"], "d": ["ストラボンは、ブレビスタがカエサルの死より前に内部のクーデタで殺され、王国が5つ、次いで4つの部分に分かれたと記す。ダキアの統合は、デケバルス(紀元87年)まで再建されなかった。", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["カエサルが3月15日(イドゥス)に元老院で殺された", "18649074"], "d": ["終身独裁官に宣言されたカエサルは、44年3月15日に、ポンペイウス劇場での元老院の会議中、元老院議員の一団に刺殺された。その死は、新たな内戦とアウグストゥスの権力の下地を用意した。", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["ムンダ:カエサルがポンペイウスの息子たちを破った", "e1e93362"], "d": ["45年3月17日にムンダで、カエサルはグナエウス・ポンペイウスとセクストゥス・ポンペイウスの軍を破った。ヒスパニアはカエサルの手に残った。内戦の最後の大きな戦いである。", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["タプソス:カエサルがユバ1世を破り、東ヌミディアが新アフリカ属州となった", "77b28c50"], "d": ["カエサルは46年春にタプソスでスキピオとユバ1世の軍を破り、ユバは自害した。ヌミディアの東部はサッルスティウスが統治する新アフリカ属州となり、西部はボックスとシッティウスに与えられた。", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["ゼラ:カエサルがファルナケス2世を破った(「来た、見た、勝った」)", "11bf082a"], "d": ["ミトリダテスの子ファルナケス2世は、内戦に乗じてポントスを取り戻そうとした。カエサルは47年にゼラで彼を破り、ポントスをローマの支配下で再編した。ファルナケスはボスポロスへ逃れ、そこで死んだ。", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["ファルサロス:カエサルがポンペイウスを破った", "e821abe8"], "d": ["カエサルは、ディュッラキウムでの撤退の後、ファルサロスでポンペイウスのより大きな軍を破った。ポンペイウスはエジプトへ逃れて殺された。東方の諸属州はカエサルに開かれた。", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["アレシア:カエサルがウェルキンゲトリクスを包囲して破り、ガリアの抵抗が砕かれた", "d57cab9f"], "d": ["紀元前52年のアルウェルニ族のウェルキンゲトリクスを指導者とするガリアの蜂起は、カエサルのアレシア包囲と包囲線の防衛によって鎮圧された。ウェルキンゲトリクスは降伏した。ガリアは翌年、完全にローマの支配下に入った。", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["カエサルのガリア遠征が始まった:ヘルウェティイ族が敗れた", "1e594bb3"], "d": ["紀元前58年、カエサルは内ガリアと外ガリアの総督として、ヘルウェティイ族の移動をビブラクテ近郊で食い止め、続いてアリオウィストゥスのゲルマン人を破った。遠征は8年続き、ガリアをローマに編入することになる。", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["ミトリダテス6世がパンティカパイオンで死去し、ボスポロスはファルナケスに残された", "0831b871"], "d": ["ポンペイウスから逃れたミトリダテスは、息子ファルナケスの反乱を受けてパンティカパイオンの要塞で自害した(63年)。ファルナケスはボスポロスをポンペイウスに引き渡し、ローマの友好王として認められた。", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["ポンペイウスがビテュニアとポントスの西部を統合し、ビテュニア・ポントス属州を設けた", "b2865ea8"], "d": ["ポンペイウスは東方の再編(65-63年)で、ビテュニアをポントスの西半と統合してビテュニア・ポントス属州をつくった。東のポントスの内陸部は在地の諸侯に与えられた。", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["ポンペイウスがコンマゲネをローマの友好国・同盟国として承認した", "a48ba55c"], "d": ["ポンペイウスは東方の再編で、アンティオコス1世の王国とセレウキア(ゼウグマ)地域の一部を承認し、コンマゲネをローマとパルティアの間の同盟国の緩衝地帯とした。王国は紀元17年に、そして恒久的には紀元72年に、ローマの属州に編入された(これらの事件は年代記では別の項目である)。", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["ポンペイウスがミトリダテスを破り、ポントスがローマに結びつけられた", "8f3f50a6"], "d": ["ポンペイウスは66年にリュコス平原で、夜間にミトリダテスの軍を破った。ミトリダテスはコルキスからボスポロスへ逃れた。ポントスの沿岸都市はローマの支配下に入り、63年にビテュニアと統合された属州が成立した。", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["アンティオコス1世テオスがコンマゲネの王位に就いた", "b1680d3f"], "d": ["コンマゲネ王アンティオコス1世は、ペルシアとマケドニアの血筋を結びつけるネムルート山の墓所神殿を築かせた。王国はローマとパルティアの間の緩衝の位置にあった。", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["キュレネがローマの属州となった(キュレナイカ)", "f9993ffb"], "d": ["プトレマイオス・アピオンが王国をローマに遺贈してから(96年)20年後に、ローマはキュレナイカを属州の制度に組み入れた。67年にクレタと統合された。", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["ニコメデス4世が王国をローマに遺贈した", "e29d9fbc"], "d": ["ニコメデス4世の死(75/74年)により、ビテュニアは遺言でローマ国民に残された。ミトリダテス6世はこれを認めず、第3次ミトリダテス戦争が始まった。ビテュニアはローマの直接の属州に変えられた。", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["ブレビスタがダキア人とゲタイ人の部族を統合した", "3648f92e"], "d": ["ストラボンによれば、ブレビスタはゲタイ人とダキア人を一つの王国にまとめ、ドナウの南でトラキアとイリュリアの境界に至るまで遠征した。王国はドナウ沿いでローマにとって脅威になり始めた。", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["ダルダノスの和約:ミトリダテスがアシアとビテュニアから撤退した", "535818ed"], "d": ["スッラとのダルダノスの和約で、ミトリダテスはすべての征服地(アシア、ビテュニア、カッパドキア、パフラゴニア)を明け渡し、70隻の船と2000-3000タラントンを与えることを受け入れた。しかしローマでスッラの敵が優位に立ったため、第2次ミトリダテス戦争に至った。", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["ミトリダテスがアシア属州に侵攻した:エフェソスの虐殺(8万人のローマ人の殺戮)", "3986833b"], "d": ["第1次ミトリダテス戦争の初め(89/88年)に、ミトリダテスはビテュニアとアシア属州に侵攻した。エフェソスで出した命令によって、ローマ市民が大量に殺された。アテナイもポントス側についた(アリスティオン)。", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["ユリウス法:ローマがイタリアの同盟市に市民権を与えた(同盟市戦争)", "f72ba27d"], "d": ["ローマのイタリア同盟市の蜂起(91-88年)を受けて、ユリウス法(90年)とプラウティウス・パピリウス法(89年)は、忠実な同盟市と降伏した同盟市にローマ市民権を認めた。こうしてポー川に至るイタリア半島は単一の市民社会となった。", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["スッラがアリオバルザネスをカッパドキアの王位に就けた", "8bdd078c"], "d": ["ミトリダテス6世が幼王を通じてカッパドキアを手中にしていたことに対し、ローマはスッラのキリキア総督在任中に、アリオバルザネスを王と宣言させた。カッパドキアは、次の世紀にローマ・ペルシア・ポントスの争いの緩衝となった。", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["プトレマイオス・アピオンがキュレネをローマに遺贈した", "5edef477"], "d": ["キュレネを統治していたプトレマイオス・アピオンは、子なくして死ぬとき、王国をローマ国民に遺した(96年)。元老院は諸都市を自由のままとし、ローマは属州化を74年まで遅らせた。", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["ボックスがユグルタをローマに引き渡した:ヌミディアの西部がマウレタニアに編入された", "7619ad15"], "d": ["ユグルタの義父でマウレタニア王のボックス1世は、スッラにユグルタを引き渡してローマと和解した。その見返りに、ヌミディアの西部が彼に与えられた。ユグルタは104年にローマの獄中で死んだ。", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["パイリサデス5世が王国をミトリダテス6世に譲った:ボスポロスがポントスに結びつけられた", "835bbe74"], "d": ["スキタイの圧力を受けたパイリサデス5世は、ミトリダテスの司令官ディオパントスの助けを得て、王国をミトリダテスに譲った。ボスポロスはこうしてポントスの北の延長となった。黒海の穀物交易は、ミトリダテスの資源として、この時にポントスに移った。", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["ミトリダテスの司令官ディオパントスがクリミアでスキタイを破った", "d8d48c68"], "d": ["ディオパントスは、スキタイ王スキルロスの子パラコスの軍を破り、タウリカでネアポリスの周辺を奪った。ボスポロスとケルソネソスはポントスに結びつけられた。", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["ユグルタがキルタを奪った:ローマがヌミディアの問題に介入した", "660eb34a"], "d": ["ユグルタは紀元前112年にキルタを包囲してアデルバルを殺した。都市で殺されたイタリア人商人たちが、ローマをユグルタに対する宣戦へと促した。戦争は105年まで続いた。", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["ナルボ・マルティウスが建設された:南ガリア(ガリア・トランサルピナ)がローマの属州となった", "20c4bdfa"], "d": ["マッサリアの救援要請(125年)でガリアに入ったローマは、アクアエ・セクスティアエ(122年)とアロブロゲス族に対する勝利でローヌ渓谷を奪った。紀元前118年にナルボ・マルティウスが、最初のローマの植民市としてガリアに建設された。この地域はガリア・トランサルピナ属州となった。", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["ミトリダテス6世エウパトルがポントスの王位に就いた", "c2d5fd41"], "d": ["ミトリダテス5世の死(120/119年)により幼くして即位したミトリダテス6世は、数年の後見の後、ポントスを黒海周辺でローマに対抗する勢力にまで押し上げた。", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["マッサリアの要請でローマがガリアに入った", "eaf7eb0a"], "d": ["サッルウィイ族とリグリア人の圧力を受けたマッサリアがローマに援助を求めると、ローマは125年に南ガリアへ軍を送った。この介入は、ナルボ・マルティウスの建設(118年)とガリア・トランサルピナの獲得につながった。", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["アリストニコスが敗れ、ペルガモンの領土からアシア属州が設けられた", "7ccdc59e"], "d": ["エウメネス3世の名で王位を主張したアリストニコスは、ローマ軍に敗れて捕らえられた(129年)。マニウス・アクィリウスの再編により、旧ペルガモン王国はアシア属州となった。属州の税制(徴税請負人)は、ローマにとって大きな収入源だった。", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["ヌマンティアが陥落した:ケルティベリアがローマに編入された", "ced07244"], "d": ["スキピオ・アエミリアヌスは8か月の包囲の後、飢餓によってヌマンティアを降伏させた(133年)。都市は破壊された。ケルティベリア戦争は終わり、近ヒスパニアの内陸部がローマに編入された。", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["アカイア戦争:アカイア同盟がローマに敗れ、同盟は解体された", "e434cfe0"], "d": ["スパルタとの国境紛争をめぐってローマに反旗を翻したアカイア同盟は、146年にレウコペトラで敗れた。コリントスは破壊され、同盟は事実上解体された。ギリシアの一部はマケドニア属州の監督下に置かれた。", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["第3次ポエニ戦争が終わった:カルタゴが破壊され、アフリカ属州が設けられた", "522515b4"], "d": ["3年の包囲の後、プブリウス・コルネリウス・スキピオ・アエミリアヌスは、146年の春にカルタゴを奪った。都市は焼かれて破壊され、領土はローマに編入された。カルタゴの後背地はアフリカ属州となった。マシニッサのヌミディアは西の隣国として残った。", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["マケドニアがローマの属州となった", "dc6d2352"], "d": ["アンドリスコスの反乱(148年)の鎮圧後、マケドニアの四つの地区は一つのローマ属州として統合された(146年)。属州の南のギリシアの統制も、マケドニア総督の監督に委ねられた。エグナティア街道は、その後の年月にアドリア海からテッサロニキまで築かれた。", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["アンドリスコスの反乱:マケドニア王国が短期間再建され、メテッルスに鎮圧された", "0119ff73"], "d": ["ペルセウスの子を称したアンドリスコスは、150/149年にマケドニアを再統合し、最初のローマ軍を破った。148年にメテッルスがマケドニアを奪還した。この蜂起は、マケドニアがローマの直接統治に結びつけられる原因となった。", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["ローマがカルタゴに宣戦した:第3次ポエニ戦争が始まった", "2e34c235"], "d": ["マシニッサの攻撃に対するカルタゴの自衛が条約違反とみなされ、ローマは149年に宣戦してウティカを自らに結びつけた。カルタゴの都市は3年間、包囲のなかで抵抗した。", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["マシニッサがカルタゴの領土を攻撃した:ヌミディア・カルタゴ戦争", "b47559a5"], "d": ["マシニッサがカルタゴの領土を奪ったこと(151/150年)を受けてカルタゴは開戦し、マシニッサに敗れた。ローマはこれを条約違反とみなして149年に宣戦した。マシニッサは148年に90歳で死んだ。", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["ローマがロドスにリュキアとカリアからの総督の引き揚げを命じた:リュキア同盟(パタラ)がロドスの支配を脱した", "6bbe2b54"], "d": ["第3次マケドニア戦争の後、ローマ元老院はロドスに、リュキアとカリアの総督をある日までに引き揚げるよう命じた。ロドスは、これらの損失を戦争の脅威よりも軽いとみなして受け入れた。リュキア同盟(中心はパタラ)はこうしてロドスの支配を脱し、ローマの保護下のリュキア同盟として続いた。", "8f86b52d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["エピロスがローマに略奪された:70の都市が破壊された", "456fb461"], "d": ["第3次マケドニア戦争の後、ペルセウスに近いままだったエピロスのモロッシスの諸都市は、アエミリウス・パウルスの命令で略奪され、約15万人が奴隷にされた。エピロスは次の世紀に、ローマの支配のもとで貧しいままだった。", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["マケドニアがローマによって四つの自治地区(メリデス)に分けられた", "7a795ba0"], "d": ["元老院の決定(紀元前167年)により、マケドニア王国はアンフィポリス、テッサロニケ(サロニカ)、ペラ、ペラゴニアを中心とする四つの地区に分けられた。地区の間の婚姻と財産取得は禁じられ、鉱山の経営は制限された。", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:3":{"b": ["ローマがリュキアとカリアをロドスから奪った:デロスが自由港と宣言された", "09c8143f"], "d": ["第3次マケドニア戦争でロドスがローマとペルセウスの間で試みた調停は罰せられた。元老院はリュキアとカリアをロドスから取り上げて自由と宣言し、デロスをアテナイに与えて関税のない港に変えた。ロドスの交易収入は大きく落ち込んだ。", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["ピュドナ:アエミリウス・パウルスがペルセウスを破り、アンティゴノス朝が終わった", "a59c5270"], "d": ["168年6月22日、ピュドナでローマの軍団がマケドニアのファランクスを破り、第3次マケドニア戦争を終わらせた。ペルセウスはサモトラケで降伏し、ローマでの凱旋式に連行された。アンティゴノス朝は終わった。", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["アパメイアの和約:エウメネス2世がペルガモンのためにトラキアのケルソネソス、フリュギア、リュディア、ミュシアの大部分を得た", "f25ed9af"], "d": ["マグネシアでの敗北の後、アンティオコス3世は188年にローマと和約を結び、トロス山脈の北を手放した。これらの土地の大部分は、同盟者エウメネス2世のペルガモンに与えられた(トラキアのケルソネソス、大フリュギア、リュディア、ミュシア、イオニアの一部)。", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["アパメイアの和約:ロドスがリュキアとカリアの南を得た", "aa5173c6"], "d": ["マグネシアの後、ローマは同盟者ロドスに、リュキアとカリアのマイアンドロス以南の部分を与えた。ロドスはこれらの土地を167年に失った。", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["マンリウス・ウルソがガラティアの諸部族を破った:ガラティア人の独立がローマの監督下に入った", "30ae73d7"], "d": ["マグネシアの後、グナエウス・マンリウス・ウルソはガラティアの地に侵攻し、オリュンポスとマガバでトリストアギイ族とテクトサゲス族を破った。条約によりガラティア人は隣国を攻撃しないことを受け入れた。ガラティアは大部分が独立したままだったが、ローマとペルガモンの均衡に結びつけられた。", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["アイトリアがローマと和約した:アンブラキアとオイニアダイを失い、ローマの主権を認めた", "f332c6bf"], "d": ["アンティオコス戦争でアンティオコスの側にいたアイトリアは、フルウィウス・ノビリオルのアンブラキア包囲の後、ローマと和約を結んだ。ローマの「威厳」を認め、賠償金を支払い、アンブラキアとオイニアダイなどの都市を手放した。", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["シピュロス山のマグネシア:ローマとペルガモンがアンティオコス3世を破った", "f650ef21"], "d": ["190/189年の冬にマグネシアで、ルキウス・スキピオとエウメネス2世がアンティオコス3世の軍を破った。勝利の後に結ばれたアパメイアの和約(188年)は、アンティオコスにトロスの北を手放させた。", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["スパルタがアカイア同盟に加わった:ピロポイメンがナビスの後にラコニアを同盟に結びつけた", "2629b6e1"], "d": ["スパルタの僭主ナビスの殺害(192年)の後、アカイア同盟の将軍ピロポイメンは、スパルタを力ずくでアカイア同盟に加えた。スパルタは188年に城壁を破壊されて、独立を完全に失った。", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["フラミニヌスがイストミア大祭でギリシア人の自由を宣言した", "3d850bf2"], "d": ["キュノスケファライの後、ローマの司令官ティトゥス・クィンクティウス・フラミニヌスは、紀元前196年のイストミア大祭で、コリントス、カルキス、デメトリアスのマケドニア守備隊が撤退すること、およびギリシアの都市が「自由で、無税で、自らの法に従う」ことを宣言した。ローマはこうしてギリシアに調停者として居座った。", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["キュノスケファライ:ローマがピリッポス5世を破り、マケドニアはギリシアから撤退せざるをえなくなった", "9cb44ca6"], "d": ["197年6月、フラミニヌスのローマ軍団はキュノスケファライでマケドニアのファランクスを破った。196年の和約で、ピリッポスはギリシアのすべての拠点(デメトリアス、カルキス、コリントス)を手放し、艦隊を引き渡し、1000タラントンを支払った。", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["ヒスパニアに二つのローマ属州が設けられた:近ヒスパニアと遠ヒスパニア", "1baa8383"], "d": ["カルタゴから奪ったヒスパニアの領土は、197年に初めて二つの属州に分けられ、それぞれが法務官によって統治された。この日付以後、半島でのケルティベリア人とルシタニア人との戦争は、ローマの属州制度を拡張するために行われた。", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["ザマ後の和約:カルタゴはヒスパニアと地中海の島々、艦隊を失い、1万タラントンの賠償金を負った", "8654422d"], "d": ["ザマ(202年)の後、ローマはカルタゴをアフリカの自らの領土に押し込めた。ヒスパニアと地中海の島々の放棄、艦隊(10隻を除く)の引き渡し、50年間にわたる1万タラントンの支払い、ローマの許可なしに戦争をしないことが条件として受け入れられた。マシニッサのヌミディアは独立した隣国となった。", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["ローマがマシニッサにシュファクスの王国を与えた", "54ba7a64"], "d": ["ザマの和約で、ローマはマシニッサをシュファクスの王国とカルタゴから奪った国境の土地に任じた。マシニッサの「エンポリア」地方とカルタゴ国境に対する要求は、後に戦争の原因となった。", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["ザマ:スキピオとマシニッサがハンニバルを破った", "52e188e6"], "d": ["ハンニバルがアフリカに呼び戻された後のザマの戦いで、スキピオの軍団とマシニッサのヌミディア騎兵がカルタゴ軍を破った。第2次ポエニ戦争は、この戦いでローマの勝利が確定して終わった。", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["シュファクスが敗れて捕らえられ、マシニッサがヌミディアを統一した", "a42a3cb0"], "d": ["スキピオとマシニッサは203年にシュファクスの軍を破ってシュファクスを捕虜にした。マシニッサは、ローマの支援を得てキルタとシュファクスの王国を手に入れた。ヌミディアは、東西の部分の統合によって強力な王国となった。", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["イリパとガデス:ヒスパニアがカルタゴからローマに移った", "31e5a50c"], "d": ["スキピオは206年にイリパでハスドルバル・ギスコとマゴの軍を破り、ヒスパニアにおけるカルタゴの支配を終わらせた。ガデスもまもなくローマに移った。カルタゴはヒスパニアの銀山と兵力の供給源を失った。", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["ファビウス・マクシムスがタレントゥムをハンニバルから取り戻した", "bd605091"], "d": ["212年にハンニバルに降伏していたタレントゥムは、209年に裏切りによってクィントゥス・ファビウス・マクシムスの手に移った。都市の陥落により、ハンニバルは南イタリアで最も価値のある港を失った。", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["カプアがローマの手に落ちた:ハンニバルのカンパニアの拠点が失われた", "cfcb9c9a"], "d": ["カンナエの後ハンニバルについたカプアを2年間包囲したローマは、ハンニバルのローマ進軍の企てにもかかわらず都市を奪い、重く罰した。カプアの自治は廃止された。ハンニバルは南イタリアで守勢に退いた。", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["カンナエ:ハンニバルがローマ軍を包囲して壊滅させ、南イタリアがカルタゴに移り始めた", "94f5110a"], "d": ["216年にアプリアのカンナエで、ハンニバルの包囲陣形が約7万人のローマ軍を壊滅させた。カプア、タレントゥム、南イタリアの多くの都市がカルタゴの側についた。", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["ローマ軍がヒスパニアに上陸した:エンポリオンに最初のローマの拠点", "8cb47853"], "d": ["ハンニバルがイタリアへ進軍した後、グナエウス・コルネリウス・スキピオは紀元前218年にエンポリオンに上陸し、エブロ川の沿いでローマのヒスパニアにおける存在を始めた。半島は第2次ポエニ戦争の第二の戦線となった。", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["ハンニバルがアルプスを越えてイタリアに入った", "a1d3bf5a"], "d": ["ハンニバルはエブロ川、ピレネー山脈、ローヌ川を渡り、秋にアルプスを越えて北イタリアに下った。ティキヌスとトレビアでローマ軍を破った。カルタゴのイタリア戦争の中心は、こうしてローマの内部に移された。", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["ハンニバルがサグントゥムを奪った:第2次ポエニ戦争の導火線に火がついた", "a497a334"], "d": ["ハンニバルは8か月の包囲の後、ローマの同盟者サグントゥムを奪った(紀元前219年)。ローマは使節を送ってハンニバルの引き渡しを求め、拒否されると宣戦が布告された。戦争はイタリア、ヒスパニア、アフリカで17年間続いた。", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["セッラシア:アンティゴノス・ドソンがクレオメネスを破り、スパルタは初めて外国の占領を受けた", "dc64a8db"], "d": ["222年夏、セッラシアでマケドニア・アカイア同盟がクレオメネスのスパルタ軍を破った。クレオメネスはエジプトへ逃れた。ドソンはスパルタに入り、リュクルゴスの制度に戻した。スパルタ人は歴史上初めて、外国軍の占領を経験した。", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["メディオラヌム(ミラノ)がローマの手に落ちた:インスブレス族が敗れ、北イタリアがローマに開かれた", "d3ec639f"], "d": ["テラモン(225年)でガリア人を破ったローマは、紀元前222年のクラスティディウムでのマルケッルスの勝利とメディオラヌムの奪取によって、ポー平原の大部分を支配下に置いた。この地域は内ガリアとして組織された。", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["アカイア同盟がアクロコリントスをアンティゴノス・ドソンに引き渡した:コリントスがマケドニアに戻った", "c8ec9d0c"], "d": ["クレオメネス3世の圧迫を受けたアカイア同盟は、アラトスの手でマケドニアに援助を求め、アクロコリントスとコリントスをアンティゴノス・ドソンに引き渡した。ドソンはヘレネス同盟(ヘレニコス・シュンマキア)を創設した。", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["エブロ条約:カルタゴはエブロ川の北に渡らないことを受け入れた", "a199de0b"], "d": ["ハミルカルが始めたヒスパニア征服を続けていたハスドルバルは、ローマとエブロ条約を結んだ。カルタゴは武装してエブロを渡らないというものである。ハンニバルが219年にサグントゥムを攻撃したことは、この条約の解釈に基づくものとされた。", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["ローマがサルディニアとコルシカをカルタゴから奪った", "4f7295ee"], "d": ["カルタゴのサルディニアの反乱傭兵がローマに援助を求めると、ローマは島を占領した。カルタゴは戦争の脅しを受けて島々を手放し、さらに1200タラントンを支払わざるをえなかった。ローマは二つ目の属州(サルディニア・コルシカ)をつくった。", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["アエガテス諸島:カルタゴの艦隊が壊滅し、シチリアが最初のローマ属州となった", "8bd16e8f"], "d": ["ルタティウス・カトゥルスは241年3月にアエガテスの沖でハンノのカルタゴ艦隊を破った。続くルタティウスの和約で、カルタゴはシチリアから撤退し、3200タラントンの戦争賠償金を支払うことを受け入れた。シチリア(ヒエロンのシュラクサイを除く)はローマの最初の属州となった。", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["アラトスがアクロコリントスを急襲した:コリントスがマケドニアからアカイア同盟に移った", "a88dfda6"], "d": ["シキュオンのアラトスは夜間の急襲でアンティゴノス・ゴナタスのアクロコリントス守備隊を無力化し、コリントスをアカイア同盟に加えた。メガラ、トロイゼン、エピダウロスも同盟に移った。マケドニアはペロポネソスで鍵となる要塞を失った。", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["アラトスがシキュオンをアカイア同盟に加えた", "6f413f9c"], "d": ["若いアラトスはシキュオンの僭主を倒して都市をアカイア同盟に結びつけた。この一歩は同盟をコリントス湾の北と南の沿岸に広げ、アラトスが将軍に選ばれることにつながった。", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["ヒエロン2世がローマと同盟を結んだ:東シチリアがローマの同盟者となった", "5e95a134"], "d": ["ヒエロンは、第1次ポエニ戦争の初めにメッサナの問題でローマに対抗してカルタゴと同盟していたが、263年にローマと和平と同盟を結び、生涯(215年まで)ローマの忠実な同盟者であり続けた。シュラクサイは、ローマのシチリアのなかで属州の外にとどまる同盟国となった。", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["ニコメデス1世がニコメディア(イズミット)を建設した", "a89ed42a"], "d": ["ニコメデスは、アスタコスの破壊の後、湾の東端にニコメディアを建設した。都市は後の数世紀にビテュニアの、そしてディオクレティアヌスの時代にはローマの東の首都の中心となった。", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["第1次ポエニ戦争が始まった:アッピウス・クラウディウスがメッサナへ渡った", "636e1533"], "d": ["マメルティニ人のメッサナが、シュラクサイ王ヒエロンに対抗してカルタゴの後にローマにも援助を求めると、ローマの執政官アッピウス・クラウディウス・カウデクスは264年にシチリアへ渡り、メッサナをカルタゴの守備隊から奪った。こうしてローマは初めてイタリアの外で戦争に入った。", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["ウォルシニイが陥落した:エトルリア最後の独立した大都市がローマに移った", "b6aed092"], "d": ["奴隷の蜂起のためローマの援助を求めたウォルシニイを、ローマは264年に奪い、都市の住民を新しい場所に移した。エトルリアはこれ以後、事実上ローマの支配下に入った。", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["ピュロスがアルゴスで死んだ", "2b4996fa"], "d": ["ペロポネソス遠征中のアルゴスの市街戦で、ピュロスは瓦で傷つけられて死んだ(272年)。エピロスはマケドニアに対する比重を失い、ローマとの関係を再び結んだ。", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["タレントゥムがローマに降伏した:南イタリアがローマに編入された", "6e87c924"], "d": ["ピュロスの出発の後、タレントゥムのエピロス守備隊は撤退し、都市はローマに降伏した(272年)。ブルッティウムとルカニアとともに、南イタリアのギリシア都市はローマの同盟者となった。こうしてローマは、ポー平原に至るイタリア半島の支配者となった。", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["マレウェントゥム(ベネウェントゥム):ピュロスがイタリアから撤退した", "ab67e9f5"], "d": ["ピュロスがシチリア遠征から戻ってローマを再び攻撃したが、マレウェントゥムでマニウス・クリウス・デンタトゥスの前に失敗した。ピュロスは275年にエピロスへ戻った。タレントゥムに小さな守備隊を残した。ローマはイタリアで敵なしとなった。", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["アンティオコス1世が「象の戦い」でガラティア人を破った", "1e88c2d0"], "d": ["アンティオコス1世は、象を用いてガラティア人を破り、ソテル(「救済者」)の称号を得た。ガラティア人は中央アナトリアに定住し、貢納と襲撃の体制に戻った。後の数世紀にペルガモンとビテュニアとの衝突が続いた。", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["アンティゴノス・ゴナタスがマケドニア王となった:アンティゴノス朝が定着した", "4b907dd6"], "d": ["ゴナタスは277年にリュシマケイアでガラティア人を破って名声を得、276年にマケドニアの王位に就いた。王朝は168年までマケドニアを統治した。ギリシアではコリントス、カルキス、ピレウスの要塞を手にしていた。", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["ニコメデス1世がガラティア人をアナトリアに渡らせた", "9e5ab10b"], "d": ["ビテュニア王ニコメデス1世は、弟ジポイテスとセレウコス朝の圧力に対抗するため、ガラティア(ケルト)の諸部族をボスポロスを越えて渡らせ、自らの配下に入れた。ガラティア人は後に中央アナトリアに定住した。テクトサゲス族の一派はアンカラ(アンキュラ)を首都とした(TDV「Ankara」:「紀元前278-189年の間にトラキアから来たガラティア人のテクトサゲス族の一派の首都となった」)。渡来の年代は278/277年である。", "b9f3dcc3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["アイトリア同盟がガラティア人の襲撃に対してデルフォイを守った", "5488966a"], "d": ["ブレンノスのガラティア軍はテルモピュライを越えてデルフォイへ進んだ。アイトリア人とポキス人の抵抗が襲撃を打ち砕いた。アイトリアのデルフォイ隣保同盟における比重は、この勝利で増した。", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["ピュロスがタレントゥムの援助のためイタリアに渡った:ヘラクレアでローマ人を破った", "55f18e85"], "d": ["タレントゥムのローマに対する要請を受けて280年にイタリアに上陸したピュロスは、ヘラクレアでウァレリウス・ラエウィヌスの軍を象と騎兵で破ったが、重い損害を出した。279年にアスクルムで再び勝ち、278-276年にシチリアへ渡った。", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["アカイア同盟が再建された:パトライ、デュメ、トリタイア、ファライ", "81bba071"], "d": ["アンティゴノス朝の支配下にあったアカイアで、四つの都市(デュメ、パトライ、トリタイア、ファライ)が紀元前280年に連邦的な同盟を再建した。その後の数年にアイギオンなどの都市が加わった。同盟はアラトスの指導のもとで、ペロポネソスの大きな勢力となった。", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["ピレタイロスがコルペディオンの後セレウコスに移った:ペルガモンが事実上独立した王朝を築いた", "ac6b3e31"], "d": ["リュシマコスの敗北の後、ピレタイロスは財宝とともにセレウコスに従い、ペルガモンを守って富ませた。セレウコスの死(281年)で事実上独立した。リウィウスは、アッタロス朝がペルガモンを283年から129年まで統治したと伝えている。", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["リュシマコスがピュロスをマケドニアから追い出し、マケドニアの唯一の王となった", "a83e6c64"], "d": ["デメトリオスがセレウコスに降伏した285年の冬の後、リュシマコスはピュロスをマケドニアから追い出して、国を単独で統治した。その国家は、トラキア、マケドニア、西アナトリアを含む広い地域に達した。", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["ピュロスとリュシマコスがマケドニアを分割し、デメトリオス・ポリオルケテスが倒された", "63371ab8"], "d": ["287年の夏、デメトリオスがアジアに渡ったことを受けて、ピュロスとリュシマコスは共同でマケドニアを二つの地域に分け、デメトリオスは崩れた。この分割はわずか2年続いた。", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["サムニウムがローマに編入された:第3次サムニウム戦争が終わった", "bede9942"], "d": ["マニウス・クリウス・デンタトゥスはサムニウム人とサビニ人に決定的な敗北を与えた。サムニウムはローマの同盟者となった。ローマは中部イタリアの支配者となり、南イタリアのギリシア都市(タレントゥム)と対峙することになった。", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["デメトリオス・ポリオルケテスがマケドニア王と宣言された", "a2b1eba3"], "d": ["カッサンドロスの王朝の内部の王位争いに乗じたデメトリオスは、294年の秋に軍によってマケドニア王と宣言された。アンティゴノスの血統のマケドニアにおける最初の主権である。288年に崩れ、ゴナタスが276年にこれを恒久的なものとした。", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["センティヌム:エトルリア人、ウンブリア人、サムニウム人、ガリア人の同盟がローマに敗れた", "b5affc1b"], "d": ["第3次サムニウム戦争中のセンティヌムでのこの戦いは、イタリアにおける反ローマの最後の大同盟を壊滅させた。エトルリアの諸都市は、一つずつローマの同盟に引き込まれた。", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["ピュロスがプトレマイオスの支援でエピロスの王位に戻った", "6288bf69"], "d": ["イプソスの後エジプトで人質となっていたピュロスは、プトレマイオスの援助でエピロスに戻り、王位を取り戻した。エピロスはこれ以後、マケドニアとイタリアの問題に発言権をもった。", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["リュシマコスが財宝をペルガモンに置いた:ピレタイロスが要塞の守護者となった", "e1b4ab77"], "d": ["イプソスの後、リュシマコスは財宝を丘の上のペルガモン要塞に保管させ、守護を宦官ピレタイロスに任せた。ピレタイロスは281年にセレウコスに移り、王朝の礎を築いた。", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["ミトリダテス1世クティステスがポントスの王朝を創始した", "490c338c"], "d": ["アンティゴノス・モノフタルモスに近づいていたミトリダテスは、302年に殺される危険から逃れ、カッパドキアのポントス側の山地のキミアタに身を寄せ、ここにポントス王国の核をつくった。王朝は63年まで続いた。", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["デメトリオス・ポリオルケテスのロドス包囲が失敗に終わった", "dae6f4d6"], "d": ["アンティゴノスに対してプトレマイオスの側にとどまったロドスを、デメトリオスは305年に巨大な攻城兵器で囲んだ。ロドス人は1年抵抗し、304年の夏に和平が成った。都市では、太陽神ヘリオスの巨像(ロドスの巨像)がこの勝利の代金で建てられた。", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["キプロスのサラミスでデメトリオスがプトレマイオスを破った:アンティゴノスとデメトリオスが王の称号を得た", "cc308941"], "d": ["306年の春、デメトリオス・ポリオルケテスはキプロスの沖でプトレマイオスの艦隊を破り、キプロスをアンティゴノスの手に渡した。夏にアンティゴノスとデメトリオスは王の称号を得、他のディアドコイもまもなく同じ称号を名乗った。プトレマイオスは294年にキプロスを取り戻した。", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["リュシマコスがリュシマケイアを建設した:トラキアのケルソネソスの首都", "83b83160"], "d": ["リュシマコスは、ガリポリ半島の首根に築いたリュシマケイアを、トラキア王国の首都とした。ボスポロスとダーダネルスの渡河は彼の手に集まった。都市は紀元前3世紀に地震で荒廃した。", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["ディアドコイの和約:アンティゴノスはアジアの、カッサンドロスはヨーロッパの、プトレマイオスはエジプトの統治を承認された", "811c80f0"], "d": ["311年12月に結ばれた和約で、アンティゴノスはアジアの司令官、カッサンドロスはヨーロッパの将軍、リュシマコスはトラキアの、プトレマイオスはエジプトとその周辺の統治者として承認された。ギリシア都市の自由の原則が通った。セレウコスのバビロンはこの和約の外に置かれた。", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["ティルスがアンティゴノスに移った:フェニキアがプトレマイオスから奪われた", "30f78257"], "d": ["アンティゴノスは315年にシリアに入ってフェニキアを奪い、ティルスを包囲した。都市は314年に陥落した。フェニキアの沿岸とガザに至るまでの海岸が彼の手に入った(ガザは312年のガザの戦いでプトレマイオスに返された)。", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["カッサンドロスがテッサロニキを建設した", "7043bd8a"], "d": ["カッサンドロスは、テルマイコス湾の北の20を超える集落を統合し、妻(ピリッポス2世の娘)テッサロニケの名で都市を建設した。テッサロニキは次の千年のあいだ、マケドニアで最も重要な港となった。", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["カッサンドロスがテーバイを再建させた", "0167e784"], "d": ["アレクサンドロスに破壊されたテーバイは、カッサンドロスの支援と、アテナイとエウボイアからの援助によって、城壁が修復されて再建された。ボイオティア同盟に再び中心が与えられた。", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["ガビエネ:アンティゴノスがエウメネスを破り、イランに至るアジアの支配者となった", "d2990dfd"], "d": ["316/5年の冬にガビエネでエウメネスの軍は崩れ、司令官は自らの兵によってアンティゴノスに引き渡されて処刑された。アンティゴノスは、ペルシア高原からアナトリアに及ぶ広い地域の唯一の支配者となった。セレウコスはエジプトへ逃れた。", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["トリパラディソスの取り決め:アンティゴノス・モノフタルモスがアジアの将軍となった", "69f6fafb"], "d": ["ペルディッカスがエジプトで殺された(320年5月)後、アンティパトロスはトリパラディソスで総督領を配り直した。アンティゴノスはアジアの軍の長に据えられ、セレウコスはバビロンを得た。アンティゴノスはこの地位から、自らの帝国を築こうと試みた。", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["クラノン:ラミア戦争に敗れた。アテナイにマケドニアの守備隊が入り、民主政が停止された", "6931c4f6"], "d": ["322年9月5日、クラノンでギリシア同盟はアンティパトロスとクラテロスに敗れた。アテナイはムニキアにマケドニアの守備隊を受け入れ、市民権の基準を財産のある者に限ることを受け入れた。デモステネスは自害した。古典期のアテナイ民主政は事実上終わった。", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["ラミア戦争:ギリシア都市がアレクサンドロスの死を受けてマケドニアの覇権に反旗を翻した", "c31c7da4"], "d": ["アレクサンドロスの死の報(323年6月)を受けて、アテナイとアイトリア同盟がアンティパトロスに対して蜂起し、アンティパトロスはラミアで包囲された。戦争は、クラノン(322年9月)でのマケドニアの勝利で終わり、コリントス同盟の枠内でのマケドニアの優位が再建された。", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["ヒュダスペス:ポロスが敗れ、パンジャーブがアレクサンドロスに結びつけられた", "abab206b"], "d": ["326年5月、タクシラの王アンビの支援を得て、アレクサンドロスはジェルム川を渡ってポロスを破った。ポロスの王国は、アレクサンドロスの従属国として残された。アレクサンドロスはここから東へ進んだが、ヒュパシスで軍の異議によって止まった。", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["ヒュパシス(ビアス)の河畔で軍が前進を拒んだ:アレクサンドロスの東の境", "17b23afc"], "d": ["モンスーンの雨と疲労のため、マケドニア軍はヒュパシスの向こうへ渡ることを拒んだ。アレクサンドロスは12の祭壇を建てさせて引き返さざるをえなかった。ヒュパシスは、マケドニアの征服のインドにおける東の端となった。", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["バクトリアとソグディアナがアレクサンドロスに服した:アレクサンドロスはロクサネと結婚した", "a050508d"], "d": ["329-327年にオクソスの向こうの地域は激しいゲリラ戦のすえ奪われた。スピタメネスは殺され、ソグディアナの岩とコリエネスの要塞は降伏した。アレクサンドロスはバクトリアの王女ロクサネと結婚し、在地の貴族を統治に結びつけた。", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["西アナトリアの沿岸がアレクサンドロスに移った:エフェソス、ミレトス、ハリカルナッソス", "f67084a4"], "d": ["エフェソスは民主政体のもとで城門を開き、ミレトスは包囲の末(334年夏)に奪われた。ハリカルナッソスの包囲は、秋の都市の陥落で終わり、カリアの総督領はアダに与えられた。アレクサンドロスは、ペルシア艦隊の港を陸から奪うという戦略を、こうして実行した。", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["テーバイがアレクサンドロスの命令で破壊された", "26c4193c"], "d": ["ピリッポスの死で蜂起したテーバイを、アレクサンドロスは秋に奪った。カドメイアにマケドニアの守備隊を置き、都市を破壊させて住民を奴隷にした(ピンダロスの家を除く)。ボイオティア同盟は、この破壊で事実上終わった(316年にカッサンドロスが再建した)。", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["ピリッポス2世がアイガイで殺され、アレクサンドロスが即位した", "417d909e"], "d": ["娘クレオパトラの婚礼の祝宴で、劇場で護衛官パウサニアスに殺されたピリッポスに代わって、息子アレクサンドロスが軍によって王と宣言された。ペルシア遠征とギリシアの統制は、アレクサンドロスに委ねられた。", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["コリントス同盟が結成された:ギリシアの都市がピリッポス2世の覇権のもとに統合された", "c38074dc"], "d": ["カイロネイアの後、ピリッポスはギリシアの都市を、共通の平和(コイネー・エイレーネー)と共同防衛の誓約のもとにコリントスに集めた。ペルシアに対する遠征のための兵と覇者の指揮が決められた。スパルタだけが参加しなかった。", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["カイロネイア:ピリッポスがアテナイ・テーバイの軍を破ってギリシアの統制を握った", "5e5d77e7"], "d": ["338年8月、カイロネイアの平原で、若いアレクサンドロスが指揮した騎兵突撃によってアテナイ・テーバイの軍は崩れた。テーバイにはマケドニアの守備隊が置かれ、アテナイは寛大に赦された。勝利はギリシアの都市の独立を終わらせ、コリントス同盟への道を開いた。", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["ラテン同盟が解散された:ラティウムがローマに結びつけられた", "58849f84"], "d": ["ラテン戦争(340-338年)の終わりに、ローマはラテン同盟を解散した。都市はローマ市民権に加えられるか、個別にローマに結びつけられ、相互の同盟は禁じられた。ローマのイタリアにおける拡張の型の基礎はこれである。", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["ピリッポス2世がスキタイ王アテアスを破った", "e4dee658"], "d": ["王アテアスのイストロス(ドナウ)の岸辺でのピリッポスとの戦いは、アテアスの殺害で終わった。ピリッポスは帰途、トリバロイ人から攻撃を受けた。スキタイの勢力は、西ではドナウの向こうに退いた。", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["ピリッポスがオドリュサイ王朝とともにトラキアを服従させた", "b543427a"], "d": ["ピリッポスは紀元前342-341年の遠征でトラキアの内陸へ進み、オドリュサイ王ケルソブレプテスに貢納を課し、ピリッポポリス(プロヴディフ)などの都市を建てた。トラキアはマケドニアの東の延長となった。", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["オリュントスの破壊:カルキディケ同盟がマケドニアに移った", "89d77301"], "d": ["オリュントスがアテナイに援助を求めたにもかかわらず、ピリッポスは都市を裏切りによって奪って破壊した。カルキディケ半島はマケドニアに編入された。デモステネスの『オリュントス演説』は、この要請に基づく。", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["同盟市戦争が終わった:ビュザンティオン、キオス、ロドス、コスが第2次アテナイ海上同盟から離れた", "856a9763"], "d": ["紀元前357年に始まった反乱は、アテナイの司令官たちがキオスで敗れ、ペルシアの支援がアテナイに敵対したため、アテナイが和平を受け入れて終わった。四つの重要な加盟国が独立を得た。同盟は弱体化し、マケドニアの前に無防備になった。", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["ピリッポスがアンフィポリスをアテナイから奪った", "2c793bc6"], "d": ["アテナイのストリュモン河口のアンフィポリスを包囲して奪ったピリッポスは、都市の金銀の鉱山と木材資源に手が届くことを知り、トラキアの沿岸へ進出した。この征服がアテナイとマケドニアの対立の始まりとなった。", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["ピリッポス2世がマケドニア王となった", "d557268d"], "d": ["ペルディッカス3世がイリュリア人との戦いで死んだ(紀元前360/359年)ことを受けて、ピリッポスは初め摂政、次いで王となった。イリュリア、パイオニア、トラキアの脅威をかわし、軍制改革(サリッサのファランクス)を行った。マケドニアの台頭は、この王国から始まる。", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["マンティネイア:エパメイノンダスが死に、ボイオティアの覇権が終わった", "94be8d5c"], "d": ["テーバイ軍は戦いに勝ったが、エパメイノンダスは傷ついて死んだ。クセノフォンは「ギリシアでは以前よりも不確実と混乱が増した」と結んでいる。テーバイの短い覇権は同年に終わり、アテナイ・スパルタ・テーバイの均衡は保たれた。", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["アルカディア同盟が結成された:ペロポネソス同盟のこの部分が解体した", "42fdc676"], "d": ["レウクトラの後、アルカディアの都市はテーバイの支援で連邦的な同盟を結成し、新しい首都メガロポリスを築いた。こうしてスパルタのペロポネソス同盟は事実上解体した。スパルタはラコニアだけに退いた。", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["メッセニアがスパルタから離れ、メッセネが建設された", "e4ef9302"], "d": ["エパメイノンダスのレウクトラ後のペロポネソス遠征(370/69年の冬)で、メッセニアのヘロットは解放され、イトメ山の麓に堅固な城壁をもつメッセネの都市が建設された。スパルタは、経済的基盤をなしていたメッセニアの土地を、数世紀ぶりに初めて失った。", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["レウクトラ:テーバイ軍がスパルタ人を破り、スパルタは陸の優位を失った", "e7829597"], "d": ["エパメイノンダスの深い右翼集中の陣形は、王クレオンブロトスのスパルタ軍をレウクトラで壊滅させた。約400人のスパルタ市民の死により、スパルタは人口の損失を補えなくなった。テーバイの指導による覇権の時代が始まった。", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["第2次アテナイ海上同盟が結成された(アリストテレスの決議)", "0e5dcaf2"], "d": ["アテナイは、スパルタに対抗して、自治と貢納を取らない原則でエーゲ海の都市に同盟への参加を呼びかけた。決議はアリストテレスの提案で出され、加盟都市のリストは石に刻まれた。同盟の結成は、アテナイを再び海上勢力にした。", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["ペロピダスがテーバイを解放し、スパルタの守備隊がカドメイアから追い出された", "eb15a9d7"], "d": ["スパルタが紀元前382年に奪って守備隊を置いていたテーバイのカドメイアは、亡命者の夜襲で取り戻された。テーバイは再びボイオティア同盟の中心となった。この事件は、スパルタの覇権の解体の始まりである。", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["アッリア:ガリア人がローマ軍を破って都市を略奪した", "db864bc9"], "d": ["ティベリス川の支流アッリア川の岸で、セノネス族のガリア人がローマ軍を破った。ローマはカピトリウムを除いて占領され、略奪された。リウィウスは、「アッリアの日」(7月18日)がローマ人にとって不吉とされたと書いている。", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["コリントスがアルゴスと合同した(アルゴス・コリントス・イソポリテイア)", "135a3d3a"], "d": ["コリントス戦争(紀元前395-387年)の間に、コリントスはアルゴスと共通の市民権の連合を結んだ。アルゴスの守備隊はコリントスに残った。スパルタは大王の和約(386年)で、この合同を解消させた。", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["ウェイイがローマの手に落ちた:エトルリアの南の最初の大都市が失われた", "0d1c4fe4"], "d": ["10年の包囲の後、カミッルスがウェイイを奪った(伝承では紀元前396年)。住民は奴隷にされ、土地はローマに編入され、ローマの公有地(アゲル・ロマヌス)はほぼ2倍になった。エトルリアの都市のティベリス以南の力は砕かれた。", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["アテナイがスパルタに降伏した:アテナイの海上帝国とデロス同盟が終わった", "43f2ddf9"], "d": ["アイゴスポタモイで艦隊を失ったアテナイは、飢えによって降伏した。長城壁は破壊され、海上帝国は解体し、都市ではスパルタ人が設けさせた三十人僭主の統治が始まった。同盟のかつての加盟国である島々とトラキアの沿岸では、リュサンドロスが設けた十人官制の統治とスパルタの守備隊が置かれた。", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["ディオニュシオス1世がシュラクサイの僭主となった", "1ad10305"], "d": ["カルタゴがアクラガスとゲラを奪った年に、ディオニュシオスは405年にシュラクサイの将軍となり、ついで僭主となった。カルタゴと和平を結び(405年)、シチリアのギリシア都市を自らに結びつけた。38年続くディオニュシオスの支配は、シチリアを地中海の大きな勢力の一つにした。", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["アイゴスポタモイ:アテナイの艦隊が壊滅し、デロス同盟は崩壊の瀬戸際に至った", "ce62187c"], "d": ["405年9月、リュサンドロスはアイゴスポタモイに停泊していたアテナイ艦隊を急襲して奪った。艦隊のほぼすべてと数千人の捕虜が失われた。ヘレスポントスの道は閉ざされ、アテナイの穀物の補給は断たれた。数か月後、アテナイは降伏した。", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["ロドスの都市が建設された:リンドス、イアリュソス、カメイロスが合同した", "2de55901"], "d": ["紀元前408年に、ロドス島の三つの都市は共同国家をつくり、新しいロドス市に合同した。ヒッポダモスの計画で建設された都市は、ヘレニズム世界で最も重要な海軍基地と交易の中心の一つとなった。", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["ハンニバル・マゴがセリヌスとヒメラを破壊した:カルタゴが西シチリアに定着した", "358f4417"], "d": ["セゲスタの救援要請でシチリアに上陸したハンニバル・マゴは、紀元前409年にセリヌスとヒメラを奪った。この地域はカルタゴのエピクラテイア(支配地)となった。カルタゴとシュラクサイの対立は2世紀続いた。", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["シチリア遠征が破滅に終わった:アテナイ軍がシュラクサイの前で全滅した", "b363df0d"], "d": ["アテナイが紀元前415年に始めたシチリア遠征は、シュラクサイを包囲できなかった後、ニキアスとデモステネスの撤退のさなかにアシナロス川の岸での降伏(紀元前413年秋)で終わった。アテナイは軍と艦隊の大部分を失った。", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["シタルケスがアテナイと同盟した:オドリュサイ王国がペロポネソス戦争に加わった", "4562f13d"], "d": ["アテナイはシタルケスの息子をアテナイ市民とし、彼と同盟を結んだ。シタルケスは429年にマケドニアを攻撃した。オドリュサイの勢力はこの時期に頂点に達した。", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["ペロポネソス戦争が始まった:ペロポネソス同盟がアテナイに対して動員された", "2adee4a1"], "d": ["テーバイのプラタイアへの夜襲(431年春)で平和は事実上破られた。初夏には王アルキダモスが指揮するペロポネソス同盟軍がアッティカに侵入した。戦争は、アテナイの海上帝国とスパルタの陸上同盟のあいだで27年間続いた。", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["シュボタ:コリントスとケルキュラの戦いがアテナイを介入に引き込んだ", "dc07b0ac"], "d": ["コリントスが植民市ケルキュラとエピダムノスをめぐって入った海戦で、アテナイはケルキュラを支援した。コリントスのアテナイに対する怒りは、ペロポネソス戦争の直接の原因の一つとなった。", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["スパルトコスがボスポロスでアルコンとなった:スパルトコス朝", "ddc76f79"], "d": ["パンティカパイオンのアルカイアナクティダイ王朝に代わって、トラキア出身のスパルトコスが立った(438/7年)。スパルトコス朝はボスポロス王国を築き、アテナイへの穀物輸出を管理した。王朝は紀元前109年まで続いた。", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["三十年和約:アテナイは陸上帝国(ボイオティア、メガラ、アカイア)を失った", "4f33ff13"], "d": ["コロネイアでボイオティア人がアテナイ軍を破り(447年)、続いてエウボイアとメガラの反乱、スパルタのアッティカ侵入の後、アテナイは三十年和約に署名した。アテナイはメガラ、ニサイア、ペガイ、およびペロポネソスのトロイゼンとアカイアを手放し、海上帝国だけを保った。", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["テレスがオドリュサイ王国を建てた:トラキア最初の大国家", "83caf189"], "d": ["トゥキュディデスは、テレスがトラキアで最初の大王国を築いたと記す。息子のシタルケスは王国をドナウからエーゲ海にまで至らせた。オドリュサイ王国は、アテナイ、マケドニア、ペルシアの間で均衡政策をとった。", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["同盟の財宝がデロスからアテナイに移された", "173f2e5b"], "d": ["エジプト遠征での敗北とペルシア艦隊への恐れを理由に、共同の財宝はデロスからアテナイに運ばれた。アテナイの女神に捧げられた「60分の1」の分担金の記録は、この年から始まる。この措置は、同盟が実際にはアテナイの帝国に変わったことの印と解釈される。", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["タソスの反乱が鎮圧された:デロス同盟は、加盟国が離脱できない帝国に変わった", "d24bd124"], "d": ["タソスは鉱山をめぐってアテナイと衝突し、同盟からの離脱を試みた。2年の包囲の後(紀元前463年)、城壁を破壊され、艦隊を引き渡し、トラキア沿岸の鉱山地域を失った。この事件は、同盟の加盟を放棄できないことを示した最初の先例である。", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["クマエ(キュメ)の海戦:シュラクサイがエトルリアの艦隊を破り、エトルリアの海上勢力が砕かれた", "2e81670b"], "d": ["クマエの救援要請を受けて、シュラクサイの僭主ヒエロン1世はクマエの沖でエトルリアの艦隊を破った。ヒエロンは勝利を兜の奉納でデルフォイに祝った(リウィウスが記すエトルリアの兜)。エトルリアのカンパニアにおける支配は揺らいだ。", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["デロス同盟が結成された:アテナイを指導者とするエーゲ海の同盟", "f0de153a"], "d": ["パウサニアスの統治のやり方の後、イオニアの都市はアテナイに指導を求めた。アリステイデスが定めた貢納(460タラントン)で、デロスに共同の財宝が設けられた。同盟はアテナイに、エーゲ海上の恒常的な艦隊と課税の基盤を与えた。", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["サラミス(480年9月29日)とプラタイア:ペルシアの侵攻が撃退された", "479b17e6"], "d": ["クセルクセスがアテナイを奪って焼いた後、テミストクレスの策略でペルシア艦隊はサラミスの海峡で崩れた(480年9月29日)。翌年、プラタイアでパウサニアスが指揮するギリシアの陸軍がマルドニオスを破り、侵攻は終わった。こうしてエーゲ海のギリシアはペルシアの支配から解放された。", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["ヒメラ:シチリアのギリシア人がカルタゴ軍を破った", "ece09580"], "d": ["ゲロンとテロンの同盟は、ヒメラの前でハミルカルのカルタゴ軍を破った。カルタゴは半世紀のあいだ、シチリアへ再び大遠征を行えなかった。ヘロドトスとディオドロスによれば、同じ日にサラミスで勝利が得られた(伝承)。", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["マラトン:アテナイがペルシアの襲来を止めた", "0967ce7c"], "d": ["ミルティアデスの指揮のもと、アテナイとプラタイアの重装歩兵はマラトンの平原でペルシア軍を破り、アッティカへの上陸を阻んだ。この勝利は、アテナイの民主政の自信と、続いてデロス同盟へ至る海洋政策を育んだ。", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["マルドニオスがマケドニアをペルシアに従属させた", "7bde569c"], "d": ["ダレイオスの婿マルドニオスはトラキアを通ってマケドニアをペルシアの支配下に入れ、マケドニア王はペルシアに土地と水を差し出した。マケドニアはこの従属を、プラタイアの後(479年)に脱した。", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["カッシウス条約:ローマがラテン同盟と同盟を結んだ", "56db407d"], "d": ["スプリウス・カッシウスの名を冠した条約によって、ローマとラテン同盟は、相互防衛、戦利品の分配、共同軍の原則で同盟を結んだ。この条約は、ラテン戦争(340-338年)までのローマとラティウムの関係の枠組みである。", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["コリントスの撤退でペロポネソス同盟のアテナイ遠征が瓦解した", "b44adf6b"], "d": ["スパルタはクレイステネスの民主政アテナイに対して、ペロポネソス同盟軍をアッティカに進めた。エレウシスでコリントス軍が撤退し、二人のスパルタ王が不和になったことで遠征は崩れた。この事件は、同盟の会議で同盟国の投票権が働き始めた最初の例とされる。", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["クレイステネスの改革:アテナイ民主政の制度的基礎が築かれた", "b2421c86"], "d": ["ヒッピアスの失脚の後、クレイステネスは市民を居住単位であるデモスと10の新しい部族によって組織した。五百人評議会はこの制度の中心となった。イソノミア/デモクラティアの概念が生まれた制度である。", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["最後の王タルクィニウス・スペルブスが追放され、王政が終わり、共和政が始まった", "5a4a9061"], "d": ["リウィウスによれば、タルクィニウス・スペルブスとその一族は紀元前509年に都市から追放され、最初の執政官(ブルトゥス、コッラティヌス)が選ばれた。ポリュビオスは、ローマ・カルタゴの最初の条約を最初の執政官の年に結びつける。この年代は、近代の歴史学では「伝承」とされるものの、紀元前6世紀末に位置づけられる。", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["ローマとカルタゴの最初の条約(ポリュビオス3.22)", "cdef940f"], "d": ["ポリュビオスは、最初の執政官の年にローマとカルタゴの間で結ばれた、ラティウムの沿岸をローマに、カルタゴを西シチリアとリビュアに分ける条約を、本文とともに伝える。ローマはラティウムの主人として語られる。", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["アラリアの海戦:エトルリア人とカルタゴ人がポカイア人をコルシカから追い出した", "25efbea8"], "d": ["アラリアで、ポカイアのギリシア人は紙の上では勝利したが、艦隊の大部分を失った。コルシカを手放して南イタリアのエレアに退いた。島にはエトルリア(カエレ)の支配が築かれた。", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["スパルタ・テゲア同盟:ペロポネソス同盟の核が形成された", "57098e47"], "d": ["スパルタはアルカディアのテゲアを破り、土地を荒らさないことの代償として永久の同盟(シュンマキア)を受け入れさせた。同じ型がペロポネソスの都市に広がり、スパルタを指導者とするペロポネソス同盟が生まれた。同盟は内部で、スパルタと同盟国の会議(スパルタが指揮する)の形で機能した。", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["ポカイア人がマッサリア(マルセイユ)を建設した", "5d46bdf2"], "d": ["ポカイアの入植者は紀元前600年ごろにローヌ川の河口にマッサリアを建設した。都市は、西地中海におけるギリシアの交易と、ケルト世界との接触の中心となった。", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["テラのバットスがキュレネを建設した", "67fd477f"], "d": ["テラから来た入植者は、デルフォイの神託にしたがってバットスの指導でキュレネを建設した。バッティアダイ王朝は440年まで統治した。リウィウスは建設年を「前630年ごろ」とする。", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["スパルタが第1次メッセニア戦争に勝った:メッセニアがスパルタに編入された", "74ad461c"], "d": ["パウサニアスが伝える伝承では、第1次メッセニア戦争は20年続き、イトメの陥落でメッセニアの平野はスパルタに移った。住民はヘロットの身分に落とされた。この征服は、スパルタの農業力と軍事社会を決定した根本的な事件とされた。", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["シュラクサイがコリントスのアルキアスによって建設された", "10217104"], "d": ["トゥキュディデスによれば、ナクソスの1年後にコリントスのアルキアスがシュラクサイを建設した。都市はシチリア最大のギリシア都市となった。", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["カルタゴの伝承上の建設(ティマイオス:紀元前814/813年)", "908099b5"], "d": ["ティマイオスによれば、カルタゴは紀元前814/813年にティルスの入植者によって建設された。ユスティヌスは825年とする。考古学的な層は紀元前8世紀末を指している。", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["ミュケナイの宮殿中心が破壊された:ペロポネソスで宮殿体制が崩壊した", "d2c79152"], "d": ["後期ヘラデ IIIB期末/IIIC期初めに、ピュロス、ティリュンス、ミュケナイの宮殿中心は破壊または放棄の層を示す。線文字Bの文字に基づく宮殿経済は終わる。破壊の原因(地震、内紛、海の民、干ばつ)については議論がある。破壊の層は単一の年ではなく、数十年にまたがる。", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["クレタでミノアの宮殿が破壊された:クノッソスでミュケナイの支配が始まった", "1a7f7f2b"], "d": ["後期ミノア IB期末(紀元前15世紀半ば)に、クレタの宮殿中心と邸宅は破壊される。クノッソスでは、後の段階の線文字Bの粘土板が、ギリシア語で書かれた宮殿の統治、すなわちミュケナイの支配を示している。こうしてクレタでのミノアの覇権は終わる。", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["トイトブルクの森:ウァルスの3個軍団が全滅し、ローマはエルベの線を放棄した", "1684ae43"], "d": ["紀元9年に、アルミニウスを指導者とするゲルマンの連合は、プブリウス・クィンクティリウス・ウァルスの第17、第18、第19軍団をトイトブルクの森で全滅させた。アウグストゥスはラインの向こうの征服を断念し、ラインの国境が恒久化した。", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["アウグストゥスが死去し、ティベリウスが皇帝となった", "0221344d"], "d": ["アウグストゥスは14年8月19日にノラで死んだ。ティベリウスが後を継いだ。元首政における継承の原則(一族からの養子)は、こうして定着した。", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["王プトレマイオスがカリグラに殺された:マウレタニアの独立が終わった", "11337627"], "d": ["ユバ2世の子プトレマイオスは、紀元40年にルグドゥヌムでカリグラの命により殺された。続いてマウレタニアでアエデモンの反乱が起こり、クラウディウスは44年に国をティンギタナとカエサリエンシスの二つの属州に分けた。", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["クラウディウスがブリタンニアに侵攻した", "f42ba7f7"], "d": ["紀元43年に、アウルス・プラウティウスの指揮する4個軍団がケントの沿岸に上陸した。カムロドゥヌム(コルチェスター)は奪われ、クラウディウスは短期間、都市に滞在した。ブリタンニアの南部は新しいローマの属州となった。", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["ローマがトラキアを属州とした:オドリュサイ王朝が終わった", "af2ba1b2"], "d": ["トラキア王ロイメタルケス3世が妻に殺され、続いて混乱が起こると、クラウディウスは46年にトラキアをローマの属州に変えた。バルカンにおいて、ローマの東の属州体制を完成させた最後の措置の一つである。", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["トラヤヌスがダキアを征服した:サルミゼゲトゥサが陥落し、デケバルスが死に、ダキア属州が設けられた", "a9277172"], "d": ["第2次ダキア戦争(105-106年)でトラヤヌスはサルミゼゲトゥサを奪い、デケバルスは捕らえられるのを避けて自害した。ダキアはローマの属州となり、金鉱はローマ経済に結びつけられた。戦争の前の段階(101-105年)は、年代記では別の項目である。", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["ハドリアヌスがブリタンニアで北の国境に長城の建設を始めた", "f4a886ec"], "d": ["ハドリアヌスは紀元122年にブリタンニアを訪れた後、タイン・ソルウェイの線に国境の長城を築かせた。長城はローマの防衛的な国境政策を象徴する。前進はアントニヌスの長城(142年)で試みられたが、恒久的にはならなかった。", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["セプティミウス・セウェルスがメソポタミアを属州とした:クテシフォンが略奪された", "df466924"], "d": ["セウェルスはパルティア戦争(195-198年)でニシビスを奪ってクテシフォンを略奪し、上メソポタミアをローマの属州として整えた。この属州は、ローマの最も東への進出を3世紀に持ち越した。", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["アントニヌス勅令:帝国のすべての自由な住民にローマ市民権が与えられた", "dd4e4024"], "d": ["カラカラは紀元212年に、属州の自由な住民をローマ市民とした。帝国で市民と外国人の区別はなくなった。この措置は課税の基盤も広げた。", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["ポストゥムスがガリアで分離したガリア帝国を建てた", "4dcda41d"], "d": ["ウァレリアヌスがパルティアで捕虜になったこと(260年)を受けて、ポストゥムスはライン軍とともにガリアで帝国を宣言した。ガリア、ブリタンニア、ヒスパニアの大部分は、274年までローマから離れた。ガッリエヌスは分離を除けなかった。", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["アウレリアヌスがダキアを放棄した:ドナウの北が手放された", "db2ca714"], "d": ["ゴート族の圧力のため、アウレリアヌスはダキア属州を空にして、軍団と民間人をドナウの南(ダキア・リペンシス)に退かせた。ローマは165年ぶりに、ドナウの北の最初の大きな領土を手放した。", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["アウレリアヌスがパルミラ帝国を破った:ゼノビアの東方の領土がローマに戻った", "0a358790"], "d": ["アウレリアヌスは272年にアンティオキアとエメサでゼノビアの軍を破ってパルミラを包囲し、ゼノビアは捕らえられた。シリア、エジプト、アナトリアの南が再びローマに結びつけられた。", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["アウレリアヌスがガリア帝国を破った:ローマが再統一された", "c1a6a642"], "d": ["アウレリアヌスは274年にカタラウヌムでテトリクスを破った。ガリア、ブリタンニア、ヒスパニアはローマに戻った。帝国は14年の分裂の後に再統一され、アウレリアヌスは「レスティトゥトル・オルビス」(「世界を再建する者」)の称号を得た。", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["ユリアヌスがサリー・フランク族をトクサンドリアにローマのフォエデラティとして定住させた", "0fb618fe"], "d": ["副帝ユリアヌスは358年にサリー・フランク族を破り、ローマの領土内のトクサンドリア(現在のオランダとベルギーの国境)に定住することを許した。これは、フランク王国が生まれる地域がローマの保護下に定住することの始まりである。", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["フン族がドン川を渡ってアラン人と東ゴート族を攻撃した:民族大移動の始まり", "659eb875"], "d": ["アンミアヌスによれば、フン族は375年にドン川を渡ってアラン人を破り、続いて東ゴート王エルマナリクの王国を滅ぼした。西ゴート(テルヴィンギ)の人々はこれを受けてドナウに迫った。ヨーロッパにおけるフン族の覇権の時代は、こうして始まった。", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["テルヴィンギ族のゴート人がドナウを渡ってローマの領土に定住した", "3e9de0e6"], "d": ["フン族の圧力を受けたフリティゲルンのテルヴィンギ族のゴート人は、376年にウァレンスから、ドナウを渡ってローマの領土に定住する許可を得た。補給と統治の問題は反乱に変わった。結果は378年のアドリアノープルの敗北となった。", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["ヴァンダル族、アラン人、スエビ族がラインを渡ってガリアに入った", "2b3354ba"], "d": ["伝統的な406年12月31日の日付に(凍ったライン川の上を)、ヴァンダル族、アラン人、スエビ族がローマのガリアに入った。ラインの防衛は崩れた。続くヒスパニアへの移動(409年)は、西ローマの基幹の属州を切り離した。", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["ヴァンダル族、アラン人、スエビ族がヒスパニアに移った:ヒスパニアが分割された", "b7036608"], "d": ["409年秋にガリアからピレネーを越えたヴァンダル、アラン、スエビの集団は、411年に半島を互いに分けた。ハスディング族とスエビ族はガッラエキアを、シリング族はバエティカを、アラン人はルシタニアとカルタギネンシスを得た。西ゴート族(416-418年)はシリング族とアラン人を打ち破り、ヴァンダル族のアフリカへの移動を準備した。", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["ローマが西ゴート族をアクィタニア・セクンダに定住させた:トゥールーズを中心とする西ゴート王国", "38a7699e"], "d": ["コンスタンティウスの指揮のもと、ローマは、ワリアの西ゴート族をヒスパニアでヴァンダル・アラン人に対して用いた後、418年にガロンヌ渓谷のアクィタニア・セクンダにフォエデラティとして定住させた。トゥールーズを中心とする西ゴート王国は、ローマの領土における最初のゲルマン王国とされる。", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["マルグス条約:フン族がローマから毎年700リブラの金を得た", "833d8854"], "d": ["フン王ルアの死(433/4年)の後、アッティラとブレダはマルグスで東ローマと条約を結んだ。毎年の貢納は350リブラから700リブラの金に引き上げられ、フンの亡命者は返還された。フン族はドナウの国境での交易の権利を得た。", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["ヒッポ条約:ローマがヴァンダル族をヌミディアとマウレタニアの一部のフォエデラティとして認めた", "f7dba59f"], "d": ["ヴァンダル王ガイセリックは、429年にアフリカへ渡った後、435年にローマとヒッポ条約を結んだ。ヴァンダル族はヌミディアとマウレタニアの一部をフォエデラティとして保持した。条約は439年のカルタゴの奪取で破られた。", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["アッティラがドナウの要塞を奪った:ウィミナキウムとシンギドゥヌム(ベオグラード)がフン族に移った", "0abb2c54"], "d": ["東ローマ軍がシチリアとヴァンダル遠征に出ていたことを受けて、アッティラは441年にドナウを渡った。マルグス、ウィミナキウム、シンギドゥヌムが奪われた。シルミウムもこの遠征で陥落し、フン族はバルカンの内陸に達した。", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["ローマとヴァンダル族が新たな条約を結んだ:アフリカ・プロコンスラリス、ビュザケナ、ヌミディアの一部がヴァンダル族に残された", "e5700ddc"], "d": ["カルタゴを奪った(439年)ガイセリックは、442年にウァレンティニアヌス3世と結んだ条約によって、アフリカ・プロコンスラリス、ビュザケナ、アバリターナ、ヌミディアの一部を法的にヴァンダルの領土とした。ローマはマウレタニアとヌミディアの西だけを保った。", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["アナトリウスの和約:ドナウの南の広い帯状の土地がフン族に委ねられた", "ee8ad838"], "d": ["ウトゥスでの東ローマの敗北の後、アナトリウスは447年にアッティラと和約を結んだ。ローマはドナウの南の、シンギドゥヌムからノウァエまで5日行程の幅の帯状の土地をフン族に委ね、毎年の貢納は2100リブラの金に引き上げられた。", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["カタラウヌム(シャロン)の戦い:アエティウスとテオドリック1世がアッティラをガリアから追い出した", "80f10e32"], "d": ["451年、アッティラはガリアに入ってオルレアンを包囲した。アエティウスと西ゴート王テオドリック1世の連合は、彼をカタラウヌムの平原で押し返した(テオドリックは戦死した)。フン族の西ヨーロッパへの進出は、これで止まった。", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["アッティラがイタリアに入った:アクイレイアが破壊された", "1349c67a"], "d": ["452年、アッティラはアルプスの向こうから北イタリアに入り、アクイレイアを更地にしてポー平原を略奪した。病気と東ローマの反撃によって退いた。アクイレイアの逃れた住民は、潟にヴェネツィアの核をつくった。", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["アッティラが死に、フン族の国家が解体した", "47009384"], "d": ["アッティラは453年に婚礼の夜に死んだ。息子たちの間の分割とゲルマンの臣民の蜂起は、1年後のネダオ(454年)でフン族の優位を終わらせた。フン族は東ヨーロッパへ退いた。", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["エウリックの西ゴート王国がローマから事実上分離した:オーヴェルニュが西ゴート族に委ねられた", "4bbe7b0c"], "d": ["エウリックは466年からヒスパニアとガリアで征服を行って王国を広げた。475年にユリウス・ネポスはオーヴェルニュを手放して、その独立した主権を事実上認めた。西ゴート王国は、ロワールから地中海まで西ローマの領土を支配した。", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["ユリウス・ネポスがダルマティアで殺された:西ローマの最後の正統な皇帝", "3b965f33"], "d": ["ロムルスの廃位の後ダルマティアに退いたネポスは、480年に殺された。その死後、西ローマの帝位を要求する者はいなくなり、オドアケルはイタリアでの事実上の権力をゼノンの名のもとに続けた。", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["テオドリックが東ゴート族をイタリアに入れた:イゾンツォとヴェローナでオドアケルが敗れた", "6a998bf8"], "d": ["東ローマ皇帝ゼノンの承認を得て、テオドリックは489年にイタリアに入り、イゾンツォとヴェローナでオドアケルを破った。オドアケルはラヴェンナに籠もった。3年の包囲は、493年のラヴェンナの降伏で終わった。", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["テオドリックがラヴェンナでオドアケルを殺させた:イタリアが東ゴート王国のものとなった", "5a2db0ed"], "d": ["オドアケルのイタリア王国の終わりである。イタリア全土(ジェノヴァ、ブリンディジ、アリキアなどの都市を含む)が東ゴート王国に移った。3年のラヴェンナ包囲の後、493年3月にオドアケルとテオドリックは共同統治で合意し、その後、テオドリックは宴席でオドアケルを殺した。イタリアは東ローマの承認を得て東ゴート王国となり、首都はラヴェンナである。", "1024674c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["サモスの和約:クシュの使節がアウグストゥスから和平を得た;ローマはクシュに課した貢納を廃し、国境は下ヌビア(ヒエラ・シカミノス)に引かれた", "c3c4c20d"], "d": ["カンダケの使節は、ペトロニウスの指示でアウグストゥスのいたサモスに赴いた;アウグストゥスは彼らの望みをすべて受け入れ、ペトロニウスがクシュに課した貢納も廃した。和平の結果、ローマ・クシュ国境はフィラエの南のヒエラ・シカミノス(マハラカ)の線に定まり、約300年間深刻な衝突はなかった。", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["ペトロニウスがクシュに遠征し、Pselkis、Premnis、ナパタを攻略した;イブリムに守備隊を置いた", "4884ed51"], "d": ["長官ペトロニウスは1万ほどの歩兵と800の騎兵で3万のクシュ兵を破り、Pselkisを攻略し、Premnis(Qasr İbrim)城塞を最初の攻撃で奪い、カンダケの宮殿のあるナパタを壊滅させた。さらに進むことは困難と考えて戻る際、Premnisに2年分の食糧とともに400人の守備隊を残した。カンダケがPremnisを奪い返そうとすると、ペトロニウスが駆けつけて城塞を守った。", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["カンダケに率いられたクシュがエレファンティネ、シエネ、フィラエを攻略した;アウグストゥスの像を倒した", "aa665fad"], "d": ["アエリウス・ガルスのアラビア遠征のためエジプトのローマ軍の一部が引き抜かれると、クシュ人はテーバイスに入った;シエネの3コホルスの守備隊を破ってシエネ、エレファンティネ、フィラエを奪い、住民を捕虜とし、カエサルの像を倒した。ストラボンは、当時クシュを統治していた女王が「カンダケ」の称号を持つ片目の女性であったと記している。", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["コルネリウス・ガルスが最初のエジプト長官となった;ヘロオンポリスとテーベの反乱を鎮圧し、クシュとの国境が確保された", "9f688855"], "d": ["オクタウィアヌスはエジプトを税の対象となる特別の属州とし、その統治を元老院議員ではなく騎士身分の長官に任せた;最初の長官はコルネリウス・ガルスとなった。ストラボンは、ガルスがヘロオンポリスで反乱を起こした町を少数の兵で攻略し、テーベで税をめぐって起きた蜂起を短期間で鎮圧したと記している。フィラエのガルスの碑は、クシュの君主の使節がここで引見され、トリアコンタスコイノス地方が保護下に置かれたことを伝えている。", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["オクタウィアヌスがアレクサンドリアに入った;プトレマイオス朝が終わり、エジプトはローマに移った", "553804ca"], "d": ["アントニウスの艦隊と騎兵がオクタウィアヌスに寝返った後、オクタウィアヌスはアレクサンドリアに入った;アントニウスは自害し、クレオパトラもまもなく死去した。オクタウィアヌスはアレクサンドリアの民を赦し、「王を見たかったのであって、死者ではない」と言ってプトレマイオス朝の墓を訪れず、エジプトを税の対象の国としてコルネリウス・ガルスに与えた。この年をもって300年続いたプトレマイオス朝の王国は終わった。", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["アクティウムの海戦:オクタウィアヌスがアントニウスとクレオパトラを破った", "7e46cc73"], "d": ["オクタウィアヌスの艦隊はアクティウムでアントニウスとクレオパトラの艦隊を破った;二人はエジプトに退いた。カッシウス・ディオは、日付を記すことを避ける著者でありながらこの日を特に記している。これはオクタウィアヌスがこの日以降、帝国を単独で掌握し、権力の年がこの日から数えられたためである。", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["アレクサンドリアの贈与:アントニウスがクレオパトラとその子供たちを東方の諸王国の君主と宣言した", "24e24981"], "d": ["ギュムナシオンに集まった群衆の前に金の玉座を設けさせたアントニウスは、クレオパトラをエジプト、キプロス、リビア、コイレ・シリアの女王、カエサリオンをその共同統治者、子供たちをアルメニア、メディア、パルティア、およびフェニキア・シリア・キリキアの王と宣言した。ローマでこの儀式はアントニウスに対する宣伝となり、内戦を早めた。", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["アントニウスがクレオパトラにキプロス、フェニキア、コイレ・シリア、キリキアの一部を贈った", "cf19a357"], "d": ["プルタルコスによれば、アントニウスはシリアに来た時、クレオパトラにフェニキア、コイレ・シリア、キプロス、キリキアの大部分、ユダヤの香油の採れる側、ナバテアの海に伸びる部分を与えた。こうしてプトレマイオス朝は、プトレマイオス3世以来初めて、東地中海の広い領域を(ローマの怒りにもかかわらず)掌握した。", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["アレクサンドリア戦争:カエサルがプトレマイオス13世を破り、エジプトをクレオパトラに委ねた", "96c9b516"], "d": ["カエサルがアレクサンドリアに来て、クレオパトラとプトレマイオス13世の間の調停を行おうとすると、宮廷の軍勢が彼を包囲した;冬の間続いた市街戦の中でカエサルに援軍が来て、ナイルの戦いでプトレマイオス13世は溺死した。カエサルはエジプトをクレオパトラと幼い弟プトレマイオス14世に与えた;ローマの軍団はアレクサンドリアに留まった。", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["ガビニウスがローマ軍でプトレマイオス12世をエジプトの王位に復位させた;アレクサンドリアにローマの守備隊が残った", "41d8f47d"], "d": ["追放されたプトレマイオス12世(アウレテス)は、シリア総督ガビニウスに多額の賄賂を贈ってエジプトへの入国を買った;ガビニウスはパルティア遠征をやめてペルシウムからエジプトに入り、アウレテスを王位に復した。これはエジプトの独立が事実上ローマの保証に依存するようになった時点である。ガビニウスはのちにローマで裁かれた。", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["ローマがキプロスをプトレマイオス朝から取り上げて併合した;カトーが島に派遣された", "678b2115"], "d": ["プトレマイオス12世の兄弟であるキプロス王は、クロディウスの提案でローマが島を取ることに抵抗しなかった;カトーが島を引き継ぐために派遣された。プトレマイオス朝はキプロスを失い、沿岸の最後の海軍基地を失った。プルタルコスは、カトーの「キプロスへの派遣」をポンペイウスの伝記で語っている。", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["「エレウシスの日」:ローマの使節ポピリウス・ラエナスがアンティオコス4世にエジプトからの撤退を強いた", "e6883e6a"], "d": ["ピュドナの戦い(紀元前168年6月22日)の直後、ローマの使節ガイウス・ポピリウス・ラエナスは、アレクサンドリアを包囲していたアンティオコスに、戦争をやめよという元老院の命令を伝えた;王が返答を考えられるよう、その周りに円を描いた。アンティオコスは撤退した。エジプトはローマの保護の下に独立を失うことなく存続した。", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["アンティオコス4世がエジプトを攻撃した;第六次シリア戦争でメンフィスとナウクラティスに進んだ", "b85e6712"], "d": ["アンティオコス4世は、プトレマイオス6世のコイレ・シリア奪還の準備に対してエジプトに入り、ペルシウムからナイルに下った;コイレ・シリアの権利を主張し、ナウクラティスで住民に好意的に振る舞った。戦争はエジプトを破壊せずに、だが国家を弱体化させて、ローマの介入により1年後に終わった。", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["テーベの反乱が鎮圧された:コマノスが上エジプトをプトレマイオス朝の支配に取り戻した", "4c0e4f10"], "d": ["約20年の分離主義的統治の後、プトレマイオス朝の司令官コマノスは、テーベを在来のファラオ、アンクウェンネフェルから取り戻し、上エジプトは再びプトレマイオス朝国家に結びつけられた。", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["メンフィス会議がロゼッタの勅令を出した:プトレマイオス5世が神殿に租税の免除を認めた", "5643b91f"], "d": ["エジプトの神官たちがメンフィスで開いた会議は、プトレマイオス5世の即位を承認し、王が神殿に行った租税の免除、反乱の鎮圧、王の祭祀の確立を宣言した。勅令はギリシア語、デモティック、ヒエログリフで書かれた;ロゼッタ・ストーンはこの三言語の文書である。文はまた、デルタの反乱者(リュコポリス)が鎮圧されたことにも触れている。", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["パニオンの戦い:アンティオコス3世がスコパスを破った;コイレ・シリアはプトレマイオス朝からセレウコス朝に移った", "97e30e58"], "d": ["第五次シリア戦争でアンティオコス3世は、プトレマイオス朝の司令官アイトリア人スコパスをパニオンで敗走させた;ヨセフスによれば、アンティオコスはスコパスが奪ったコイレ・シリアの都市を取り戻してサマリアも取り、ユダヤ人は自らの意志でアンティオコスに加わった。コイレ・シリア(シリア・パレスチナ)はこれ以後セレウコス朝の統治下に入り;プトレマイオス朝は地域から撤退した。", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["テーベで分離主義的な在来のファラオが現れた:上エジプトがプトレマイオス朝の支配から離れた", "d10abb36"], "d": ["ラフィアの勝利の後に武装させられた在来のエジプト人は、ポリュビオスの表現によれば勝利に驕って王の命令を聞かなくなった;デルタと上エジプトで蜂起が起こった。テーベでは在来のファラオたち(ホルウェンネフェル、のちアンクウェンネフェル)が約20年間、プトレマイオス朝に対して上エジプトを握っていた。", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["ラフィアの戦い:プトレマイオス4世がアンティオコス3世を破った;コイレ・シリアはプトレマイオス朝に残った", "34362178"], "d": ["ラフィアでプトレマイオス4世の軍は、多数の在来エジプト人のファランクス(重装歩兵)を含む編成で、アンティオコス3世の軍を破った;アンティオコスはコイレ・シリアから撤退し、地域は200年までプトレマイオス朝の手にあった。在来のエジプト人の武装は、のちに上エジプトでの分離主義的な反乱を育てた。", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["アンティオコス3世がセレウキア・ピエリアをプトレマイオス朝から取り戻した", "39ee3a52"], "d": ["アンティオコス3世は、プトレマイオス朝の手にあったセレウキア・ピエリアを包囲し、将校たちに賄賂を贈って奪った;ポリュビオスは、都市がプトレマイオス3世の時代からエジプトの王たちに属する守備隊によって保たれていたと記している。この勝利でセレウコス朝はアンティオキアの港を得て、コイレ・シリアへの進軍に備えた(第四次シリア戦争)。", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["プトレマイオス3世がラオディケ戦争でシリアとメソポタミアに侵攻した;セレウキア・ピエリアがプトレマイオス朝の手に渡った", "04472253"], "d": ["プトレマイオス2世が紀元前246年1月28日に死去すると、プトレマイオス3世は妹ベレニケを守るためセレウコス朝に攻め込んだ。セレウキア・ピエリアとアンティオキアで迎えられた;バビロニア年代記(BCHP 11)は、彼の軍が紀元前246年12月からバビロンに迫っていたと伝えている。アドゥリス碑文は、ユーフラテス川以西、キリキア、パンフィリア、トラキアを征服したと主張している。セレウキア・ピエリアは長年プトレマイオス朝の手にあった。", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["イプソスの後、プトレマイオスがコイレ・シリアに侵攻した;セレウコスが異議を唱えた(シリア戦争の根源)", "a109388f"], "d": ["イプソスの戦い(紀元前301年)の後、セレウコス、リュシマコス、カッサンドロスは合意してシリア全体をセレウコスに与えた;一方プトレマイオスはコイレ・シリアに軍で侵攻してこれを保持した。この係争は、その後の2世紀に6回のシリア戦争を生んだ。アンティオコス3世は後に、ポリュビオスが伝えるようにこの主張を擁護した。", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["プトレマイオスが自らを王と宣言した;プトレマイオス朝が正式に成立した", "008c723a"], "d": ["アンティゴノスとデメトリオスが王の称号を取った(紀元前306年)後、プトレマイオスも王の称号を取った;エジプトは独立したヘレニズム王国と呼ばれ始めた。王朝がエジプトのファラオとして示されたことは、在来の神官階級との妥協をも早めた。", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["ガザの戦い:プトレマイオスとセレウコスがデメトリオスを破った(シリアは短期間プトレマイオス朝に)", "ea0d264f"], "d": ["アンティゴノスの子デメトリオスは、ガザの前でプトレマイオスとセレウコスの連合軍に敗れた;プトレマイオスはコイレ・シリアに入った。アンティゴノスの反撃により地域はまもなく再び手から離れ、和平(紀元前311年)がこれを固定した。", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["ペルディッカスのエジプト遠征がナイル渡河で失敗した;ペルディッカスは自軍の手で殺された", "c1792117"], "d": ["ディアドコイ戦争で、アレクサンドロスの摂政ペルディッカスは、アレクサンドロスの葬列を奪ったプトレマイオスに対してエジプトに入ったが、ナイルを渡れず、多数の兵を失い、将校たちによって殺された。プトレマイオスはエジプトを保った。", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["プトレマイオスがキュレネ(キュレナイカ)をエジプトに加えた", "65316c50"], "d": ["プトレマイオスは、キュレネの内紛に介入し、Ophellasの指揮でリビアのキュレナイカ地方をエジプトに結びつけた。こうしてプトレマイオス朝のエジプトは西にも拡大した;キュレナイカは、その後の世紀にプトレマイオス家の一つの分家の手にあった。", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["アレクサンドロスがシーワ・オアシスでアメンの神託に伺いを立てた", "c437ced0"], "d": ["アレクサンドロスは沿岸から砂漠に入り、アメン神殿のあるシーワ・オアシスに赴いて神託に伺いを立てた;アッリアノスは、彼が心にかなう答えを得たと記している。この訪問は、アレクサンドロスのエジプトでの正統性と、のちに神の子とみなされたとの語りを育んだ。", "40603afa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0331-01-01:0":{"b": ["アレクサンドロスがエジプトに入った;ペルシアのサトラップ、マザケスが降伏し、エジプトはマケドニアの統治に移った", "c4a5f014"], "d": ["ガザから出発したアレクサンドロスは7日目にペルシウムに着き、艦隊もそこに達していた。イッソスの後ペルシアの支援を失っていたサトラップのマザケスは抵抗せず、アレクサンドロスを都市で友好的に迎えた。アレクサンドロスはペルシウムに守備隊を置いてメンフィスに進んだ;統治を二人の在来の総督(Doloaspis、Petisis)に任せ、メンフィスとペルシウムにマケドニア人の司令官を任命した。エジプトはペルシアの支配から離れ、アレクサンドロスの帝国に加わった。", "08c837eb"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0342-01-01:0":{"b": ["アルタクセルクセス3世がエジプトを再征服した;ネクタネボ2世はヌビアに逃れた", "55d78a8d"], "d": ["アルタクセルクセス3世がシドンを攻略した後のエジプト進軍で、ペルシウムの防衛が崩れた;ネクタネボ2世はメンフィスで包囲されるのを待たず、上エジプトとヌビアに逃れた。エジプトは二度目のペルシアのサトラップ領となった;最後の在来のファラオの運命は知られていない。", "373a5f39"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0359-01-01:0":{"b": ["タホスがシリア遠征に出た;ネクタネボ2世がクーデターで王位を奪い、アゲシラオスが陣営を替えた", "4e1e9804"], "d": ["タホスは、ペルシア領シリアを攻撃するため、ギリシア人傭兵(スパルタ王アゲシラオスとアテナイ人カブリアス)を集めた;遠征中に甥のネクタネボ2世が自らを王と宣言した。アゲシラオスはネクタネボの側についた;プルタルコスは、アゲシラオスが老年に一人の「蛮族の反逆者」のために報酬を得て戦ったことがギリシアで批判されたと記している。", "d9ffa449"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0372-01-01:0":{"b": ["ネクタネボ1世がペルシアの侵攻(ファルナバゾス・イピクラテス)を撃退した", "0a8bc67d"], "d": ["第30王朝の創設者ネクタネボ1世は、ファルナバゾス指揮下のペルシア軍とアテナイ人イピクラテスのデルタへの上陸を、ナイルの増水と司令官同士の不和のおかげで退けた。この成功はエジプトの独立をさらに30年延ばした。", "edb11f45"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0459-01-01:0":{"b": ["イナロスの反乱:アテナイが支援したエジプトの蜂起がメンフィスでペルシア人を追い詰めた;紀元前454年にプロソピティスで崩壊した", "0cd93c33"], "d": ["リビア人イナロスは、アルタクセルクセスに対してエジプトのほぼ全土を蜂起させ、アテナイ人に援助を求めた;アテナイ艦隊はナイルに入ってメンフィスの3分の2を奪い、残る「白い城」を包囲した。ペルシアの司令官メガビュゾスは、アテナイ人をプロソピティス島で1年半包囲し(水路を干上がらせて)滅ぼした;イナロスは捕らえられて磔にされた。デルタの湿地にいたアミュルタイオスは捕らえられなかった。", "452e1e06"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0485-01-01:0":{"b": ["エジプトがペルシアの支配に対して反乱を起こした;クセルクセス1世は反乱を鎮圧してエジプトをより重く統治した", "9d3d7462"], "d": ["ダレイオス1世の死の前に始まったエジプトの反乱は、クセルクセス1世の最初の数年に鎮圧された;クセルクセスは弟アカイメネスをサトラップに任命し、エジプトをダレイオスの時代よりも重く統治し始めた。", "db4dbf1d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0522-01-01:0":{"b": ["カンビュセスのクシュ遠征が渇きと食糧の欠乏で失敗した;エジプトの南の国境はエレファンティネに留まった", "4ebbad8c"], "d": ["カンビュセスはエジプトの後、「長寿のエチオピア人」(クシュ)に対する遠征を計画した;ヘロドトスによれば、クシュ王はペルシアの使節に弓を送り、「弓を楽に引けるようになったら」攻撃せよと言った。軍は砂漠で食糧を失い引き返した。ストラボンも、カンビュセスの軍が砂漠の嵐で全滅した場所に触れている。クシュは独立を保った;ペルシア人の南の国境はエレファンティネで止まった。", "141a4dc5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0569-01-01:0":{"b": ["アマシスがアプリエスを破ってエジプトの王位に就いた;ギリシア人商人がナウクラティスに入植させられた", "75a24b0b"], "d": ["ギリシア人傭兵とともにリビア遠征から戻ったアプリエスは、軍の在来部隊の長となったアマシスにモメンフィスで敗れた;アマシスはサイスからエジプトを統治し、ギリシア人にナウクラティスを唯一の通商港として割り当てた。その治世の終わり(紀元前526年)にペルシアの脅威が大きくなった。", "821328d0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0592-01-01:0":{"b": ["プサムテク2世がヌビアに遠征した:クシュのエジプト国境への圧力が砕かれた", "8f0aaf9d"], "d": ["プサムテク2世のヌビア遠征は、ヘロドトスでは「エチオピアへの遠征」として語られている;エジプト軍とギリシア人/カリア人傭兵はアブ・シンベルにギリシア語の銘を残した。テーベ(カルナク)の3年目の碑はクシュ王国に大敗を与えたと伝え、カラブシャの戦勝碑がこれを記念している;遠征は第三あるいは第四急流まで進んだとされる。史料によれば、クシュの政治的中心はその後の時代(アスペルタ、紀元前591年頃)に南のメロエに移った。", "17c955db"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0600-01-01:0":{"b": ["ネブカドネザルがエジプトの国境を攻撃した;野戦で両軍が大損害を出し、バビロンは退却した", "45655313"], "d": ["バビロニア王ネブカドネザルは4年目にエジプトに進軍した;エジプト王は軍を集めて迎え撃ち、野戦で両軍は互いに大きく消耗した。ネブカドネザルはバビロンに戻って軍の再装備に引いた。エジプトは国境を守ったが、シリア・パレスチナはバビロンのものとなっていた。", "c561b28b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0604-01-01:0":{"b": ["カルケミシュの戦い:ネブカドネザルがエジプト軍を破った;エジプトはシリアを失った", "ba486ac1"], "d": ["皇太子ネブカドネザルはバビロニア軍とともに、カルケミシュにいたエジプト軍に対してユーフラテスを渡って敗走させ、逃げる者をハマトの地方で滅ぼし、ハマト地方全体を奪った。エジプトはシリアから撤退してシナイの国境の後ろに戻った;バビロンはシリア・パレスチナの主となった。", "61bb7c47"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0608-01-01:0":{"b": ["ネコ2世がシリア・パレスチナに入った;メギドでヨシヤを破りユーフラテスに向かって進んだ", "f887d6fd"], "d": ["崩壊するアッシリアの西方の諸州を奪おうとしたネコ2世は、シリアに進軍した;途上にいたユダ王ヨシヤをメギドで殺させた。ヘロドトスは「ネコはマグドロスでシリア人を破り、大きなシリアの都市カデュティスを奪った」と述べている。こうしてエジプトは短期間、シリア・パレスチナをユーフラテスまで掌握した。", "573a58de"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0655-01-01:0":{"b": ["プサムテク1世が娘ニトクリスをテーベの「神の妻」の養女とさせて上エジプトを掌握した", "bf768452"], "d": ["プサムテク1世は、9年目に、娘ニトクリスがクシュ王タハルカの娘シェペンウェペト(テーベの「神の妻」)の養女としてテーベに送られるようにした;シェペンウェペトは財産をニトクリスに譲り、テーベの神殿の資産はこうしてサイス朝の手に渡った。養子縁組の碑は、プサムテクが9年目にテーベを完全に掌握したこと、タンタマニがその時までに上エジプトを失っていたことを示している。", "f750f320"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0662-01-01:0":{"b": ["アッシリア軍がテーベを略奪した;タンタマニは南に退き、クシュのエジプトでの支配は崩壊した", "777fc1a5"], "d": ["アッシュルバニパルの軍はタンタマニをメンフィスから追ってテーベまで進み、都市を略奪した;テーベの神殿の財宝はニネヴェに運ばれた。タンタマニはヌビアに退いた;上エジプトでクシュの支配は解けた。この略奪は旧約聖書で「ノ・アモン」(ナホム書3:8)として語られている。", "3d4dea25"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:0":{"b": ["第26王朝が始まった:プサムテク1世がサイスでアッシリアの藩属として下エジプトで権力を得た", "f270eac3"], "d": ["アッシリアがエジプトに置いたデルタの諸侯の中から、サイスの君主プサムテク1世が第26(サイス)王朝を始めた。ヘロドトスによれば、プサムテクは「十二人の王」の中から抜け出して湿地に追われ、デルタを再び手に入れた。アッシリアとクシュの後、エジプトは再び在来の王朝の手に渡った;テーベと上エジプトの獲得には数年を要した。", "eaebf639"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:1":{"b": ["タンタマニがクシュから下ってテーベとメンフィスを再び奪った;アッシリアの藩属を包囲した", "f84c87a4"], "d": ["タハルカの後継者タンタマニは、夢の碑によれば、ナパタで戴冠した後に川を北に下った:エレファンティネでクヌムに供物を捧げ、テーベとメンフィスに来てここで自らに逆らう者を虐殺して都市を奪い、デルタの諸侯は隠れるか服従した。この企てはプサムテク1世とアッシリアのデルタの秩序を脅かし、アッシリアの懲罰遠征をもたらした。", "d8ce2798"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0670-01-01:0":{"b": ["エサルハドンがエジプトに入ってメンフィスを奪った;タハルカは南に退いた", "a138bcac"], "d": ["アッシリア王エサルハドンは10年目にエジプトに進軍した;アッシリア軍はエジプトで大虐殺を行い、クシュ王タハルカは南に逃れた。デルタの諸侯国はアッシリアの藩属となり、メンフィスと北エジプトは一時的にアッシリアの手に渡った。エサルハドンは2年後に新たな遠征に出る際に途上で死去した。", "4c58b398"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0700-01-01:0":{"b": ["センナケリブのユダ遠征でクシュ・エジプト軍とエルテケで対峙した", "7f423351"], "d": ["アッシリア王センナケリブのカナン遠征で、クシュ人のエジプト軍はユダの救援に来てエルテケでアッシリアと衝突した;アッシリア軍はエルサレムを攻略できずに退いた。ヨセフスは、クシュ王ティルハカが大軍で来るとの知らせを受けたセンナケリブがペルシウムから去ったと語る。これは、クシュ・エジプトとアッシリアの最初の直接の衝突である。", "0bc942e3"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0724-01-01:0":{"b": ["ピイ(パンキ)がエジプトに下った:テフナクトの連合を破り、メンフィスとデルタの君主たちを服従させた", "bb36f7c4"], "d": ["サイスのテフナクトは、デルタからメンフィスと中部エジプトに及ぶ同盟を築いてヘラクレオポリスを包囲していた。ナパタから遠征に出たピイは、21年目に北に下って、同盟した都市(ヘルモポリス、メンフィス、ヘリオポリス)を攻略し、デルタの諸侯の降伏を受け入れた;その後ナパタに戻った。こうしてクシュはエジプト全土の長となった(第25王朝)。", "8a8bbba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0749-01-01:0":{"b": ["クシュ(ナパタ)の王カシュタが上エジプトに進んだ;エレファンティネとテーベに影響を及ぼした", "b0f5be7f"], "d": ["ナパタのクシュの王たちは、エジプトの第三中間期の分裂を利用して北に向かって強まった。カシュタが上エジプトでエレファンティネまで影響を確立したことは記念物から知られる;クシュ王家のアメニルディス1世(ピイの姉妹)はテーベでアメンの「神の妻」の称号で据えられ、この地位はクシュのテーベに対する仲介となった。こうして第25王朝が成立する地盤が整えられた。", "3540bb2c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0924-01-01:0":{"b": ["シェションクがカナンに遠征した:エルサレムとイスラエル・ユダの都市がカルナクの一覧に入った", "1607ae3a"], "d": ["シェションクのカナン遠征は、レハブアム王の5年にエルサレムから貢物を取ったと伝えるトーラーの語り(列王記上14:25)と一致する;カルナクのブバスティス門には約150の都市名が並べられている(おおよそ50-60がイスラエル、100がユダのもの)。ヨセフスもシサクがエルサレムを奪って財宝を持ち去ったと語る。この遠征は、第三中間期のエジプトの最長の対外作戦である。", "13f6482e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0944-01-01:0":{"b": ["シェションク1世(メシュウェシュ/リビア系)が第22王朝を築いた;首都はブバスティス", "dae122c7"], "d": ["リビア系のメシュウェシュの将軍たちは、新王国の後にデルタに定着していた;そのうちシェションク1世がタニスの第21王朝の後にエジプトを再統一した。子をアメンの大司祭としてテーベも王朝に結びつけた。この時代は、エジプトを再び対外政策(カナン遠征)に向かわせた短い回復をもたらした。", "09d0b8f9"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1068-01-01:0":{"b": ["新王国が終わった:ラムセス11世の最晩年にデルタでスメンデス(タニス)、テーベでアメンの大司祭が事実上独立した", "1828ceb0"], "d": ["ラムセス11世の最晩年に中央の国家は崩壊した:テーベではアメンの大司祭ヘリホルが上エジプトを掌握し、デルタのタニスではネスバネブジェド(スメンデス)が統治した;ウェンアムンの物語はこの分裂(ウェンアムンのヘリホルからスメンデスに至る旅)を記録している。スメンデスはついに第21王朝を築いた;ヌビアもこの混乱の中でエジプトの支配から離れた。", "2317479f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1176-01-01:0":{"b": ["ラムセス3世が海の民を陸上(ジャヒ)とデルタの海で破った", "9068ae7b"], "d": ["ラムセス3世の8年に、ペレセト、チェケル、デニェン、シェルデンおよびその他の海の民が陸と海からエジプトの国境に向かった;エジプト軍は、まずカナンの国境で、続いてデルタの河口の海戦で彼らを止めた。メディネト・ハブの浮彫がこれを記録している。エジプトはカナンを再び保ったが、この時代以後、東地中海での影響力は侵食され始めた。", "a7654a37"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1208-01-01:0":{"b": ["メルエンプタハがリビアと海の民の同盟を西デルタで破った;カナンで「イスラエル」の名が初めて語られた", "e512311e"], "d": ["メルエンプタハの5年に、リブ人を先頭にメシュウェシュと「海から来た民」(エクウェシュ、テレシュ、ルッカ、シャルダナ、シェケレシュ)が西デルタに侵入した;エジプト軍はペリレで6時間の戦いで彼らを散らした。同じ出来事を語る戦勝碑は、カナンのアシュケロン、ゲゼル、イェノアムと「イスラエル」を数え上げて名を挙げる;これはイスラエルの名の知られている最古の言及である。", "6a9d6afc"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1258-01-01:0":{"b": ["ラムセス2世とハットゥシリ3世の間の「永遠の条約」:エジプト・ヒッタイトの戦争が終わった", "100f2a75"], "d": ["ラムセス2世の21年に、ヒッタイトの使節が条約の粘土板をピ・ラメセスに持ってきた。条約は約15年のシリア戦争を終わらせた:両者はシリアでのさらなる征服の計画を放棄し、防衛同盟を結び、逃亡者の引き渡しと相互援助を受け入れた。ブレステッドの要約によれば、国境は文中に述べられない;両国の勢力圏は事実上の状況(カデシュ・アムルの帯はハッティに、カナンはエジプトに)のままであった。", "9b723519"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1273-01-01:0":{"b": ["ラムセス2世がカデシュでムワタリ2世のヒッタイト軍と対峙した;結果は引き分けに終わった", "f5ad96db"], "d": ["ラムセス2世は、オロンテス川畔のカデシュの前でヒッタイト軍と対峙した;ヒッタイトの戦車が待ち伏せしたことでエジプト軍は壊滅寸前に至り、ラムセスは自らの護衛とともに反撃して押し返した。戦いは決定的な結果を生まなかった;カデシュとアムルはヒッタイトの支配下に残り、エジプトの北の国境はやはりカナンの沿岸に留まった。", "b58cad94"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1293-01-01:0":{"b": ["セティ1世が南カナンからフェニキアの沿岸まで遠征した:エジプトはカナンとレバノン沿岸を再び支配し、カデシュを奪った", "ad7bf1cd"], "d": ["カルナクの浮彫によれば、セティ1世の1年の遠征はまずシャスウの遊牧民を、ついでパレスチナを経て北に上り、ペヘル、ベト・シェアン、イェノアム、ティルス、レバノンの首長たちを服従させた。浮彫の上段にはカデシュの攻略も示されている。ブレステッドは、恒常的な北の国境がフェニキアの沿岸に沿う東西の線を越えて伸びなかったこと、ヒッタイトの力が砕かれなかったことを述べている;これはラムセス2世のカデシュの戦いの背景である。", "aa320c30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1339-01-01:0":{"b": ["アマルナ時代にエジプトの北シリアでの支配が解けた;アムルとカデシュがヒッタイトの勢力圏に移った", "90d00c5a"], "d": ["アマルナ文書(EA)は、北シリアの藩属(アムルのアジル、カデシュの君主たち)がエジプト、ミタンニ、ハッティの間で立ち回り、エジプトが地域に介入できなかったことを示している。ヒッタイト王シュッピルリウマ1世のミタンニを消耗させた遠征の結果、アムルとカデシュはヒッタイトの影響下に入った;こうしてエジプトのシリアでの北の国境はカナンまで後退した。", "c876708d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1347-01-01:0":{"b": ["アメンホテプ4世(アクエンアテン)がエジプトの首都をアケトアテン(アマルナ)に移した", "53cadac3"], "d": ["アクエンアテンはアテン信仰を国家の宗教とし、中部エジプトの砂漠に開かれた新しい都市(アケトアテン)を首都と宣言した;都市の境界を定める「境界碑」は4-5年に年代づけられる。アマルナ文書は、この時代にシリアの藩属が助けを求めたがエジプトが応じなかったことを示している。", "a7911bcf"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1424-01-01:0":{"b": ["アメンホテプ2世がヌビアでナパタに達して南の国境碑を立てた:エジプトの最南端", "2f61f824"], "d": ["アメンホテプ2世はシリア遠征からの帰途(7月)にヌビアに渡った;エレファンティネとアマダの神殿の銘によれば、シリアから連れてきた7人の王子のうち6人をテーベの城壁に、7人目をナパタの城壁に吊るさせた。ブレステッドによれば、王はナパタかそのすぐ上に南の国境を示す碑を立てた:エジプトのヌビアでの事実上の主権は、こうしてトンボス(第三急流)を越えて第四急流の地域まで及んだ。", "31d51fb0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1446-01-01:0":{"b": ["トトメス3世がユーフラテスを渡ってミタンニの領土に入った;ナハリンに国境碑を立てた", "ebdbeebe"], "d": ["33年目にトトメス3世はレテヌから進んでユーフラテスを渡り、ナハリンの町々を略奪し、川の東に国境碑を立てた;父の碑の隣に2つ目を置いた。この遠征はエジプトの影響の北の最遠点であり、ミタンニとの直接の衝突の瀬戸際を示している。", "e7a917e6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1456-01-01:0":{"b": ["トトメス3世がメギドでカデシュを首領とするカナンの連合を破った;カナン・シリアがエジプトの支配下に入った", "439dc6e8"], "d": ["トトメス3世の23年、シェムウ季第1月21日、メギドの前でカデシュの君主を首領とするカナンの連合を破った;敵は都市に逃れ、メギドは長い包囲の末に降伏した。カルナクの年代記に記録されたこの遠征は、エジプトのカナンと南シリアに対する従属関係を恒久的なものとし、帝国の拡大の始まりとなった。", "8c75d558"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1498-01-01:0":{"b": ["トトメス1世がユーフラテス河畔(ナハリン)に達するアジア遠征を行った", "50ce0679"], "d": ["イアフメス・ペンネクベトとイアフメス・エバナの銘によれば、トトメス1世はヌビア遠征の後、ナハリンへ大遠征を行った;トトメス3世はのちにユーフラテスの上で父が立てた国境碑の隣に自らの碑を加える。これは、エジプトの影響がユーフラテスまで及んだ最初の記録された時期である。", "bc058844"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1524-01-01:0":{"b": ["イアフメスが下ヌビアに遠征してヌビアの高地民を制圧した", "dbbd94b7"], "d": ["イアフメスは、アジア人を破った後、川を南にケント・ヘン・ネフェルまで上り、ヌビアの高地民を制圧した。この遠征は、中王国の要塞線以来ケルマの手にあった下ヌビアのエジプトへの編入の過程の最初の一歩である。", "df3be70d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1529-01-01:0":{"b": ["アハメスがヒクソスの首都アヴァリスを奪い、シャルヘンを包囲して陥落させた", "b7bb3099"], "d": ["アハメスは東デルタのアヴァリスを包囲して奪った。ヒクソスはアジアへ逃れ、アハメスは彼らを南カナンのシャルヘンまで追撃した。エバナの子アハメスの碑文は、シャルヘンが6年間包囲されたと伝える。こうしてエジプトのデルタはヒクソスの支配を脱し、エジプトはカナンに政治的影響力を及ぼしうる位置に立った。", "48e6f876"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1549-01-01:0":{"b": ["アハメス1世がテーベで即位し、第18王朝と新王国時代が始まった", "0798cfa3"], "d": ["テーベの第17王朝最後の王カーメスの弟アハメスは幼少で即位した。その治世のうちにヒクソスをエジプトから追い、ヌビアとカナンへの支配を再建して、第18王朝と新王国時代を開くことになる。即位はヒクソスの終焉ではなく、闘争の最終局面の始まりである。", "a003c4aa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1649-01-01:0":{"b": ["エジプトが二分された。ヒクソス(第15王朝)はアヴァリスから下エジプトと中エジプトを、テーベの第17王朝は上エジプトを統治した", "cd743737"], "d": ["東デルタのアヴァリスに定住したカナン系出自の「異国の支配者」(ヒクソス)は第15王朝を立て、下エジプトと中エジプトをクサエ(クシヤ)まで支配した。一方、テーベの在地の第17王朝は上エジプトを保持した。テーベの南ではケルマ王国が独立した勢力として存続した。アヴァリスがヒクソスの首都であったことは、アハメスの包囲の記述によりブレステッドで裏づけられる。", "6bb8eb9b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1866-01-01:0":{"b": ["センウセレト3世がセムナでエジプトの南の国境を第2急流に引き、ヌビア人の通行を禁じた", "753ef5fd"], "d": ["センウセレト3世の治世8年のセムナ碑文は「南の国境」を定め、交易のためイケンへ来る者を除き、ヌビア人が陸路でも水路でもこの線を越えることを禁じている。王は下ヌビアに要塞群(ブヘン、セムナ、クンマ、ウロナルティなど)を築き、ケルマの北進を食い止めた。これは中王国がヌビアに築いた最南端の恒久的な国境である。", "e50a591d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1984-01-01:0":{"b": ["アメンエムハト1世が第12王朝を創始し、首都をイチ・タウイに移した", "26c43dad"], "d": ["宰相から王となったアメンエムハト1世は第12王朝を創始し、首都をテーベから、メンフィスとファイユームの間の新都市(イチ・タウイ)に移した。この王朝は中王国の最も安定した時代を築き、ヌビアに対する要塞体制を整えた。", "55432fe0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2015-01-01:0":{"b": ["メンチュヘテプ2世がヘラクレオポリスを破り、エジプトを再統一した(セマタウィ)", "dbc6136f"], "d": ["治世第39年ごろ、メンチュヘテプ2世はヘラクレオポリスを滅ぼして上下エジプトを単一の統治下に置き、称号に「二つの国を統一する者」(セマタウィ)の名を加えた。中央の統治はテーベに移され、ノマルコスの権限は削減された。", "d3ad8b02"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2054-01-01:0":{"b": ["メンチュヘテプ2世がテーベで即位し、中王国時代が始まってヘラクレオポリスとの戦いが激化した", "edde038d"], "d": ["メンチュヘテプ2世の長い治世(51年)は中王国の始まりとされる。治世の前半、テーベはヘラクレオポリスと戦争状態にあった。治世14年にヘラクレオポリス軍がアビドスの聖なる墓地を荒らしたため、王は北へ軍を進めた。エジプトの実質的な統一はずっと後、治世39年ごろに実現した(下の項目)。", "5db4eeba"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2124-01-01:0":{"b": ["テーベで第11王朝が始まった。インテフ家が上エジプトに独立した王国を築いた", "0e021743"], "d": ["テーベのノマルコスはインテフの家系から王位の称号を取り、上エジプト南端(エレファンティネからアビドスまで)に自らの王国を立てた。後のインテフは、アビドスのあるティニス州を奪い「その要塞をことごとく開いた」と碑文に記している。こうしてテーベとヘラクレオポリスの境界はアビドス周辺に引かれた。", "eddec482"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2159-01-01:0":{"b": ["ヘラクレオポリス(ヘネン・ネスト)で第9・10王朝:北エジプトをケティ家が統治した", "9dde2d0c"], "d": ["第1中間期にメンフィスの空白をヘラクレオポリスの王朝が埋めた。中エジプトのシウトの総督テフィビのような忠実なノマルコスは、南(テーベ)に対してこの王国の側で戦った。シウトの墓碑銘は、南の勢力がエレファンティネから北上し、「南の国境」まで撃退されたことを伝える。こうしてエジプトはヘラクレオポリス(北)とテーベ(南)の二大勢力に分かれた。", "5e8484b5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2180-01-01:0":{"b": ["古王国が崩壊した。ペピ2世の後に中央政府が解体し、第1中間期が始まった", "0339e96b"], "d": ["非常に長いペピ2世の治世の後に第6王朝は終わり、王国はノマルコス(州総督)が事実上独立する地域に分裂した。墓碑銘(シウト、エレファンティネなど)は、地方総督が自らの名で年代を記し、自らの兵を動員したことを示す。メンフィスの短命な第7・8王朝は全土を掌握できなかった。", "67f3dd29"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2279-01-01:0":{"b": ["エレファンティネ総督ハルクフのヤム国遠征:ヌビアの彼方との外交・通商の絆", "705b9808"], "d": ["エレファンティネ総督ハルクフは、メレンラーとペピ2世のために南のヤム国へ数回遠征した。碑文には彼が通った道と持ち帰った産物が記される。幼王ペピ2世が彼に宛てた書簡も墓碑銘に残されている。これらの遠征は、古王国の南の国境でケルマ以前/古ケルマの諸集団と接触した記録である。", "31a49890"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2299-01-01:0":{"b": ["第6王朝でウニ指揮のもと、カナン国境へヌビア人部隊を含む大遠征が行われた", "69c94c55"], "d": ["ウニの自伝によれば、王は「アジアの砂漠の住人」に対して数万の軍を集めた。軍は南エジプト(エレファンティネまで)、北、さらにヌビアの諸族(イルチェト、メジャ、ヤム、ワワト、カウ)から徴募した部隊で構成された。この文書は、古王国がヌビアを兵力供給源として用い、南カナンにまで遠征できたことを示している。", "4a1574fe"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2559-01-01:0":{"b": ["クフ王(ケオプス)のギザの大ピラミッドが築かれた", "282359fc"], "d": ["第4王朝の王クフのギザのピラミッドは、古王国の労働力と資源動員の象徴である。ヘロドトスが伝えるエジプトの神官の語りは、クフを神殿を閉ざし民に石を運ばせた暴君として描くが、これは後の時代の見方であり、同時代の文書ではない。", "6bc26700"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2685-01-01:0":{"b": ["ジョセル(第3王朝)が即位した。古王国時代とサッカラの階段ピラミッド", "23e99ef4"], "d": ["ジョセル(ネチェリケト)の統治によりメンフィスを中心とする古王国が始まる。石造建築の最初の大規模な例である階段ピラミッドは彼のために築かれた。この時代、国家はナイル渓谷とデルタを中央から統治し、シナイの鉱山とヌビアの国境(エレファンティネ)は国家の支配下にあった。", "3b6eb1c6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-3099-01-01:0":{"b": ["ナルメル(メネス)が上下エジプトを統一した。第1王朝が成立し、メンフィスが首都となった", "cd3fadb1"], "d": ["上エジプト(ティニス/アビドス周辺)の支配者ナルメルは、多くのエジプト学者によればメネスと同一人物である。彼が下エジプトを支配下に加えたことで、ナイル渓谷とデルタは初めて単一の国家となった。古い伝承によれば、メネスはナイルの流路を変えてメンフィスの地を築いた。統一は単一の出来事ではなく、ナカダIIIから続く長い過程の帰結である。", "f5802ba8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0069-07-01:0":{"b": ["ウェスパシアヌスがアレクサンドリアで皇帝に推戴された:エジプトの穀物資源が内戦の帰趨を決した", "02b78348"], "d": ["エジプト長官ティベリウス・アレクサンダーは、アレクサンドリアの軍団にウェスパシアヌスへの忠誠を誓わせた。宣誓は7月1日に行われ、ウェスパシアヌスはこの日を自らの即位日とした。ユダヤ方面軍は2日後にウェスパシアヌスの面前で宣誓した。エジプトの穀物生産は、この企ての戦略的な支えとされる。", "da411a30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0115-01-01:0":{"b": ["エジプト、キュレネ、キプロスでユダヤ人の反乱:トラヤヌスの治下、ローマは辛うじて地域を鎮圧した", "54787782"], "d": ["トラヤヌスのパルティア遠征の最中、キュレネでユダヤ人がアンドレアスの指導のもとローマ人とギリシア人を殺害した。ディオによれば、エジプトとキプロスでも同様の事件が起こり、死者の数は十万単位で語られた。トラヤヌスが派遣したルシウス・クィエトゥスが反乱を鎮圧し、キプロスへのユダヤ人の立ち入りが禁じられた。", "40f5a14f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0172-01-01:0":{"b": ["ブコロイの反乱:デルタの蜂起がアレクサンドリアを脅かし、アウィディウス・カッシウスが鎮圧した", "5f94e6bf"], "d": ["デルタのブコロイ(牧者)と呼ばれる人々が、イシドロスという神官の指導のもとに蜂起した。ディオによれば、反乱者はローマの部隊を破り、アレクサンドリアを奪う寸前に至った。シリアから派遣されたカッシウスが、反乱者の結束を崩して蜂起を鎮圧した。", "ab9f3aff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0175-01-01:0":{"b": ["アウィディウス・カッシウスがシリアとエジプトで皇帝を宣言し、3か月後に殺害された", "ce33ca9d"], "d": ["東方諸属州の司令官カッシウスは、マルクス・アウレリウス死去の知らせを受けて帝位を宣言し、反乱はシリアとエジプトに広がった(エジプト総督フラウィウス・カルウィシウスは、反乱との関係にもかかわらず後に殺されず島へ流されたことがディオに見える)。カッシウスは、ディオによれば3か月6日続いた「帝位の夢」の後、自らの士官の一人に殺された。マルクス・アウレリウスはエジプトとシリアを訪れ、誰も罰しなかった。", "d3821bc7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0270-01-01:0":{"b": ["パルミラ(ゼノビア)がエジプトを占領し、ローマの将軍プロブスが敗れた", "54568441"], "d": ["ゼノビアの名で動いたパルミラの将軍ザブダスは、7万の軍とともにエジプトへ入った。ローマの将軍テナギノ・プロブスは一時アレクサンドリアを奪還したが、敗れてバビロン要塞に籠もり、捕らえられると自害した。エジプトは1、2年のあいだ、ゼノビアの名のもとにパルミラ国家の一部とみなされた。", "ea44ec63"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0297-01-01:0":{"b": ["ドミティウス・ドミティアヌスがエジプトで皇帝に宣言された:ディオクレティアヌスがテーベ、次いでアレクサンドリアを包囲して反乱を鎮圧した", "3c765005"], "d": ["税制改革とローマ軍のパルティア戦線への引き抜きへの反発から、エジプトでドミティウス・ドミティアヌスが297年7月から8月にアウグストゥスに宣言された。アレクサンドリアを含むエジプトの大部分が彼を承認した。ディオクレティアヌスは秋にテーベの反乱者を鎮圧し、アレクサンドリアを包囲した。ドミティアヌスは297年12月に死去し、都市の防衛はアウレリウス・アキッレウスが続けたが、約8か月の包囲の末、おそらく298年3月に降伏した。", "8d6ec081"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0298-01-01:0":{"b": ["ディオクレティアヌスがエジプトの南の国境をエレファンティネ/フィラエの線に引いた:下ヌビアはノバタイに委ねられた", "725574bb"], "d": ["プロコピオスは、ディオクレティアヌスがエジプト最南部の広大な砂漠(ドデカスコイノス)を保持する費用を見て、エレファンティネの南をノバタイとブレミュエスに委ね、国境をエレファンティネに定めたと伝える(代償として毎年の支払いが定められたとも伝えられる)。こうしてローマの統治は、アウグストゥスが引いたヒエラ・シカミノスの国境から後退した。", "bba78e53"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0349-01-01:0":{"b": ["アクスム王エザナがクシュを破り、メロエ王国が終わった(紀元350年ごろ)", "7c9d95d7"], "d": ["ノバとブレミュエスの圧力で弱体化したクシュ王国をアクスム王エザナが攻撃した。エザナの碑文はノバとカス(クシュ)の諸民族に対する遠征を語り、メロエでは、アクスムの勝利を記した断片的なギリシア語碑文2点が見つかっている。メロエの最後のピラミッドは4世紀半ばに年代づけられる。クシュ国家は解体し、ノバティア、マクリア、アロディアの諸王国に分かれた。", "49687083"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0391-01-01:0":{"b": ["テオフィロスがアレクサンドリアのセラペウムを破壊させた:エジプトの異教信仰の中心が閉ざされた", "119a26c7"], "d": ["テオドシウス1世の異教祭祀禁止の勅令の後、アレクサンドリア司教テオフィロスはセラピス神殿(セラペウム)を破壊させた。都市におけるキリスト教徒と異教徒の緊張はこの事件で頂点に達した。聖典や蔵書の行方については議論がある。", "5128d07a"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0395-01-17:0":{"b": ["テオドシウス1世が死去し、帝国は恒久的に東西に分かれた。エジプトは東ローマ(アルカディウス)に属した", "54a12472"], "d": ["テオドシウスの死により、息子のアルカディウスが東を、ホノリウスが西を受け継いだ。エジプトはローマの穀物需要の主要な供給地であったにもかかわらず、東帝国(ビザンツ)の属州にとどまり、後の数世紀にコンスタンティノープルの穀物供給地となった。", "c418b085"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0451-10-08:0":{"b": ["カルケドン公会議:アレクサンドリア総主教ディオスコロスが断罪され、エジプト教会が帝国教会から分離した", "5d2d05c6"], "d": ["カルケドン公会議がエジプトのアレクサンドリア総主教ディオスコロスを断罪すると、エジプトのキリスト教徒の多数は決定を受け入れなかった。こうしてエジプトではコプト(エジプト)教会と帝国教会(メルキト派)が分かれた。この分裂は、後の数世紀にエジプトがビザンツから政治的に離れていく素地を整えた。", "0d1827cd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0019-01-01:0":{"b": ["アウグストゥスとプラアテス4世の協定:クラッススのローマ軍旗が返還された", "be5f8bda"], "d": ["クラッススとアントニウスが失ったローマの軍旗は、プラアテス4世により外交的な身振りとしてアウグストゥスに返還された。協定はユーフラテスをローマ・パルティアの国境として固め、アルメニアを緩衝地帯として残した。", "8cca70ad"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0039-01-01:0":{"b": ["パコルスとラビエヌスがシリアとパレスチナに侵攻した", "68669aa1"], "d": ["パルティアの王子パコルスと、ローマから逃れてパルティアに身を寄せたラビエヌスは、ローマのシリア諸属州に侵攻してアンティオキアとパレスチナを奪った。アントニウスの将軍ウェンティディウスは38年にギンダロスでパルティアを破り、地域を奪回した。", "c3d65f7c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0052-01-01:0":{"b": ["カルラエ(ハッラーン)の戦い:スレナスがクラッススのローマ軍を壊滅させた", "3a91cd75"], "d": ["クラッススのローマ軍団はハッラーン近郊でパルティアの騎兵と騎馬弓兵に敗れ、クラッススは殺された。この戦いはローマの東方での最も重い敗北の一つであり、ユーフラテスの国境をパルティア優位に固めた。", "3f9d31bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0091-01-01:0":{"b": ["スッラとパルティア使節オロバゾスがユーフラテスで会見した:ローマとパルティアの最初の外交接触", "f8913f2b"], "d": ["カッパドキア総督スッラは、パルティア王ミトリダテス2世の使節オロバゾスとユーフラテス河畔で会見した。ローマとパルティアは初めて公式の接触をもった。ユーフラテスはその後、両国の国境となる。", "64f67e31"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0128-01-01:0":{"b": ["アンティオコス7世シデテスがパルティア遠征中に死去し、セレウコス朝はメソポタミアを取り戻せなかった", "e5897112"], "d": ["アンティオコス7世シデテスは130-129年にパルティアからメソポタミアとメディアを奪還したが、冬営地での反乱とパルティアの攻撃により軍と自らの命を失った。この失敗によって、セレウコス朝の東方に対する主張は終わった。", "0ceb2108"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0137-01-01:0":{"b": ["パルティアがデメトリオス2世ニカトルを捕らえ、セレウコス朝はバビロンとメソポタミアを最終的に失った", "94a764ce"], "d": ["ミトリダテス1世のパルティア軍はセレウコス朝の王デメトリオス2世を捕らえ、パルティアの宮廷に留め置いた。ミトリダテスはメソポタミアをパルティア帝国に編入し、セレウコス朝は沿岸部に押し込められてシリアへ後退した。", "d53eb877"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0166-01-01:0":{"b": ["マカバイの反乱:ユダヤでアンティオコス4世の宗教禁令に対する蜂起が始まった", "41c25b76"], "d": ["アンティオコス4世エピファネスがエルサレムの神殿をオリンポスのゼウスに献じ、ユダヤの宗教的慣行を禁じると、モデインでマタティアとその息子たちが蜂起した。ユダ・マカバイは164年に神殿を取り戻して清めた(ハヌカ)。ハスモン朝が誕生した。", "ad039b3f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0170-01-01:0":{"b": ["ミトリダテス1世がパルティアの王位に就き、パルティア帝国の拡張期が始まった", "cc77639b"], "d": ["ミトリダテス1世はパルティアを帝国へと変えた。メディア(147年)、バビロンとセレウキア(141年)を奪い、エリュマイスとペルシスに宗主権を確立した。クテシフォンは後に冬の首都となる。", "248f554a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0187-01-01:0":{"b": ["アパメイアの和約:セレウコス朝はトロス山脈の西から撤退し、賠償金を支払った", "f5197a70"], "d": ["ローマとアンティオコス3世の間の和約により、トロスの西のアナトリアはローマの同盟国(ペルガモン、ロドス)に与えられた。セレウコス朝の艦隊と象の数は制限され、1万5000タラントンの賠償金が支払われた。セレウコス朝はこれ以後、シリア・メソポタミアの国家となった。", "08e214af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0204-01-01:0":{"b": ["アンティオコス3世の東方遠征(209-204年):パルティアとバクトリアの王がセレウコス朝への貢納を課された", "5c81f302"], "d": ["アンティオコス3世は、セレウコス朝の失われた東方領を取り戻すため、メディア、パルティア、バクトリアへ進軍した。アルサケス2世とエウテュデモスは貢納を課された。この遠征の後、アンティオコスは「大王」の称号を得た。", "473faaed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:0":{"b": ["アルサケス1世とティリダテスがパルタヴァを奪い、パルティア(アルサケス朝)国家を建てた", "2cd572ca"], "d": ["パルニ遊牧部族の指導者アルサケスは、セレウコス朝のサトラップであるアンドラゴラスを倒してパルタヴァを奪い、パルティア王国の初代の王となった。首都はヘカトンピュロスである。パルティア国家はその後3世紀にわたってメソポタミアとイランの覇者となる。", "1fb67f39"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:1":{"b": ["バクトリアのサトラップ、ディオドトスがセレウコス朝から離れ、グレコ・バクトリア王国が誕生した", "52faafa6"], "d": ["バクトリアとソグディアナのサトラップ、ディオドトスは、アンティオコス2世の弱体化に乗じて独立を宣言した。グレコ・バクトリアは、セレウコス朝国家の東の国境をパルタヴァとバクトリアから後退させた。", "ac02ccda"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0273-01-01:0":{"b": ["第1次シリア戦争(274-272年):セレウコス朝軍がダマスカスを取り戻し、和約が結ばれた", "0c17ee3d"], "d": ["アンティオコス1世が「象の戦い」(275年)でガラティア人を破って安全を確保すると、プトレマイオス2世と再び戦った。セレウコス朝の将軍はダマスカスを取り戻し、マガスはエジプトを攻撃し、ついに272年に和約が結ばれた。この戦争は、コイレ・シリアをめぐるプトレマイオス朝とセレウコス朝の争いの始まりである。", "20ab588f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0279-01-01:0":{"b": ["カリア戦争:プトレマイオス2世がアンティオコス1世からイオニア、カリア、リュキア、パンフィリア、キリキアの一部を奪った", "afe190ca"], "d": ["プトレマイオス2世は短く成功した遠征でアナトリアの南岸と西岸を奪い、ダマスカスに達した。アンティオコスの戦力が父に劣らないと見ると、休戦した。アンティオコスは、アナトリア内陸にある父の征服地を整える必要があったため、損失を受け入れた。", "868966e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0280-01-01:0":{"b": ["セレウコス1世がプトレマイオス・ケラウノスに殺され、アンティオコス1世が即位した", "4703b674"], "d": ["コルペディオンでリュシマコスを破ってアナトリアを手に入れたセレウコスは、ヨーロッパへ渡る際にプトレマイオス・ケラウノスに刺殺された。息子のアンティオコス1世が国を継いだが、西アナトリアで苦戦することになる。", "18a3f3a5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0299-01-01:0":{"b": ["セレウコス1世がアンティオキア(アンタキヤ)を建設した", "f4b98967"], "d": ["セレウコスはイプソスの後、シリアのオロンテス河畔に、自らの父の名を冠したアンティオキアを建設した。この都市はセレウコス王国の西の首都となり、古代最大級の都市の一つとなった。ティグリス川のセレウキアは、それ以前に東の首都として建設されていた。", "0ab29d65"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0300-01-01:0":{"b": ["イプソスの戦い:セレウコスとリュシマコスがアンティゴノスを破り、シリアはセレウコスの手に渡った", "93bf2aa9"], "d": ["ディアドコイ戦争の決定的な戦いで、セレウコスとリュシマコスはアンティゴノスを破った(アンティゴノスは戦死)。東方の全域とシリアはセレウコスの取り分となった。一方プトレマイオスはコイレ・シリアを占領し、最初のシリア戦争の原因をつくった。", "a2ab17a8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:0":{"b": ["セレウコス1世がティグリス川にセレウキアを建設した", "032efabd"], "d": ["セレウコスはバビロン近くのティグリス河畔にセレウキアを建設し、バビロンの人口をここへ移し始めた。セレウキアは約30万の人口をもつ東方最大のヘレニズム都市となり、のちにパルティア帝国の首都の隣の都市となった。", "a1aa43e3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:1":{"b": ["セレウコス1世がインドでチャンドラグプタ・マウリヤと協定を結び、アラコシア、ゲドロシア、パロパミサダイをマウリヤ朝に譲った", "3ef3bdee"], "d": ["セレウコスは、アレクサンドロスのインドのサトラップ領を取り戻すためインドへ進軍したが、チャンドラグプタと合意し、東方領の一部を500頭の戦象と引き換えた。この協定はマウリヤ帝国の西の国境をヒンドゥークシュまで進め、セレウコスに西方での戦いのための象をもたらした。", "95b2b8bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0309-01-01:0":{"b": ["アレクサンドロス4世が母ロクサネとともに殺害され、アルゲアス朝が断絶した", "3be9d974"], "d": ["311年の和約の後、カッサンドロスの命により(ディオドロスによれば処刑人はグラウキアス)、12歳のアレクサンドロス4世と母ロクサネが殺された。アレクサンドロスの帝国には名目上の君主もいなくなり、ディアドコイは自らの王国の宣言(前306-305年)へと向かった。", "46aa8fb2"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:0":{"b": ["アレクサンドロスがペルセポリスに到達し、都市と財宝がマケドニアの手に渡った", "c1dbaada"], "d": ["スサの後、ペルシア門を越えたアレクサンドロスは、330年1月末にペルセポリスに到達した。都市は抵抗せずに降伏した。ペルセポリスのアケメネス朝による所有はこの年で終わる(宮殿は330年5月に焼かれた)。", "de8726c8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:1":{"b": ["ペルセポリスの宮殿の焼却(4月)", "6e6cdfe0"], "d": ["アレクサンドロスは330年4月にペルセポリスでいくつかの宮殿建築を焼かせた。財宝を敵の手に渡さないため、またまだ唯一の君主ではなかったためという理由が挙げられる。クセルクセスの宮殿も焼けたことが考古学的に確認される。都市全体は放棄された。", "c22d037f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-07-01:0":{"b": ["ダレイオス3世がバクトリア総督ベッソスの部下に殺され、アケメネス朝が終わった", "bedcca87"], "d": ["エクバタナから逃れて東へ向かったダレイオス3世は、330年7月にパルティアでベッソスとその一派に傷つけられて置き去りにされ、死んだ。アレクサンドロスは遺体をペルセポリスへ送った。アケメネス朝の事実上の終焉である。", "dc8ceef3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-01:0":{"b": ["ガウガメラの戦い:アレクサンドロスがダレイオス3世の軍を決定的に破った", "a5b082d7"], "d": ["ガウガメラで、多数の戦車と騎兵からなるダレイオスの軍は、アレクサンドロスの左翼の守りを破って内側に突入した攻撃で崩れた。ダレイオスはまたも逃げた。この戦いはペルシア帝国の終わりを決定づけ、バビロンとスサが城門を開いた。", "b31c6746"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-22:0":{"b": ["アレクサンドロスがバビロンに入った。マザイオスが都市を引き渡し、バビロニア総督領はアレクサンドロスの手に渡った", "c8d2afb3"], "d": ["ガウガメラの後、バビロンの総督マザイオスは城門をアレクサンドロスに開いた。アレクサンドロスはマルドゥク神殿の修復を命じ、34日間この都市を用いた。バビロンはペルシアの支配からマケドニアの支配に移った。", "b84160e8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-12-15:0":{"b": ["アレクサンドロスがスサを奪い、ペルシアの財宝を手に入れた", "fbf417db"], "d": ["バビロンを発ったアレクサンドロスはスサに入った。総督アブリテスは都市と巨額の財宝を引き渡した。スサはマケドニアの東方遠征の財政的基盤となった。", "b65699b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0331-01-01:0":{"b": ["ティルス攻囲戦:アレクサンドロスが島の都市を堤道によって奪い、破壊した", "89ede146"], "d": ["ペルシア艦隊の基地であるティルス島を、アレクサンドロスは7か月で人工の堤道を築いて奪った。都市は略奪され、住民の大部分は殺されるか奴隷とされた。こうしてペルシアの海上勢力は崩壊し、エジプトへの道が開かれた。", "22842728"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0332-11-01:0":{"b": ["イッソスの戦い:アレクサンドロスがダレイオス3世を破り、ダレイオスは家族を残して逃げた", "3803fc30"], "d": ["狭い海岸平野でダレイオス3世の大軍はアレクサンドロスに敗れた。ペルシア王は家族と財宝を残して逃げた。イッソスの勝利により、シリアとフェニキアの沿岸、続いてエジプトがアレクサンドロスの手に渡った。", "a711a81e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0333-01-01:0":{"b": ["グラニコス川の戦い:アレクサンドロスがペルシアのサトラップたちを破った", "1aae30d4"], "d": ["マケドニア王アレクサンドロスは334年5月にアジアへ渡り、6月初めにグラニコスでペルシアのサトラップたちを破った。西アナトリアの門が開き、サルディスとイオニアの都市はアレクサンドロスに降伏した。", "8cc08bd9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0335-01-01:0":{"b": ["ダレイオス3世がペルシアの王位に就いた(アルセスの殺害)", "706f8a9f"], "d": ["宮廷官バゴアスがアルタクセルクセス4世を殺し、アルメニアのサトラップであったアルタシャタがダレイオス3世(コドマンノス)の名で王となった。336年10月にマケドニアでフィリッポスが殺され、アレクサンドロスが王位を継いだ。", "c082bdae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0337-01-01:0":{"b": ["アルタクセルクセス3世が死去し、アルタクセルクセス4世(アルセス)が即位した", "d38e2edc"], "d": ["アルタクセルクセス3世は338年夏に(ディオドロスの毒殺説にもかかわらず)自然死し、アルセスが即位した。エジプトとバビロンの反乱、マケドニア王フィリッポスのアナトリアへの準備は同じ時期に重なる。", "09f24497"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0344-01-01:0":{"b": ["アルタクセルクセス3世がシドンを奪って破壊し、テンネスの反乱が鎮圧された", "d1b533cc"], "d": ["シドン王テンネスのエジプトに支援されたペルシア反抗の反乱のさなか、アルタクセルクセス3世は都市を奪った。テンネスはペルシアに寝返り、都市は自らを焼き、多くの人が死んだ。フェニキアの諸都市は再びペルシアの支配下に入り、エジプト征服の道が開かれた。", "050b8e4e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0386-01-01:0":{"b": ["大王の和約(アンタルキダス):アナトリアのギリシア都市とキプロスがペルシアに委ねられた", "17e871ad"], "d": ["ペルシア王アルタクセルクセス2世が書き取らせた和約により、アジアのギリシア都市とキプロスはペルシアに属するものとされ、ギリシアの諸都市には自治が認められた。スパルタはペルシアの代弁者として和約を実施した。", "7bf00868"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0400-01-01:0":{"b": ["クナクサの戦い:小キュロスが兄アルタクセルクセス2世に敗れて死んだ", "90346087"], "d": ["小キュロスは、ギリシア人傭兵からなる「一万人」とともにバビロンへ進軍し、兄アルタクセルクセス2世にクナクサで敗れ、戦死した。「一万人」の黒海への帰還行軍は、クセノフォンの『アナバシス』に語られている。", "664d8d4f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:0":{"b": ["クセルクセスがヘレスポントスを渡った:テルモピュライとアテナイの陥落", "9bf22df1"], "d": ["クセルクセスは大軍を率い、テルモピュライでレオニダスのスパルタ・同盟軍を破ってアッティカに入った。アテナイは空にされ、アクロポリスとともに焼かれた。ペルシア軍はギリシア中央部まで進んだ。", "3b81a962"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:1":{"b": ["サラミスの海戦:ギリシア艦隊がペルシア艦隊を壊滅させた", "010e3aab"], "d": ["テミストクレス指揮のギリシア艦隊は、サラミスの狭い海峡でペルシア艦隊を破り、制海権を握った。クセルクセスは陸軍の大部分とともにアジアへ戻り、マルドニオスがギリシアに残った。", "f55ed3ca"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0483-01-01:0":{"b": ["バビロンでベール・シマンニとシャマシュ・エリバの反乱がクセルクセス1世により鎮圧された", "ebcef5a9"], "d": ["クセルクセス1世の治世の初めに、バビロンで二つの反乱(ベール・シマンニ、シャマシュ・エリバ)が起こった。クセルクセスは反乱を鎮圧し、バビロニア総督領を分割して都市の特権を縮小した。", "015c253c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0493-01-01:0":{"b": ["ラデの海戦:ペルシア艦隊がイオニア艦隊を破り、ミレトスが陥落した", "86396cf1"], "d": ["フェニキア人が主力のペルシア艦隊は、ラデでイオニア艦隊を壊滅させた。ミレトスは包囲されて破壊され、住民はメソポタミアへ追放された。イオニアの反乱は終わり、イオニアは再びペルシアの支配下に入った。", "b72ba00d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0497-01-01:0":{"b": ["イオニア人がサルディスを焼いた", "adf677bd"], "d": ["イオニア人とアテナイ・エレトリアの部隊は、ペルシアの総督領の中心サルディスへ進軍して都市を焼いた。ダレイオスはこれ以後、アテナイを罰する決意をした。この事件はマラトン遠征の理由である。", "32e33dce"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0498-01-01:0":{"b": ["イオニアの反乱が始まった:アリスタゴラスのナクソス遠征が失敗すると、イオニアのギリシア都市がペルシアに反旗を翻した", "aab8ff2f"], "d": ["ミレトスの僭主アリスタゴラスのナクソス遠征が挫折すると、イオニアの諸都市は僭主を倒し、アテナイとエレトリアに援助を求めた。この反乱はペルシア戦争の導火線である。", "7d70c2ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0512-01-01:0":{"b": ["ダレイオスがイストロス(ドナウ)を渡ってスキタイ遠征に出た:トラキアがペルシアの総督領に編入された", "a5891101"], "d": ["ダレイオスはボスポロスを橋でわたってトラキアに入り、ゲタイ人を従えてドナウを渡り、スキタイに対する遠征に出た。スキタイを破れなかったが、メガバゾスがトラキアとマケドニアの沿岸をペルシアの支配下に加えた。", "f464fbf8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-05-08:0":{"b": ["ダレイオスの軍がメディアの反乱者フラワルティシュ(プラオルテス)を破った", "4a9c4633"], "d": ["メディアで自らをキュアクサレスの血筋の王と宣言したフラワルティシュの軍は敗れた。フラワルティシュは逃亡中にラガイ(テヘラン近郊)で捕らえられ、拷問のうえ殺された。メディアは再びペルシアの州となった。", "efea5aea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-12-28:0":{"b": ["ダレイオスの将軍がマルギアナの反乱者フラダを破り、最後の大規模な蜂起が鎮圧された", "76e0ea1c"], "d": ["バクトリアのサトラップ、ダーダルシは、カラクム砂漠を300km行軍して、マルギアナの反乱者フラダを521年12月28日に破った。ダレイオスの治世第1年に、19の戦いですべての反乱が鎮められたことになる。", "5c0c9cfa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-03-11:0":{"b": ["ガウマータ(バルディヤ)がペルシアの王位を奪い、カンビュセスはエジプトからの帰途に死んだ", "1606d9c1"], "d": ["ベヒストゥン碑文によれば、神官ガウマータは自らをキュロスの子バルディヤ(スメルディス)と宣言して522年3月に即位し、カンビュセスはシリアで死んだ。ダレイオスと六人の貴族は522年9月29日にガウマータを殺した。", "f143e726"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-09-29:0":{"b": ["ダレイオスと六人の貴族がガウマータを殺し、ダレイオス1世がペルシアの王位に就いた", "08897d54"], "d": ["ダレイオスは六人の貴族の仲間とともに、メディアのシカヤウヴァティ要塞で偽バルディヤを殺した。ガウマータの死は、帝国の各地で蜂起を引き起こした。ダレイオスは1年のうちに19の戦いでこれらを鎮圧した。", "daebf974"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-12-18:0":{"b": ["ダレイオスがバビロンを奪還し、ニディントゥ・ベル(ネブカドネザル3世)が捕らえられ殺された", "365cdd51"], "d": ["ガウマータの死を受けて、ニディントゥ・ベルは自らをナボニドスの子でネブカドネザル3世と宣言し、バビロンをペルシアから切り離した。ダレイオスの軍は12月13日に膨らませた革袋でティグリス川を渡って反乱軍を撃破し、12月18日にバビロンが奪還され、ニディントゥ・ベルは殺された。スサでのエラムの蜂起はこの間に鎮圧された。", "4bd29dc6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0529-01-01:0":{"b": ["キュロスが死去し、息子のカンビュセスが即位した", "de69f4d5"], "d": ["キュロスは、ヘロドトスによればマッサゲタイの国での戦いで死んだ(クセノフォンによれば宮殿で死んだ)。死の知らせは530年12月にバビロンに届き、文書は「カンビュセスの第1年」と年代づけられた。カンビュセスはエジプトの征服によって帝国を拡大した。", "9900a295"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:0":{"b": ["キュロスの勅令:バビロン捕囚のユダヤ人がエルサレムへ帰還でき、神殿の再建が許された", "715eac6b"], "d": ["バビロンを奪ったキュロスは、捕囚された諸民族の神像を返還して故地へ戻ることを許した(キュロス・シリンダー)。トーラー(エズラ記1:1-4)もこの勅令をユダヤ人について別に伝えている。捕囚の民はエルサレムへ戻り、神殿を再建できるとされた。この地域はペルシアの総督領「イェフド」となった。", "a8c7f81c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:1":{"b": ["フェニキアの都市国家(ティルス、シドン、ビブロス)がペルシアの支配を受け入れ、ペルシア艦隊の中核となった", "d9f7f277"], "d": ["バビロンの陥落とともに、フェニキアの沿岸は「河の向こう」(エビル・ナリ)総督領のなかでペルシアの支配下に入った。フェニキアの艦隊はペルシアの海軍力の背骨となった。シドンとティルスは特権的な内政の権利を保った。", "bb0c17fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-01-01:0":{"b": ["オピスの戦い:キュロスがティグリス河畔でバビロニア軍を破った", "d91708c6"], "d": ["キュロスのペルシア軍はティグリス川のオピスでアッカドの軍を迎え撃って破った。バビロンの人々は退き、略奪と殺戮が行われた。この戦いは、2週間後のバビロン陥落への道を開いた。", "20739fbd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-10:0":{"b": ["シッパルが戦わずにペルシアの手に渡り、ナボニドスは逃げた", "47f6d3a5"], "d": ["オピスの戦いの後、タシュリトゥ月14日にシッパルは戦わずにキュロスの手に落ち、ナボニドスは逃げた。ペルシア軍は2日後にバビロンへ入る。", "5a23a85c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-12:0":{"b": ["ゴブリュアス(ウグバル)指揮のペルシア軍が戦わずにバビロンに入り、新バビロニアが終わった", "f67bf0e3"], "d": ["グティウムの総督ウグバル(ゴブリュアス)とキュロスの軍は、タシュリトゥ月16日に戦闘なしでバビロンに入り、ナボニドスは捕らえられた。エサギラでの儀礼は途切れなかった。キュロスはアラフサムヌ月3日(10月29日)に都市に入り、バビロン帝国はペルシアの覇権に移った。", "891c267b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-29:0":{"b": ["キュロスがバビロンに入った:バビロンの支配はアケメネス朝に移り、ゴブリュアスが総督に任命された", "fd45fa83"], "d": ["キュロスはアラフサムヌ月3日にバビロンに入り、住民に挨拶し、グバル(ゴブリュアス)を都市の総督とした。ナボニドスが都市に集めていたアッカドの神像は、キスリム月からアッダル月にかけて元の場所に戻された。息子のカンビュセスは王太子としてナブー神の儀礼に参加した。", "17d2bc46"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0546-01-01:0":{"b": ["クロイソスがハリュス川を渡ってプテリアを奪い、キュロスとのプテリアの戦いは決着なく終わった", "eee7aef1"], "d": ["クロイソスはデルフォイの神託を信じてハリュス川を渡り、プテリアを包囲してカッパドキアのシリア人を追い払った。キュロスとの激戦が決着しなかったため、クロイソスはサルディスに戻って同盟軍を集めたが、キュロスは奇襲の遠征で彼をティンブラで破り、サルディスは陥落した。", "419ac6ed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0551-01-01:0":{"b": ["ナボニドスがテイマー(アラビア)のオアシスに居を定めてバビロンに来ず、アキトゥ祭が行われなかった", "2ce93701"], "d": ["ナボニドスがテイマーのオアシスにいる間、王太子ベルシャザルは軍とともにアッカドで待機した。4月に王が来なかったためマルドゥクはバビロンに入らず、新年祭(アキトゥ)は行われなかった。これは、神殿の神官たちがナボニドスに反対してキュロスを支持した理由の一つとされる。", "d1e857db"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0555-01-01:0":{"b": ["ナボニドスがクーデタでバビロンの王位に就いた", "b7ab73ce"], "d": ["ネブカドネザルの死(562年)の後、アメル・マルドゥク、ネリグリッサル(559-556年)、短命のラバシ・マルドゥクが続いていた。ナボニドスは王家の出ではなかったが、556年にクーデタを起こした。月神シンへの格別な帰依は、マルドゥクの神官たちの不興を買った。", "6b2f9204"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0559-01-01:0":{"b": ["クロイソスがリディアの王位に就き、エフェソスとイオニアのギリシア都市に貢納を課した", "5544cfa4"], "d": ["クロイソスは父アリュアッテスの死後、エフェソスを、続いて他のイオニア、アイオリス、カリアのギリシア都市を貢納国とした。リディアは、アナトリア西部からハリュス川に至る単一の政治的統一体である。クロイソスの財宝とデルフォイへの奉納物は伝説となった。", "88136bde"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0584-01-01:0":{"b": ["ハリュス(クズルウルマク)の戦い:日食を受けてアリュアッテスとキュアクサレスが和睦し、ハリュスがリディアとメディアの国境となった", "9ababdd3"], "d": ["アリュアッテスとメディア王キュアクサレスの5年間の戦争は、昼間に起こった日食を受けて和睦で終わった。キリキア王シュエンネシスとバビロン王「ラビュネトス」が仲介した。ハリュス川は両王国の国境となり、メディアはアナトリアの内部にまで広がったとみなされた。", "ddab1c12"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:0":{"b": ["ネブカドネザルがティルスの包囲を開始し、包囲は13年続いた", "5b753ca0"], "d": ["ヨセフス(『アピオンへの反論』1.156)によれば、ネブカドネザルは王イトバアルの時代にティルスを13年間包囲した。都市は最終的に和平/臣従の取り決めで終わり、ティルスはバビロンの影響下に入りつつ、島の都市の独立した統治は続いた。", "0975583d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:1":{"b": ["エルサレムが破壊され、ソロモンの神殿が焼けた。ユダ王国は終わり、住民はバビロンへ連行された", "c9f78b2a"], "d": ["ゼデキアのバビロンに対する反乱を受けて、ネブカドネザルはエルサレムを二度目に奪って焼いた。神殿は破壊され、住民の大部分がバビロンへ連行された(バビロン捕囚)。ユダの独立国家としての存在は終わった。", "f53414ac"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0596-03-16:0":{"b": ["ネブカドネザルがエルサレムを奪い、王エホヤキンが捕虜として連行され、代わってゼデキアが立てられた", "55b14c31"], "d": ["バビロン軍は「ユダの都市」を包囲し、アッダル月2日に奪った。王エホヤキンは捕らえられてバビロンへ連行され、バビロンが選んだゼデキア(マッタニヤ)が代わりに据えられた。都市は初めてバビロンの支配下に入った。", "12a9d088"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0599-01-01:0":{"b": ["ウラルトゥの要塞が破壊され焼かれ、国家が崩壊した", "6be90688"], "d": ["カルミール・ブルールなどの要塞に見られる焼土層は、紀元前600年以前に、スキタイ/キンメリア人の侵入、メディア人、あるいは別の敵がウラルトゥを滅ぼしたことを示す。アッシリア史料が途絶えるため、最後の王ルサ3世以後の年代は不明である。ウラルトゥはしばらく後にアケメネス朝の総督領(アルミナ)となった。", "1e7ff200"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0603-12-01:0":{"b": ["ネブカドネザル2世がアシュケロンを奪い、その王を捕虜にして都市を廃墟とした", "7429839d"], "d": ["ネブカドネザルの第1年に「ハッティ国のすべての王」が彼に貢物を運んだが、アシュケロンだけが抵抗した。都市はキスリム月に奪われ、王は捕らえられ、都市は廃墟の丘に変えられた。", "a455db32"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0604-09-07:0":{"b": ["ナボポラッサルが死去し、ネブカドネザル2世がバビロンの王位に就いた", "bce88c5a"], "d": ["バビロン王ナボポラッサルは21年の治世の後、アブ月8日(605年8月15日)に死去した。カルケミシュで勝利したネブカドネザルは国へ戻り、ウルル月1日(605年9月7日)に即位した。4年にわたる遠征は、ハッティ国(シリア・パレスチナ)をバビロンに結びつけた。", "b519ffaa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:0":{"b": ["ハッラーンが陥落し、アッシュル・ウバリト2世がエジプトへ退いた", "b2d122c2"], "d": ["ニネヴェの陥落後、アッシリア最後の王アッシュル・ウバリト2世はハッラーンに退いていた。メディア人とバビロニア人がハッラーンへ進軍すると、アッシリアとエジプトの部隊は都市を捨ててユーフラテスの向こうへ退いた。ナボポラッサルはハッラーンを奪って略奪した。", "cb81464b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:1":{"b": ["アリュアッテスがリディアの王位に就き、キンメリア人をアナトリアから追って王国を拡大した", "160e291d"], "d": ["アリュアッテスは長い治世のなかで、キンメリア人を西アナトリアから一掃し、ミレトスと戦った。メディアとハリュス川の国境で対峙するまで、王国の境界をアナトリアの中央に進めた。", "54aee50b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0613-01-01:0":{"b": ["キュアクサレスとナボポラッサルがアッシュルの前で同盟条約を結んだ", "650f0e5a"], "d": ["メディア人がアッシュルを奪ったとき、遅れて到着したバビロン王ナボポラッサルは、都市の近くでメディア王と会って同盟を結んだ。ベロッソスによれば、この絆はネブカドネザルとキュアクサレスの娘アミュティスとの婚姻で固められた。", "450ae215"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0624-01-01:0":{"b": ["キュアクサレス(ウマキシュタル)がメディアの王位に就いた", "67896ea0"], "d": ["ヘロドトスの伝承によれば、キュアクサレスは40年間統治し、メディアを統一してアッシリアに対する遠征に出た。バビロンとの同盟(614年)とニネヴェの陥落(612年)は彼の治世のことである。メディアはこの時期に最大の版図に達した。", "4094aac8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0630-01-01:0":{"b": ["アッシュルバニパルが死去し、アッシリアで王位争いとバビロンの蜂起が始まった", "dbe19d8c"], "d": ["アッシュルバニパルの死は、アッシリアを二人の後継者の間で分裂した状態に残した。バビロンの総督たちはシン・シュム・リシルとシン・シャル・イシュクンに反旗を翻した。帝国は10年のうちに崩壊へ向かい始めた。", "9537e9f3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0644-01-01:0":{"b": ["アッシュルバニパルがスサを破壊し、新エラム王国が崩壊した", "cb341293"], "d": ["エラムがバビロンとともにアッシリアに反乱を起こした罰として、アッシュルバニパルはスサを奪って略奪し、神殿を破壊して神像をニネヴェへ運んだ。エラムは半独立の公国群となってペルシア/アンシャンの影響下に入った。", "327f1322"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0647-01-01:0":{"b": ["バビロンがシャマシュ・シュム・ウキンの反乱の後、アッシュルバニパルに屈した", "d6964932"], "d": ["アッシュルバニパルの弟でバビロン王のシャマシュ・シュム・ウキンは、652年にアッシリアに反旗を翻した。エラムとアラブの同盟者が一時的な支援を与えた。4年続いた戦争はバビロンの陥落で終わり、シャマシュ・シュム・ウキンは死んだ。", "b038173f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0651-01-01:0":{"b": ["キンメリア人がサルディスを略奪し、ギュゲスが死んだ", "950e5f80"], "d": ["キンメリア人の侵入は、ゴルディオン(696/695年)の後、リディアにも及び、サルディスの下町を略奪した。アッシリア史料は、リディア王ググ(ギュゲス)がキンメリア人に対抗してアッシリアの援助を求めたことを伝える。ギュゲスはこれらの戦いの最中か後に死んだ。", "93736177"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0652-01-01:0":{"b": ["ティル・トゥバ/ウライの戦い:アッシュルバニパルがエラム王テウマンを破って殺した", "177e87cf"], "d": ["アッシュルバニパルは、エラム王テウマンをスサ近郊のウライ(カルン/カルヘ)河畔で破って殺した。首はニネヴェへ運ばれた。この戦いは、エラムがアッシリア・バビロン間の争いで果たした役割の終わりを用意した。", "3aa28a86"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0663-01-01:0":{"b": ["アッシュルバニパルがテーベを略奪した", "179269c7"], "d": ["エサルハドンの死後、エジプトでクシュ人の反乱がタヌトアメンのもとで再燃すると、アッシュルバニパルは上エジプトに入ってテーベを略奪した。アッシリアはエジプトを実質的に保持することに苦しみ、短期間で退いた。", "c292bcf0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0676-01-01:0":{"b": ["エサルハドンがシドンを破壊し、カル・エサルハドンの名で再建した", "bd713ae6"], "d": ["シドン王アブディ・ミルクティがアッシリアに反乱を起こすと、エサルハドンは都市を破壊し、王を斬首して殺し、その跡地にカル・エサルハドン(「エサルハドンの港」)というアッシリアの州都を建設した。", "2a506319"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0684-01-01:0":{"b": ["ギュゲスがカンダウレスを倒してメルムナス朝を創始した", "37e46a38"], "d": ["ヘロドトスによれば、ギュゲスは近衛兵のとき王カンダウレスを倒してリディアの王位を奪い、メルムナス朝を創始した。フリュギアがキンメリア人の攻撃で崩壊した後、リディアは西アナトリアの主要勢力になり始めた。", "e477b6b5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0688-01-01:0":{"b": ["センナケリブがバビロンを破壊し、神殿を略奪して、ユーフラテスの水を都市に流し込んだ", "82265d98"], "d": ["バビロンの度重なる反乱を受けて、センナケリブは都市を奪って破壊し、マルドゥクの像を持ち去り、運河の水を都市に流し込んだ。バビロンはエサルハドンの修復まで半世紀にわたり荒廃したままだった。この破壊は、アッシリアのバビロン政策のなかで最も苛烈な措置である。", "e4312fee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:0":{"b": ["センナケリブがユダに侵攻し、ラキシュを奪ってエルサレムを包囲した", "dc11fa2d"], "d": ["ヒゼキヤのアッシリアに対する反乱を鎮圧したセンナケリブは、ユダの46の都市を奪い、ラキシュを征服し、エルサレムを包囲した。ヒゼキヤは重い貢納を支払って都市を救った。ニネヴェのラキシュ浮彫は、この遠征を描いている。", "ebc2ce02"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:1":{"b": ["センナケリブがシドンを奪い、王ルリがキプロスへ逃れた", "41bb1358"], "d": ["センナケリブは701年にフェニキアの諸都市を従えた。シドン王ルリ(エルライオス)はキプロスへ逃れ、シドンとティルスの属邑はアッシリアの手に渡った。ユダ遠征の前に、これらの征服によって西の沿岸が確保された。", "3b2c6518"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0704-01-01:0":{"b": ["サルゴン2世がタバルで戦死し、センナケリブが即位した", "2f6ae581"], "d": ["サルゴン2世は、アナトリアでタバルの王グルディに対する遠征中に戦死し、遺体は回収できなかった。息子のセンナケリブは宮廷をニネヴェに移した。父の都ドゥル・シャルキンは放棄され、多くの州が蜂起した。", "21ee2771"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0711-01-01:0":{"b": ["サルゴン2世がメリド(マラティヤ)を奪い、グンジナヌが追放された", "3ef6a5c9"], "d": ["メリド(マラティヤ)の王グンジナヌは、タバルおよびウラルトゥと協力したためサルゴンに敗れ、その王国はアッシリアの州となった。こうしてアナトリア東部における新ヒッタイトの支配は終わった。", "281f75fd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0713-01-01:0":{"b": ["サルゴン2世がウラルトゥに入った:ルサ1世が敗れ、ムサシルが略奪されてハルディの像が奪われた", "38992d24"], "d": ["サルゴンの第8次遠征はウルミア湖の周辺から南へウラルトゥを略奪した。ムサシルのハルディ神殿は掠奪された。王ルサ1世は大敗を前に自ら命を絶った(伝承)。ウラルトゥは二度とアッシリアに対して大規模な企てをなしえなかった。", "7d05af4c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0716-01-01:0":{"b": ["サルゴン2世がカルケミシュを奪い、ピシリスの王国はアッシリアの州となった", "cfcc3ee4"], "d": ["カルケミシュ王ピシリスはアッシリアに対してミダス(ミタ)と同盟を結ぼうとした。サルゴンは都市を奪って住民を追放した。カルケミシュの150年にわたる独立は終わり、ユーフラテスの国境はアッシリアの手に渡った。", "87f1f2e6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0719-01-01:0":{"b": ["サルゴン2世がハマト(ハマ)を破り、カルカルでヤウビディを殺して王国を州とした", "aeca8edc"], "d": ["ハマト王ヤウビディは、サルゴンに対して結成されたシリア・パレスチナの連合の首謀者だった。サルゴンはカルカルで彼を破って都市を破壊し、ハマトはアッシリアの州に変えられた。", "70e2d509"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0732-01-01:0":{"b": ["ティグラト・ピレセル3世がガリラヤとギレアドをイスラエルから奪い、アッシリアの州とした", "0b59ead2"], "d": ["ペカのイスラエルがダマスクスとともにアッシリアに歯向かうと、ティグラト・ピレセル3世は北イスラエル(ガリラヤ、ギレアド、メギド周辺)をアッシリアの州に変えて住民を追放した。ペカの後にはホシェアが立った。イスラエル王国はサマリアとその周辺の山地に縮小された。", "28d3a30e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0733-01-01:0":{"b": ["ティグラト・ピレセル3世がガザを奪い、パレスチナの沿岸がアッシリアの支配下に入った", "1c89131f"], "d": ["ティグラト・ピレセルはパレスチナの沿岸地帯へ向かい、ガザ王ハヌヌをエジプトへ逃げさせて都市を支配下に置いた。パレスチナの都市国家は、その後の数年でアッシリアの従属的な帯状地帯に変わった。", "ff623a4d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0742-01-01:0":{"b": ["ティグラト・ピレセル3世がアルパド近郊でウラルトゥ王サルドゥリ2世を破った", "7478a232"], "d": ["サルドゥリ2世がシリアの諸国を独立へ向かわせようとした試みは、ティグラト・ピレセル3世の勝利に終わった。ウラルトゥはシリアでの影響力を失い、アッシリアにはアナトリアとシリアに対する競争相手が残らなかった。", "b851f23b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0744-01-01:0":{"b": ["ティグラト・ピレセル3世が即位し、アッシリアの州制度が確立した", "b5889059"], "d": ["カルフで反乱により即位したティグラト・ピレセル3世は、従属王国に代えてアッシリアの総督を置き、州制度を定着させた。バビロンを同君連合で結び、ダマスクス、ガザ、イスラエルへ遠征した。のちの帝国(バビロニア、ペルシア、セレウコス朝)が用いた統治の仕組みはここに由来する。", "7deb8187"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0795-01-01:0":{"b": ["アダド・ニラリ3世がダマスクス王マリを破り、貢納を得た", "3e01dbfa"], "d": ["アダド・ニラリ3世はダマスクス王マリ(バル・ハダド)を破って多額の貢納を得た。アラム・ダマスクスの内部の力は弱まり、イスラエルはしばらく一息ついた。", "c5c0a66d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0809-01-01:0":{"b": ["ミヌアがウラルトゥをヴァン湖からアラス渓谷とウルミア湖にまで広げた", "d77231e4"], "d": ["ミヌアとその子アルギシュティ1世の時代に、ウラルトゥはヴァン湖を中心とする国から、アラスとウルミア湖の周辺に至る高地全体を含む王国に変わった。トゥシュパ(ヴァン)は新たな入植と灌漑工事によって拡張された。", "289fc554"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0839-01-01:0":{"b": ["モアブ王メシャがイスラエルからの独立を宣言した(メシャ碑文)", "e9c264b2"], "d": ["メシャ碑文は、モアブ王メシャのイスラエルの宗主権からの解放と、オムリ王朝に対して得た勝利を語る。トーラーと碑文はともに、オムリ王朝が弱体化した時期を示している。", "ffefe5fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0840-01-01:0":{"b": ["シャルマネセル3世がハザエルを破ってダマスクスを包囲し、イスラエル王イエフが貢納を納めた", "93aacc56"], "d": ["シャルマネセル3世はアラム・ダマスクス王ハザエルをシャニル(ヘルモン)山で破ってダマスクスを包囲した。イスラエル王イエフは黒色オベリスクにアッシリアへ貢納を捧げる姿で描かれている。カルカルの連合は解体し、アッシリアは西方の覇権勢力となった。", "2992ec0c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0852-01-01:0":{"b": ["カルカルの戦い:シャルマネセル3世がダマスクス・ハマト・イスラエルの連合軍と対戦した", "9a736e92"], "d": ["シャルマネセル3世は、ダマスクス王ハダドエゼル(アダド・イドリ)、ハマト王イルフレニ、イスラエル王アハブを含む12王の連合軍とカルカルで戦った。アッシリアの文書は勝利を主張するが、進軍をやめざるをえなかった。連合は数年にわたりアッシリアを食い止めた。", "524874c7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0857-01-01:0":{"b": ["シャルマネセル3世がウラルトゥ(アラメ)へ遠征を開始し、ウラルトゥが初めてアッシリア史料に現れた", "375ce993"], "d": ["シャルマネセル3世は治世の初めの数年に、王アラメのウラルトゥの地へ進軍した。アッシリアの年代記は、この遠征で初めてウラルトゥを「ウラルトゥの国」の名で記す。後の数世紀にこの地域でアッシリアの主要な競争相手となる国家の、最初の年代づけられた記録である。", "759a75b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0876-01-01:0":{"b": ["アッシュルナツィルパル2世がユーフラテスを渡り、カルケミシュと新ヒッタイト/アラムの諸国から貢納を得た", "5e385948"], "d": ["アッシュルナツィルパル2世は西方遠征でユーフラテスを渡り、カルケミシュ、パティナ、フェニキアの沿岸に達して貢納を集めた。この遠征は、新ヒッタイト・アラムの都市国家がアッシリアに結びつけられていく過程の始まりである。", "8432c2ea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0878-01-01:0":{"b": ["アッシュルナツィルパル2世がカルフ(ニムルド)をアッシリアの新しい首都とした", "fbb17248"], "d": ["アッシュルナツィルパル2世は小さな町だったカルフを、4万7000人の労働者で大首都に変えた。アッシュルの6倍の広さの都市に北西宮殿が築かれた。カルフは706年までアッシリアの首都であり続けた。", "5a0f00b6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0879-01-01:0":{"b": ["オムリがサマリアを首都とし、モアブを奪った", "e060c4b7"], "d": ["オムリはイスラエルの最初の本格的な国家を築いた。ヨルダン川の東(モアブを含む)を征服し、国境の要塞を強化して、サマリアを新首都とした。息子アハブはシドン王エトバアルの娘イゼベルと結婚し、イスラエルをフェニキアの交易に結びつけた。", "14f7df9d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0910-01-01:0":{"b": ["アダド・ニラリ2世が即位し、新アッシリアの復興が始まった", "e6887ba9"], "d": ["約1世紀半続いた衰退の後、アダド・ニラリ2世はアッシリアの領土を再び集め始め、アラム人とバビロンの国境へ遠征した。後継者のアッシュルナツィルパル2世とシャルマネセル3世の時代に、新アッシリア帝国が誕生した。", "beab377b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0929-01-01:0":{"b": ["ソロモンの王国が分裂し、ヤロブアム1世が北にイスラエル王国を建てた", "cfbbc025"], "d": ["トーラーによれば、ソロモンの死後、息子レハブアムの増税が北の十部族の離脱を招いた。ヤロブアムが王に選ばれ、ティルツァを首都とした。南ではユダがダビデ王朝のもとで存続した。二つの国の別個の歴史が始まる。", "7e2e066d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1099-01-01:0":{"b": ["ティグラト・ピレセル1世が西へ進軍し、地中海沿岸のフェニキアの都市から貢納を得た", "0b2822b7"], "d": ["ティグラト・ピレセル1世はレバノンの森とアルワド、ビブロス(ジュバイル)、シドンなどの港に達して貢納を集め、地中海で船による航行を行った。ヒッタイトの崩壊後、西方に彼を止める勢力がなかったため、これらの遠征はアッシリアの西方志向の始まりとなる。", "60dc7824"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1109-01-01:0":{"b": ["ネブカドネザル1世(イシン第2王朝)がエラムへ進軍し、マルドゥクの像を取り戻した", "3c551c03"], "d": ["イシン第2王朝のネブカドネザル1世はエラムへ進軍し、クティル・ナフンテが持ち去ったマルドゥクの像をバビロンに取り戻した。この勝利はバビロンの歴史で「マルドゥクの帰還」として記憶され、マルドゥク崇拝を中心的なものにした。", "fdd1a6a4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1157-01-01:0":{"b": ["シュトルク・ナフンテがバビロニアを略奪し、ハンムラビとナラム・シンの碑をスサへ持ち去った", "3d499fcc"], "d": ["中期エラムの王シュトルク・ナフンテはバビロンを襲ってシッパルなどの都市を略奪した。ハンムラビ法典碑やナラム・シンの戦勝碑などの戦利品はスサへ運ばれた。息子のクティル・ナフンテは紀元前1155年にカッシートの王朝を終わらせた。", "2179c21e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1174-01-01:0":{"b": ["カルケミシュでクジ・テシュブが「大王」の称号でヒッタイトの遺産を継いだ", "0bda7a64"], "d": ["ハットゥシャの崩壊の後、カルケミシュ王国はヒッタイト王家の一支流の手で存続した。クジ・テシュブは自らを「大王」と宣言した。カルケミシュ、マラティヤ(メリド)、ハマなどのルウィ・アラムの都市国家が「新ヒッタイト」の世界を形づくった。", "214de0bd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1179-01-01:0":{"b": ["ハットゥシャが焼かれて放棄され、ヒッタイト帝国が崩壊した", "64d58b6b"], "d": ["ハットゥシャの都市は最後のヒッタイト王シュッピルリウマ2世の時代に焼かれて放棄された。飢饉、内紛、海の民をめぐる後期青銅器時代の崩壊の一部である。ヒッタイト国家は、カルケミシュやマラティヤなどの新ヒッタイトの都市国家に取って代わられた。", "34ee5436"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1224-01-01:0":{"b": ["アッシュル王トゥクルティ・ニヌルタ1世がバビロンを征服し、マルドゥクの像をアッシュルへ持ち去った", "2cc39251"], "d": ["トゥクルティ・ニヌルタ1世(前1243-1207年ごろ)はカッシートの王カシュティリアシュ4世を破ってバビロンを奪い、城壁を破壊させ、マルドゥクの像をアッシュルへ運んだ。バビロンは約7年間アッシュルの支配下に置かれ、アッシリアは中世以前の最強国となった。", "8abcb249"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1259-01-01:0":{"b": ["シャルマネセル1世がカルフ(ニムルド)の都市を建設した", "e0bf279a"], "d": ["シャルマネセル1世はティグリス河畔にカルフを建設した。都市は883年にアッシュルナツィルパル2世によって再建され、アッシリアの首都となる。", "8a213755"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1269-01-01:0":{"b": ["シャルマネセル1世がハニガルバトを併合し、ミタンニが消滅した", "88620feb"], "d": ["ハニガルバト王シャットゥアラ2世の反抗を鎮めたシャルマネセル1世は、国を直接アッシリアに併合し、住民を追放した。ミタンニ国家は、ヒッタイトとアッシリアの相次ぐ打撃で歴史の舞台から消えた。", "c6c8615e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1274-01-01:0":{"b": ["ウンタシュ・ナピリシャがドゥル・ウンタシュ(チョガ・ザンビール)の都市とジッグラトを建設した", "117fbc13"], "d": ["中期エラムの王ウンタシュ・ナピリシャは、スサの近くに神インシュシナクのためのジッグラトをもつ聖都を建設した。都市は未完成に終わったが、200年以上利用された。チョガ・ザンビールは、イランで最も保存状態のよいジッグラトである。", "fe8afd09"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1294-01-01:0":{"b": ["アダド・ニラリ1世がハニガルバト(ミタンニの残存勢力)を破って従属させた", "1adb5969"], "d": ["アッシュル・ウバリト1世の孫アダド・ニラリ1世は、ヒッタイトに打撃を与えられたミタンニの残存であるハニガルバト王国を破って従属させた。次の王シャルマネセル1世の時代に、この国はアッシリアの州に変えられた。アッシリアはユーフラテスまで広がった。", "24941786"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1317-01-01:0":{"b": ["ムルシリ2世がアルザワ(西アナトリア)を破って分割した", "4a204e42"], "d": ["ムルシリ2世は治世の初めに、西アナトリアの強力なアルザワ連合を破って小王国に分け、ヒッタイトの従属国とした。西アナトリアにおけるヒッタイトの国境は、エーゲ海の沿岸に近づいた。", "c2f9977c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1327-01-01:0":{"b": ["シュッピルリウマが息子たちをカルケミシュとアレッポの王国の首長に任じた", "1c5bc8b3"], "d": ["シュッピルリウマは征服したシリアを、ヒッタイト王家の「王たち」の手で統治した。カルケミシュとアレッポは息子たちに与えられた。カルケミシュの王位代行はヒッタイトの崩壊後もおよそ500年存続することになる。", "40eeaf84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1344-01-01:0":{"b": ["シュッピルリウマ1世がミタンニ(トゥシュラッタ)を破り、アレッポとカルケミシュを奪った:北シリアがヒッタイトの手に渡った", "52f9627a"], "d": ["シュッピルリウマはミタンニ王トゥシュラッタを破り、カルケミシュとアレッポを含むシリアの都市を奪った。ミタンニ領の西部はヒッタイト帝国に編入された。エジプトのアクエンアテンの時代の内政問題が、この拡張を容易にした。", "c80de115"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:0":{"b": ["カッシートのバビロンが、アマルナ外交でエジプトと対等の大国として位置づけられた", "5e7b31a2"], "d": ["カッシートの王カダシュマン・エンリル1世とブルナ・ブリアシュ2世は、エジプトのファラオと婚姻と贈り物の外交を行う「大王」の仲間に加わっていた。アマルナ文書は、この仲間の構成員をエジプト、バビロン、ミタンニ、ハッティ、アッシュルと列挙している。", "8ecd665d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:1":{"b": ["シュッピルリウマ1世がヒッタイトの王位に就き、新王国時代が始まった", "58b301b7"], "d": ["シュッピルリウマ1世は、ヒッタイト新王国の創始者であり、職業的な戦車軍の創設者である。35年の治世はヒッタイトをアナトリアからシリアに至る帝国に変えた。", "72c7f3af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1362-01-01:0":{"b": ["アッシュル・ウバリト1世がミタンニの宗主権から脱し、アッシリアは独立して「大王」となった", "5f280058"], "d": ["ミタンニの従属国であったアッシュルは、アッシュル・ウバリト1世の時代に、ヒッタイトがミタンニに与えた打撃を利用して独立を得た。王はエジプトのファラオに「大王」の称号で書簡を送った。これは中期アッシリア時代の始まりである。", "690fb956"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1399-01-01:0":{"b": ["ミタンニ・エジプト同盟:アルタタマ1世とトトメス4世の和平、ミタンニの王女がエジプトへ嫁いだ", "017f13d2"], "d": ["敵対関係の後、ミタンニ王アルタタマ1世はエジプトのファラオと和平を結び、娘をエジプトへ送った。同盟は、ヒッタイトの脅威に対抗して北シリアにエジプトとミタンニの均衡をつくり、アマルナ時代の外交を準備した。", "72df719d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1499-01-01:0":{"b": ["ミタンニ(ハニガルバト)王国がハブール・ユーフラテス地域に成立した", "04920d91"], "d": ["フルリ・ミタンニ王国は、古バビロニアの崩壊とヒッタイトの衰退がつくった空白のなかで、上メソポタミアに興った。首都はワシュカンニであった。王国は数十年のうちにアッシュルと北シリアを従属させた。", "c6aa0237"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1524-01-01:0":{"b": ["テリピヌが即位して勅令を発し、キッズワトナとの条約で関係が定められた", "e1f0895b"], "d": ["テリピヌは、継承に関する規定を含む勅令でヒッタイトの法を再建した。キッズワトナと結ばれた条約は、この国を従属国ではなく対等の相手として認めた。ヒッタイト古王国はこの勅令で終わる。", "47b927f1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1569-01-01:0":{"b": ["カッシート王朝がアグム・カクリメの時代にバビロンを再び統合し、マルドゥクの像がヒッタイトの捕囚から戻った", "0d525e02"], "d": ["ヒッタイト王ムルシリ1世によるバビロン略奪(紀元前1595年)の後、都市にはカッシート王朝が君臨した。伝承は、アグム・カクリメがヒッタイトからマルドゥクの像を取り戻したと語る。カッシートは短期間のうちにバビロンの文化を受け入れ、約4世紀続く王朝を築いた。", "d91fcc1e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1589-01-01:0":{"b": ["ムルシリ1世が暗殺され、ヒッタイト王国は内紛で弱体化した", "fa5a6ea9"], "d": ["バビロンからの帰途、ムルシリ1世は義弟ハンティリとジダンタに殺された。王位争いと新たなフルリ/ミタンニの勢力のため、王国は半世紀にわたり弱いままだった。テリピヌが秩序を打ち立てたのは紀元前1525年ごろである。", "90711b8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1599-01-01:0":{"b": ["ムルシリ1世がアレッポ(ヤムハド)を奪って破壊した", "78c81e82"], "d": ["ハットゥシリの孫で後継者のムルシリ1世は、数十年にわたり抵抗していたアレッポ王国を奪って破壊した。ヤムハドの終焉は北シリアにおけるヒッタイトの優位をもたらし、ムルシリのバビロン遠征への道を開いた。", "327a9d55"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1629-01-01:0":{"b": ["ハットゥシリ1世がトロスを越えて北シリアへ遠征した:アララハが破壊され、アレッポ(ヤムハド)王国が攻撃された", "92b0d44b"], "d": ["ハットゥシリ1世(前1650-1620年ごろ)はトロスを越えて北シリアへ遠征した。アララハは破壊され、アレッポ(ヤムハド)王国は攻撃されたが、アレッポは奪われなかった。キッズワトナ(キリキア)の併合はこの遠征によるものではない。キッズワトナはその後ハッティとミタンニの間を行き来し、ヒッタイトによる併合は新王国の初めのことである。", "cf12effe"]}
});
